_TEST_CLOSED_WORLD_ATTESTATION_ID = "11111111-1111-4111-8111-111111111111"


def _closed_world_attestation_memory(
    *,
    members: list[str] | None = None,
    payload_overrides: dict | None = None,
    memory_overrides: dict | None = None,
) -> dict[str, str]:
    payload = {
        "attestation_id": _TEST_CLOSED_WORLD_ATTESTATION_ID,
        "subject": "employment_history",
        "set_key": "employers",
        "set_semantics": "complete_membership",
        "members": list(members if members is not None else ["Example Labs"]),
        "complete_through": "2026-07-31T12:34:56.123456",
        "membership_answer": "Yes",
        "absence_answer": "No",
        "exhaustive": True,
        "provenance": "explicit_user_attestation",
        "source": "profile_attestation_api",
        "version": 1,
    }
    payload.update(payload_overrides or {})
    unsigned_value = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    payload["attestation_sha256"] = hashlib.sha256(
        unsigned_value.encode("utf-8")
    ).hexdigest()
    attestation_id = str(payload["attestation_id"])
    memory = {
        "key": f"closed_world_attestation.{attestation_id}",
        "value": json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
        "source": (
            "user_profiles.profile_json.closed_world_attestations."
            f"{attestation_id}"
        ),
    }
    memory.update(memory_overrides or {})
    return memory


def test_type_read_back_reports_whitespace_only_difference() -> None:
    action = {"text": "copy me "}
    result = {"active_value": "copy me", "active_value_matches_expected": False}
    note = extension_run._type_value_mismatch_feedback(action, result)
    assert "except whitespace" in note and "'copy me '" in note
    exact = {"active_value": "copy me ", "active_value_matches_expected": True}
    assert extension_run._type_value_mismatch_feedback(action, exact) == ""
    masked = {"active_value": "[REDACTED]", "active_value_redacted": True, "active_value_matches_expected": True}
    assert extension_run._type_value_mismatch_feedback(action, masked) == ""


def test_secret_classifier_keeps_rendered_control_text_separate_from_value() -> None:
    control = {
        "index": 7,
        "tag": "input",
        "type": "tel",
        "text": "Phone",
        "value": "",
    }

    evidence = extension_run._secret_classifier_control_evidence(control)

    assert evidence["text"] == "Phone"
    assert evidence["browser_value_present"] is False


def test_secret_classifier_never_projects_editable_text_as_a_label() -> None:
    secret = "FAKE_TEST_SECRET_MUST_NOT_REACH_CLASSIFIER"
    control = {
        "index": 1,
        "tag": "div",
        "contenteditable": True,
        "text": secret,
        "value": "",
    }
    page = {
        "viewport_text": f"Recovery phrase {secret}",
        "controls": [control],
    }

    control_evidence = extension_run._secret_classifier_control_evidence(control)
    page_evidence = extension_run._secret_classifier_page_evidence(
        page,
        control=control,
    )

    assert "text" not in control_evidence
    assert secret not in json.dumps(page_evidence)


