def test_vision_observation_artifacts_retain_model_screenshot_and_raw_evidence(tmp_path) -> None:
    settings = extension_run.get_settings()
    previous_root = settings.artifact_root
    settings.artifact_root = tmp_path
    try:
        screenshot = b"model-visible-jpeg-bytes"
        page_evidence = {
            "viewport_text": "Apply for this role",
            "controls": [{"index": 1, "role": "textbox", "text": "Email", "value": "candidate@example.com"}],
        }
        retained = extension_run._persist_vision_observation_artifacts(
            90210,
            step=7,
            shot={
                "ok": True,
                "image": base64.b64encode(screenshot).decode(),
                "url": "https://example.test/apply",
                "width": 1120,
                "height": 753,
                "page_evidence": page_evidence,
            },
            image_b64=base64.b64encode(screenshot).decode(),
            view={
                "url": "https://example.test/apply",
                "title": "Apply",
                "width": 1120,
                "height": 753,
                "scroll_y": 400,
                "scroll_height": 2200,
            },
        )

        assert retained["ok"] is True
        assert retained["step"] == 7
        assert retained["screenshot_sha256"]
        screenshot_path = Path(retained["screenshot_path"])
        observation_path = Path(retained["observation_path"])
        assert screenshot_path.read_bytes() == screenshot
        observation = json.loads(observation_path.read_text(encoding="utf-8"))
        assert observation["page_evidence"] == page_evidence
        assert observation["screenshot"]["sha256"] == retained["screenshot_sha256"]
        assert hashlib.sha256(observation_path.read_bytes()).hexdigest() == retained["observation_file_sha256"]
        manifest_lines = Path(retained["manifest_path"]).read_text(encoding="utf-8").splitlines()
        assert json.loads(manifest_lines[-1])["observation_path"] == retained["observation_path"]
    finally:
        settings.artifact_root = previous_root


def test_vision_model_input_artifacts_retain_exact_sent_image_and_sanitized_envelope(tmp_path) -> None:
    settings = extension_run.get_settings()
    previous_root = settings.artifact_root
    settings.artifact_root = tmp_path
    try:
        model_screenshot = b"reduced-model-visible-jpeg"
        view = {
            "url": "https://example.test/workflow",
            "title": "Workflow",
            "width": 800,
            "height": 538,
            "scroll_y": 0,
            "scroll_height": 1600,
        }
        context = {
            "goal": "Complete the reversible steps",
            "human_answers": [{"question": "Verification code", "answer": "Code 482193"}],
            "page_evidence": {
                "viewport_text": "Continue",
                "controls": [{"index": 1, "role": "button", "text": "Continue"}],
            },
        }
        retained = extension_run._persist_vision_model_input_artifacts(
            90211,
            step=3,
            payload_mode="reduced_after_timeout",
            image={
                "media_type": "image/jpeg",
                "data": base64.b64encode(model_screenshot).decode(),
            },
            view=view,
            context=context,
            source_observation_ref={
                "step": 2,
                "observation_path": "source-observation.json",
                "screenshot_sha256": "source-sha",
            },
            source_observation_reused=True,
        )

        assert retained["ok"] is True
        assert retained["payload_mode"] == "reduced_after_timeout"
        assert retained["source_observation_reused"] is True
        assert Path(retained["model_screenshot_path"]).read_bytes() == model_screenshot
        record = json.loads(Path(retained["model_input_path"]).read_text(encoding="utf-8"))
        assert record["view"] == view
        assert record["source_observation_ref"]["screenshot_sha256"] == "source-sha"
        assert record["model_screenshot"]["sha256"] == retained["model_screenshot_sha256"]
        assert record["model_input"]["sha256"] == retained["model_input_sha256"]
        assert record["model_input"]["envelope_sha256"] == retained["model_input_envelope_sha256"]
        assert hashlib.sha256(Path(retained["model_input_path"]).read_bytes()).hexdigest() == retained["model_input_file_sha256"]
        assert retained["retention_boundary"] == "model_client_input_before_provider_serialization"
        assert "[REDACTED_OTP]" in json.dumps(record["model_input"]["envelope"])
        assert "482193" not in json.dumps(record["model_input"]["envelope"])
        manifest_lines = Path(retained["manifest_path"]).read_text(encoding="utf-8").splitlines()
        assert json.loads(manifest_lines[-1])["model_input_path"] == retained["model_input_path"]
    finally:
        settings.artifact_root = previous_root


def test_upload_document_context_uses_authoritative_base_not_newest_unrelated_pdf(tmp_path: Path) -> None:
    init_db()
    current_pdf = tmp_path / "current-real.pdf"
    current_pdf.write_bytes(b"%PDF-1.4\ncurrent\n")
    with SessionLocal() as db:
        user = models.User(email=f"vision-document-selection-{uuid.uuid4()}@example.com", name="Document Selection")
        db.add(user)
        db.flush()
        stale = models.Resume(user_id=user.id, name="stale-demo.pdf", base_resume_text="stale", is_base=True)
        current = models.Resume(user_id=user.id, name="current-real.pdf", base_resume_text="current", is_base=True)
        db.add_all([stale, current])
        db.flush()
        current_artifact = models.ResumeArtifact(
            resume_id=current.id,
            artifact_type="BASE_PDF",
            pdf_path=str(current_pdf),
            compile_status="SUCCESS",
        )
        db.add(current_artifact)
        db.flush()
        posting = models.JobPosting(user_id=user.id, url="https://example.test/job")
        db.add(posting)
        db.flush()
        stale_version = models.ResumeVersion(job_posting_id=posting.id, resume_id=stale.id, tailored_latex="stale")
        db.add(stale_version)
        db.flush()
        db.add(
            models.ResumeArtifact(
                resume_id=stale.id,
                resume_version_id=stale_version.id,
                artifact_type="TAILORED_PDF",
                pdf_path="newer-but-unrelated.pdf",
                compile_status="SUCCESS",
            )
        )
        db.flush()

        documents = extension_run._upload_documents_for_user(db, user.id)

        assert documents["resume"]["artifact_id"] == current_artifact.id
        assert documents["resume"]["resume_id"] == current.id
        assert documents["resume"]["resume_version_id"] is None
        assert documents["resume"]["artifact_type"] == "BASE_PDF"


def test_upload_document_context_rejects_missing_selected_file_without_fallback(tmp_path: Path) -> None:
    init_db()
    older_pdf = tmp_path / "older-real.pdf"
    older_pdf.write_bytes(b"%PDF-1.4\nolder\n")
    missing_pdf = tmp_path / "missing-selected.pdf"
    with SessionLocal() as db:
        user = models.User(email=f"vision-document-readable-{uuid.uuid4()}@example.com", name="Readable Selection")
        db.add(user)
        db.flush()
        resume = models.Resume(user_id=user.id, name="base.pdf", base_resume_text="base", is_base=True)
        db.add(resume)
        db.flush()
        db.add_all(
            [
                models.ResumeArtifact(
                    resume_id=resume.id,
                    artifact_type="BASE_PDF",
                    pdf_path=str(older_pdf),
                    compile_status="SUCCESS",
                ),
                models.ResumeArtifact(
                    resume_id=resume.id,
                    artifact_type="BASE_PDF",
                    pdf_path=str(missing_pdf),
                    compile_status="SUCCESS",
                ),
            ]
        )
        db.flush()

        documents = extension_run._upload_documents_for_user(db, user.id)

        assert "resume" not in documents


def test_upload_document_context_binds_tailored_resume_to_exact_application_posting(tmp_path: Path) -> None:
    init_db()
    tailored_pdf = tmp_path / "tailored-for-exact-posting.pdf"
    tailored_pdf.write_bytes(b"%PDF-1.4\nexact tailored selection\n")
    with SessionLocal() as db:
        user = models.User(email=f"vision-tailored-binding-{uuid.uuid4()}@example.com", name="Tailored Binding")
        db.add(user)
        db.flush()
        resume = models.Resume(user_id=user.id, name="base.pdf", base_resume_text="base", is_base=True)
        selected_posting = models.JobPosting(user_id=user.id, url="https://example.test/jobs/selected")
        different_posting = models.JobPosting(user_id=user.id, url="https://example.test/jobs/different")
        db.add_all([resume, selected_posting, different_posting])
        db.flush()
        version = models.ResumeVersion(
            job_posting_id=selected_posting.id,
            resume_id=resume.id,
            tailored_latex="tailored",
        )
        db.add(version)
        db.flush()
        artifact = models.ResumeArtifact(
            resume_id=resume.id,
            resume_version_id=version.id,
            artifact_type="TAILORED_PDF",
            pdf_path=str(tailored_pdf),
            compile_status="SUCCESS",
            file_size=tailored_pdf.stat().st_size,
        )
        matching_application = models.Application(
            user_id=user.id,
            job_posting_id=selected_posting.id,
            resume_version_id=version.id,
        )
        mismatched_application = models.Application(
            user_id=user.id,
            job_posting_id=different_posting.id,
            resume_version_id=version.id,
        )
        db.add_all([artifact, matching_application, mismatched_application])
        db.flush()

        assert "resume" not in extension_run._upload_documents_for_user(db, user.id, version.id)
        assert "resume" not in extension_run._upload_documents_for_user(
            db,
            user.id,
            version.id,
            expected_application_id=mismatched_application.id,
            expected_job_posting_id=different_posting.id,
        )

        documents = extension_run._upload_documents_for_user(
            db,
            user.id,
            version.id,
            expected_application_id=matching_application.id,
            expected_job_posting_id=selected_posting.id,
        )

        assert documents["resume"]["artifact_id"] == artifact.id
        assert documents["resume"]["resume_version_id"] == version.id
        assert documents["resume"]["application_id"] == matching_application.id
        assert documents["resume"]["job_posting_id"] == selected_posting.id


def _vision_backup_test_provider(*, provider_type: str, enabled: bool = True) -> int:
    with SessionLocal() as db:
        service = ModelProviderService(db)
        provider = service.create_provider(
            {
                "display_name": f"Backup candidate {provider_type}",
                "provider_type": provider_type,
                "model_name": f"opaque-model-{uuid.uuid4()}",
                "base_url": "https://compatible.example.test/v1" if provider_type == "custom_openai_compatible" else "",
                "api_key": f"sk-backup-{uuid.uuid4()}",
                "enabled": enabled,
            }
        )
        db.commit()
        return provider.id


def _resolved_vision_provider(
    provider_id: int | None,
    *,
    display_name: str,
    provider_type: str,
    model_name: str,
    source: str = "database",
) -> ResolvedModelProvider:
    return ResolvedModelProvider(
        id=provider_id,
        display_name=display_name,
        provider_type=provider_type,
        model_name=model_name,
        base_url="https://provider.example.test/v1",
        api_key="test-key",
        temperature=0.0,
        max_tokens=2048,
        timeout_seconds=35,
        enabled=True,
        is_active=False,
        source=source,
    )


