def test_hud_payload_surfaces_loop_progress_without_notifications() -> None:
    observing = _hud_payload_for_narration(123, "observe", {"summary": "Capturing the current browser screenshot.", "elapsed_seconds": 5})
    thinking = _hud_payload_for_narration(123, "thinking", {"summary": "Choosing the next visual browser action.", "elapsed_seconds": 10})
