def test_option_click_requires_committed_or_existing_value_readback() -> None:
    inconclusive = {
        "ok": True,
        "surface_changed": True,
        "target_option_like": True,
        "target_selected_before": False,
        "selection_committed": False,
        "option_menu_closed": True,
        "owner_value_before": "Select...",
        "owner_value_after": "Select...",
        "owner_matches_target_after": False,
    }
    committed = {
        **inconclusive,
        "selection_committed": True,
        "owner_value_after": "No",
        "owner_matches_target_after": True,
        "owner_readback_changed": True,
    }

    assert _vision_action_verified("click", inconclusive) is False
    assert _vision_action_verified("click", committed) is True
    assert _vision_verification_extra("click", committed)["owner_readback_changed"] is True

    feedback = _vision_unverified_action_feedback(
        "click",
        {"action": "click", "reason": "Activate the grounded visible option."},
        inconclusive,
        False,
    )
    assert feedback.startswith("choice_activation_inconclusive")
    assert "ask_user only when the value itself is genuinely missing" in feedback


