    first = extension_run._scroll_oscillation_scope_key(
        action={"action": "scroll", "control": 1},
        bound_control={"selector": "#first"},
        shot=shot,
        result=invalid_container_result,
    )
    second = extension_run._scroll_oscillation_scope_key(
        action={"action": "scroll", "control": 2},
        bound_control={"selector": "#second"},
        shot=shot,
        result=invalid_container_result,
    )

    assert first and second and first != second
    assert extension_run._scroll_oscillation_scope_key(
        action={"action": "scroll", "control": 1},
        bound_control={"label": "descriptive text only"},
        shot=shot,
        result={},
    ) == ""
    assert extension_run._scroll_oscillation_scope_key(
        action={"action": "scroll", "control": 0},
        bound_control=None,
        shot={"page_evidence": {}},
        result={},
    ) == ""


