def test_final_page_context_survives_a_rerender_that_keeps_every_control_state() -> None:
    # v2_mutation_storm: the page re-renders every 900 ms with fresh ids and reshuffled sections, so
    # the exact document signature never holds from approval to dispatch while every control keeps
    # its label, value, and state.
    approved = {
        "url": "https://example.test/deck",
        "document_state_signature": "v1:approved-ids",
        "document_semantic_signature": "sv1:same-controls",
        "document_lifecycle_token": "doc-1",
        "page_evidence": {},
    }
    rerendered = {**approved, "document_state_signature": "v1:fresh-ids"}
    relabeled = {**rerendered, "document_semantic_signature": "sv1:other-controls"}
    replaced = {**rerendered, "document_lifecycle_token": "doc-2"}
    context = extension_run._final_page_context(approved)
    assert context["document_semantic_signature"] == "sv1:same-controls"
    assert extension_run._final_page_context_matches(context, rerendered) is True
    assert extension_run._final_page_context_matches(context, relabeled) is False
    assert extension_run._final_page_context_matches(context, replaced) is False
    # An approval recorded without the semantic signature (older extension) stays exact.
    legacy = {key: value for key, value in context.items() if key != "document_semantic_signature"}
    assert extension_run._final_page_context_matches(legacy, rerendered) is False


