def test_visible_change_feedback_reports_evidence_without_judging_the_surface() -> None:
    text = _scope_no_progress_feedback(
        label="Priority",
        result={"ok": True, "surface_changed": True},
        progress_class="transient_surface_change",
        attempts=2,
    )
    assert "toggle" not in text
    assert "not workflow progress" not in text
    assert "Read the fresh screenshot" in text
    assert "different mechanism" in text
    # A browser choice owner's popup keeps its own guidance.
    popup = _surface_change_recovery(
        {"surface_changed": True, "owner_selector": "#country", "owner_matches_target_after": False}
    )
    assert "do not toggle the owner again" in popup
    assert "do not toggle" not in _surface_change_recovery({"surface_changed": True})
    # Every browser click carries the owner_matches_* booleans; a plain button is not a popup.
    button = _surface_change_recovery(
        {"surface_changed": True, "owner_selector": "", "owner_matches_target_before": False, "owner_matches_target_after": False}
    )
    assert "choice popup" not in button
    # A click that raised the browser's own confirm: the screenshot cannot show it.
    dialog = _surface_change_recovery(
        {"surface_changed": True, "native_dialog": {"type": "confirm", "message": "Start the archival job?"}}
    )
    assert "confirm dialog" in dialog
    assert "does nothing here" not in dialog
    # Caret advice belongs to possible fields, not to a tab or button that was clicked.
    assert "text field" not in _surface_change_recovery({"surface_changed": True, "target_tag": "button", "target_role": "tab"})
    assert "text field" in _surface_change_recovery({"surface_changed": True, "target_tag": "div"})
    # The whole message reaches the model, not a 700-char cut that ends mid-sentence.
    from app.vision_agent import prepare_model_input

    prepared = prepare_model_input(
        {"width": 800, "height": 600, "url": "http://bench.test/", "title": "t"},
        {"goal": "g", "page_evidence": {}, "required_state_repair": popup},
    )
    assert "do not toggle the owner again." in prepared["system"]
    # A visible change the body could not read back is evidence about the last action, framed as
    # such (one-shot), not as a standing recovery order that rides along until durable progress.
    noted = prepare_model_input(
        {"width": 800, "height": 600, "url": "http://bench.test/", "title": "t"},
        {"goal": "g", "page_evidence": {}, "last_action_feedback": _surface_change_recovery({"surface_changed": True})},
    )
    assert "LAST ACTION FEEDBACK" in noted["system"]
    assert "RECOVERY REQUIRED" not in noted["system"]


