def test_tiny_browser_scroll_amount_is_a_unit_mistake() -> None:
    assert _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 3}, "browser")
    assert _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 49, "direction": "up"}, "browser")
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 50}, "browser")
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 0}, "browser")
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 3, "text": "Total"}, "browser")
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 3, "modifiers": ["ctrl"]}, "browser")
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 3}, "desktop")
    short_list = {"scroll": {"visible_height": 150}}
    assert not _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 40}, "browser", short_list)
    assert _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 10}, "browser", short_list)
    assert _scroll_amount_is_unit_mistake({"action": "scroll", "amount": 40}, "browser", {"scroll": {"visible_height": 900}})


def test_vision_scroll_delta_preserves_model_direction() -> None:
    assert _vision_scroll_delta({"direction": "up", "amount": 500, "y": 0}) == -500
    assert _vision_scroll_delta({"direction": "down", "amount": 300, "y": 0}) == 300
    assert _vision_scroll_delta({"amount": 0, "y": 400}) == 400
    assert _vision_scroll_delta({"direction": "up", "amount": 10}) == -10
    assert _vision_scroll_delta({"direction": "down", "amount": 40}) == 40
    assert _vision_scroll_delta({"direction": "down"}) == 600
    assert _vision_scroll_delta({"direction": "down", "amount": 90000}) == 50000


