def test_short_resume_value_requires_brain_owned_semantic_grounding() -> None:
    assert _vision_grounding_requires_semantic_judge(
        {"action": "type", "text": "LinkedIn"},
        {"ok": True, "source": "resume"},
    )
    assert not _vision_grounding_requires_semantic_judge(
        {"action": "type", "text": "https://example.test/profile"},
        {"ok": True, "source": "profile"},
    )
    assert not _vision_grounding_requires_semantic_judge(
        {"action": "type", "text": "Grounded long answer. " * 20},
        {"ok": True, "source": "resume"},
    )
    assert not _vision_grounding_requires_semantic_judge(
        {"action": "type", "text": "LinkedIn"},
        {"ok": False, "source": "resume"},
    )

    trusted_memory = _closed_world_attestation_memory()
    attestation_value = trusted_memory["value"]
    trusted_context = {
        "profile": {
            "profile_memory": [trusted_memory]
        }
    }
    assert _vision_grounding_requires_semantic_judge(
        {
            "action": "click",
            "text": "No",
            "grounding_quote": '"absence_answer":"No"',
        },
        {"ok": True, "source": "profile"},
        trusted_context,
    )
    judge_candidates = extension_run._vision_grounding_judge_candidates(
        trusted_context,
        citation_source="profile",
        citation_quote='"absence_answer":"No"',
        page_question="Have you previously worked for Other Corp?",
    )
    atomic_candidate = next(
        entry
        for entry in judge_candidates
        if entry.get("value") == attestation_value
    )
    assert len(attestation_value) > 200
    assert attestation_value.index('"members"') > 200
    assert atomic_candidate["evidence_contract"] == "closed_world_attestation_v1"
    forged_context = {
        "profile": {
            "profile_memory": [
                {**trusted_memory, "source": "user_profiles.profile_json.common_answers"}
            ]
        }
    }
    assert not _vision_grounding_requires_semantic_judge(
        {
            "action": "click",
            "text": "No",
            "grounding_quote": '"absence_answer":"No"',
        },
        {"ok": True, "source": "profile"},
        forged_context,
    )


