def test_vision_grounding_conflict_blocks_self_admitted_ungrounded_actions() -> None:
    assert _vision_grounding_conflict(
        {
            "action": "click",
            "reason": "I have no explicit gender in the profile, so I will select Choose not to disclose.",
        }
    ) == "ungrounded_action_admitted"
    assert _vision_grounding_conflict(
        {
            "action": "scroll",
            "reason": "I have no explicit gender in the profile, so I will scroll past this field.",
        }
    ) == ""
    assert _vision_grounding_conflict(
        {
            "action": "click",
            "reason": "The saved answer is Yes, so I will select Yes.",
        }
    ) == ""
    assert _vision_grounding_conflict(
        {
            "action": "click",
            "reason": "Based on the user's name, I can infer the user identifies as Asian and select Asian.",
        },
        {"profile": {"identity": {"name": "Jordan Candidate"}}},
    ) == "ungrounded_identity_inference"
    assert _vision_grounding_conflict(
        {
            "action": "click",
            "reason": "The Gender dropdown is open and I have a grounded answer for this field from saved_answers.",
        },
        {"profile": {"identity": {"name": "Jordan Candidate"}}, "saved_answers": []},
    ) == "unsupported_identity_grounding_claim"
    assert _vision_grounding_conflict(
        {
            "action": "click",
            "reason": "The saved answer for gender is Choose not to disclose, so I will select it.",
        },
        {"saved_answers": [{"question": "Gender", "answer": "Choose not to disclose"}]},
    ) == ""


