def test_vision_decision_context_trims_normal_payload_without_interpreting() -> None:
    compact = _vision_decision_context(
        {
            "resume_facts": {"resume_text": "R" * 3000},
            "saved_answers": [{"question": f"Q{i}" * 80, "answer": f"A{i}" * 120, "source": "answer_memory"} for i in range(12)],
            "human_answers": [
                {
                    "question": f"H{i}",
                    "answer": f"HA{i}" * 120,
                    "source": "human_field_approval",
                    "target_selector": f"#field-{i}",
                    "target_control_signature": f"sig-{i}",
                }
                for i in range(10)
            ],
            "profile_provenance": [{"field": f"field-{i}", "source": "S" * 400} for i in range(20)],
            "page_evidence": {
                "viewport_text": "V" * 3000,
                "controls": [
                    {
                        "text": "T" * 300,
                        "value": "X" * 300,
                        "nearby_text": "N" * 300,
                        "context_text": "C" * 300,
                        "dom_context": [{"relation": "previous_sibling", "depth": 3, "text": "D" * 300}],
                        "x": i,
                        "y": i,
                        "width": 10,
                        "height": 10,
                    }
                    for i in range(30)
                ],
            },
            "page_memory": [
                {"text": " ".join(f"view{i}word{j}" for j in range(160))} for i in range(8)
            ],
            "control_memory": [{"controls": [{"text": str(i) * 300} for i in range(12)]} for i in range(4)],
            "recent_actions": [str(i) for i in range(10)],
            "session_ledger": [{"control": f"C{i}" * 80, "action": "type", "attempts": i, "value": f"V{i}" * 120} for i in range(25)],
            "already_asked": [str(i) * 300 for i in range(10)],
        },
        payload_mode="normal",
    )

    assert compact.get("payload_mode") is None
    assert len(compact["resume_facts"]["resume_text"]) == 800
    assert len(compact["page_evidence"]["viewport_text"]) == 2000
    assert len(compact["page_evidence"]["controls"]) == 30  # the 28 budget grows to every on-screen row, up to twice
    assert extension_run._VISION_NORMAL_CONTEXT_BUDGET["controls"] == 28
    assert len(compact["page_evidence"]["controls"][0]["text"]) == 120
    assert len(compact["saved_answers"]) == 8
    assert len(compact["saved_answers"][0]["answer"]) == 220
    assert len(compact["human_answers"]) == 8
    assert compact["human_answers"][0]["target_selector"] == "#field-2"
    assert compact["human_answers"][0]["target_control_signature"] == "sig-2"
    assert compact["page_evidence"]["controls"][0]["dom_context"][0]["depth"] == 3
    assert len(compact["page_evidence"]["controls"][0]["dom_context"][0]["text"]) == 120
    assert len(compact["profile_provenance"]) == 12
    assert len(compact["profile_provenance"][0]["source"]) == 160
    assert len(compact["page_memory"]) == 6
    assert len(compact["page_memory"][0]["text"]) == extension_run._VISION_NORMAL_CONTEXT_BUDGET["page_memory_text"]
    assert compact["page_memory"][0]["text"].startswith("view2word0 ")
    assert len(compact["control_memory"]) == 1
    assert len(compact["control_memory"][0]["controls"]) == 8
    assert compact["recent_actions"] == ["4", "5", "6", "7", "8", "9"]
    assert len(compact["session_ledger"]) == 20
    assert len(compact["session_ledger"][0]["control"]) == 80
    assert len(compact["session_ledger"][0]["value"]) == 120
    assert len(compact["already_asked"]) == 8


