def test_vision_decision_profile_save_retries_sqlite_lock_and_persists(monkeypatch) -> None:
    init_db()
    provider_type = "openrouter"
    model_name = f"test-vision-lock-{uuid.uuid4().hex}"
    real_session_local = extension_run.SessionLocal
    calls = {"commit": 0}

    class LockOnceSession:
        def __init__(self) -> None:
            self._session = real_session_local()

        def __enter__(self):
            self._session.__enter__()
            return self

        def __exit__(self, exc_type, exc, tb):
            return self._session.__exit__(exc_type, exc, tb)

        def __getattr__(self, name: str):
            return getattr(self._session, name)

        def commit(self) -> None:
            calls["commit"] += 1
            if calls["commit"] == 1:
                raise RuntimeError("sqlite database is locked")
            self._session.commit()

    monkeypatch.setattr(extension_run, "SessionLocal", lambda: LockOnceSession())
    monkeypatch.setattr(extension_run.time, "sleep", lambda _seconds: None)

    ok = _save_vision_decision_profile(
        {
            "provider_type": provider_type,
            "model_name": model_name,
            "ewma_latency_seconds": 12.0,
            "latency_ring_seconds": [10, 12],
        },
        force=True,
    )

    assert ok is True
    assert calls["commit"] == 2
    with SessionLocal() as db:
        row = db.query(models.VisionDecisionProfile).filter_by(provider_type=provider_type, model_name=model_name).first()
        assert row is not None
        assert row.metadata_json["latency_ring_seconds"] == [10.0, 12.0]


def test_vision_decision_profile_save_failure_emits_telemetry(monkeypatch) -> None:
    init_db()
    real_session_local = extension_run.SessionLocal
    events: list[tuple[int, str, dict]] = []

    class AlwaysLockedSession:
        def __init__(self) -> None:
            self._session = real_session_local()

        def __enter__(self):
            self._session.__enter__()
            return self

        def __exit__(self, exc_type, exc, tb):
            return self._session.__exit__(exc_type, exc, tb)

        def __getattr__(self, name: str):
            return getattr(self._session, name)

        def commit(self) -> None:
            raise RuntimeError("sqlite database is locked")

    monkeypatch.setattr(extension_run, "SessionLocal", lambda: AlwaysLockedSession())
    monkeypatch.setattr(extension_run.time, "sleep", lambda _seconds: None)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: events.append((run_id, event_type, payload)))

    ok = _save_vision_decision_profile(
        {
            "provider_type": "openrouter",
            "model_name": f"test-vision-fail-{uuid.uuid4().hex}",
            "ewma_latency_seconds": 12.0,
            "latency_ring_seconds": [12],
        },
        force=True,
        run_id=987,
    )

    assert ok is False
    assert events
    assert events[0][0] == 987
    assert events[0][1] == "VISION_PROFILE_SAVE_FAILED"
    assert "database is locked" in events[0][2]["error"]


def test_await_with_progress_stops_waiting_when_cancelled(monkeypatch) -> None:
    events: list[tuple[str, dict]] = []
    calls = {"count": 0}

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    async def slow_phase() -> str:
        await asyncio.sleep(5)
        return "done"

    def should_cancel() -> bool:
        calls["count"] += 1
        return calls["count"] >= 2

    async def run_wait() -> str:
        try:
            await extension_run._await_with_progress(
                slow_phase(),
                narrate=narrate,
                kind="thinking",
                data={"summary": "Choosing the next visual browser action."},
                timeout_seconds=5,
                should_cancel=should_cancel,
            )
        except extension_run._RunCancelled as exc:
            return str(exc)
        return "not_cancelled"

    monkeypatch.setattr(extension_run, "_HEARTBEAT_INTERVAL_SECONDS", 0.01)

    assert asyncio.run(run_wait()) == "user_cancelled"
    assert events[0] == ("thinking", {"summary": "Choosing the next visual browser action.", "elapsed_seconds": 0})


def test_await_with_progress_preserves_session_pause_reason(monkeypatch) -> None:
    events: list[tuple[str, dict]] = []

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    async def slow_phase() -> str:
        await asyncio.sleep(5)
        return "done"

    async def run_wait() -> str:
        try:
            await extension_run._await_with_progress(
                slow_phase(),
                narrate=narrate,
                kind="thinking",
                data={"summary": "Choosing the next visual browser action."},
                timeout_seconds=5,
                should_cancel=lambda: "session_paused",
            )
        except extension_run._RunCancelled as exc:
            return str(exc)
        return "not_interrupted"

    monkeypatch.setattr(extension_run, "_HEARTBEAT_INTERVAL_SECONDS", 0.01)

    assert asyncio.run(run_wait()) == "session_paused"
    assert events[0] == ("thinking", {"summary": "Choosing the next visual browser action.", "elapsed_seconds": 0})


