class _VisionBody:
    def __init__(self) -> None:
        self.scrolls = 0
        self.captures = 0
        self.uploads: list[tuple[int, int, dict]] = []

    async def capture_screenshot(self) -> dict:
        self.captures += 1
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test",
            "title": "Example",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {
                "viewport_text": "Example job page text with enough visible content to keep in session memory.",
                "controls": [{"text": "Select", "nearby_text": "Work authorization", "x": 10, "y": 100, "width": 200, "height": 40}],
            },
        }

    async def vision_scroll(self, dy: int) -> dict:
        self.scrolls += 1
        return {"ok": True, "before_scroll_y": 0, "scroll_y": dy}

    async def vision_upload(self, x: int, y: int, document: dict) -> dict:
        self.uploads.append((x, y, document))
        return {"ok": True, "value_present": True, "observed_present": True, "page_filename_visible": True, "filename": document.get("filename")}


class _TargetedScrollBody(_VisionBody):
    def __init__(self) -> None:
        super().__init__()
        self.targeted_scrolls: list[tuple[int, dict]] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["document_lifecycle_token"] = "document-targeted-scroll"
        shot["document_state_signature"] = "state-targeted-scroll"
        shot["page_evidence"] = {
            "viewport_text": "A clipped generic option list is open.",
            "document_lifecycle_token": "document-targeted-scroll",
            "document_state_signature": "state-targeted-scroll",
            "controls": [
                {
                    "index": 1,
                    "tag": "button",
                    "type": "",
                    "role": "option",
                    "text": "New Jersey",
                    "selector": "#menu-option",
                    "x": 100,
                    "y": 140,
                    "width": 220,
                    "height": 36,
                }
            ],
        }
        return shot

    async def vision_scroll(self, dy: int, **binding: object) -> dict:
        self.scrolls += 1
        self.targeted_scrolls.append((dy, dict(binding)))
        return {
            "ok": True,
            "action": "scroll",
            "mode": "element_scroll",
            "before_scroll_y": 0,
            "scroll_y": 0,
            "before_scroll_position": 0,
            "scroll_position": dy,
            "scroll_target_kind": "container",
            "scroll_container_identity_hash": "c" * 32,
            "scroll_attempted": True,
            "target_identity_matched": True,
        }


class _OutcomeUnknownTargetedScrollBody(_TargetedScrollBody):
    async def vision_scroll(self, dy: int, **binding: object) -> dict:
        self.scrolls += 1
        self.targeted_scrolls.append((dy, dict(binding)))
        return {
            "ok": False,
            "action": "scroll",
            "mode": "element_scroll",
            "failure_reason": "scroll_execution_outcome_unknown",
            "scroll_target_kind": "container",
            "scroll_container_identity_hash": "d" * 32,
            "scroll_attempted": True,
            "browser_mutation_attempted": True,
            "execution_outcome_unknown": True,
            "target_identity_matched": True,
        }


class _TransportLostTargetedScrollBody(_TargetedScrollBody):
    async def vision_scroll(self, dy: int, **binding: object) -> dict:
        self.scrolls += 1
        self.targeted_scrolls.append((dy, dict(binding)))
        raise ExtensionTransportError(
            "extension response lost after dispatch",
            command_may_have_executed=True,
        )


