def test_vision_loop_reobserves_after_one_unknown_scroll_and_blocks_on_the_second(monkeypatch) -> None:
    """The first scroll whose result is lost settles and continues from a fresh observation (run 1792
    blocked one step before Submit on one); it is never re-dispatched blind. A second one blocks."""
    init_db()
    monkeypatch.setattr(extension_run, "_VISION_UNKNOWN_SCROLL_SETTLE_SECONDS", 0)
    body = _OutcomeUnknownTargetedScrollBody()
    decisions = 0
    events: list[tuple[str, dict]] = []
    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda _run_id, event_type, payload: events.append((event_type, payload)),
    )
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)

    def decide(*_args, **_kwargs):
        nonlocal decisions
        decisions += 1
        return {
            "action": "scroll",
            "control": 1,
            "direction": "down",
            "amount": 180,
            "reason": "The desired content is below the clipped container viewport.",
        }

    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    async def narrate(_kind: str, _data: dict) -> None:
        return None

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=4,
        )
    )

    # One decision per scroll: each follows a fresh observation, not a blind retry. The second and third
    # unknown scrolls each recover in-loop (SELF_RECOVERY_LIMIT per run); the fourth ends the run.
    assert decisions == SELF_RECOVERY_LIMIT + 2
    assert len(body.targeted_scrolls) == SELF_RECOVERY_LIMIT + 2
    assert summary["state"] == "BLOCKED"
    assert summary["reason"] == "scroll_execution_outcome_unknown"
    assert summary["block_kind"] == "awaiting_engineering"
    assert summary["system_block"] is True
    assert len(summary["receipts"]) == SELF_RECOVERY_LIMIT + 2
    for receipt in summary["receipts"]:
        verification = receipt["verification"]
        assert verification["scroll_attempted"] is True
        assert verification["browser_mutation_attempted"] is True
        assert verification["execution_outcome_unknown"] is True
    unknown_events = [payload for event_type, payload in events if event_type == "VISION_SCROLL_EXECUTION_OUTCOME_UNKNOWN"]
    assert [event["unknown_scrolls_this_run"] for event in unknown_events] == list(range(1, SELF_RECOVERY_LIMIT + 3))
    assert all(event["duplicate_retry_allowed"] is False for event in unknown_events)
    recoveries = [payload for event_type, payload in events if event_type == "VISION_SELF_RECOVERY"]
    assert [(p["reason"], p["count"]) for p in recoveries] == [
        ("scroll_execution_outcome_unknown", count) for count in range(1, SELF_RECOVERY_LIMIT + 1)
    ]


def test_vision_loop_blocks_post_dispatch_scroll_transport_loss_without_retry(monkeypatch) -> None:
    init_db()
    body = _TransportLostTargetedScrollBody()
    decisions = 0
