class _OptionalSkipBody:
    def __init__(self, observations: list[dict]) -> None:
        self.observations = observations
        self.captures = 0
        self.mutations = 0
        self.clicks: list[tuple[int, int]] = []
        self.control_clicks: list[tuple[str, int, int]] = []
        self.scroll_deltas: list[int] = []

    async def capture_screenshot(self) -> dict:
        observation = self.observations[min(self.captures, len(self.observations) - 1)]
        self.captures += 1
        image_bytes = observation.get("image_bytes") or b"optional-skip-observation"
        return {
            "ok": True,
            "image": base64.b64encode(image_bytes).decode(),
            "width": 800,
            "height": 600,
            "url": observation.get("url") or "https://example.test/apply",
            "title": "Apply",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {
                "viewport_text": observation.get("viewport_text") or "Visible browser controls.",
                "controls": [dict(control) for control in observation.get("controls") or []],
            },
        }

    async def vision_click(self, x: int, y: int, **kwargs) -> dict:
        self.mutations += 1
        self.clicks.append((x, y))
        return {
            "ok": True,
            "action": "click",
            "focus_changed": True,
            "active_typable": True,
            "active_tag": "input",
        }

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        **kwargs,
    ) -> dict:
        self.mutations += 1
        self.control_clicks.append((selector, fallback_x, fallback_y))
        return {
            "ok": True,
            "action": "click",
            "mode": "control_selector",
            "focus_changed": True,
            "active_typable": True,
            "active_tag": "input",
            "activation_dispatched": True,
            "activation_count": 1,
        }

    async def vision_type(self, *args, **kwargs) -> dict:
        self.mutations += 1
        return {"ok": True}

    async def vision_scroll(self, dy: int) -> dict:
        self.mutations += 1
        self.scroll_deltas.append(dy)
        return {"ok": True, "before_scroll_y": 0, "scroll_y": dy}

    async def vision_key(self, *args, **kwargs) -> dict:
        self.mutations += 1
        return {"ok": True}

    async def vision_upload(self, *args, **kwargs) -> dict:
        self.mutations += 1
        return {"ok": True}


def _optional_skip_control(
    index: int,
    *,
    question: str = "Work authorization",
    selector: str | None = None,
    y: int = 100,
    x: int = 10,
) -> dict:
    return {
        "index": index,
        "tag": "input",
        "type": "text",
        "role": "combobox",
        "selector": selector or f"#control-{index}",
        "text": "Select",
        "value": "",
        "context_text": question,
        "x": x,
        "y": y,
        "width": 240,
        "height": 40,
    }


def test_optional_skip_binding_requires_unchanged_current_control_state() -> None:
    control = _optional_skip_control(1, selector="#optional-before")
    evidence = {"controls": [control]}
    observation_identity = {"screenshot_sha256": "a" * 64, "step": 7}
    binding, error = extension_run._bind_model_optional_skip(
        {
            "control": 1,
            "question": "Work authorization",
            "reason": "The rendered page marks this control optional.",
        },
        raw_page_evidence=evidence,
        model_page_evidence=evidence,
        observation_identity=observation_identity,
    )

    assert error == ""
    assert binding is not None
    assert extension_run._control_matches_model_optional_skip(
        {"index": 1},
        page_evidence=evidence,
        bindings=[binding],
        observation_identity=observation_identity,
    )

    changed_evidence = {"controls": [{**control, "selector": "#optional-after", "x": 25}]}
    assert not extension_run._control_matches_model_optional_skip(
        {"index": 1},
        page_evidence=changed_evidence,
        bindings=[binding],
        observation_identity=observation_identity,
    )


