class _RejectedScreenshotBody(_VisionBody):
    def __init__(self, *, retryable: bool) -> None:
        super().__init__()
        self.retryable = retryable

    async def capture_screenshot(self) -> dict:
        self.captures += 1
        if self.captures == 1 or not self.retryable:
            return {
                "ok": False,
                "action": "screenshot",
                "failure_reason": (
                    "screenshot_observation_drift"
                    if self.retryable
                    else "sensitive_mask_rebind_lost_before_capture"
                ),
                "retryable": self.retryable,
                "image_discarded": True,
                "evidence_stage": "pre_capture_context",
                "surface_probe_complete": False,
                "before_surface_signature": "before-surface",
                "after_surface_signature": "after-surface",
            }
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/review",
            "title": "Review",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {"viewport_text": "Review is ready.", "controls": []},
        }


