class _LedgerBody:
    def __init__(self, *, observed_value: str | None = "a@b.com") -> None:
        # None: the field echoes whatever was typed (a read-back that always matches).
        self.observed_value = observed_value
        self.typed = False
        self.clicks: list[tuple[int, int]] = []
        self.typed_values: list[str] = []

    async def capture_screenshot(self) -> dict:
        controls = [] if self.typed else [
            {
                "index": 1,
                "tag": "input",
                "type": "email",
                "role": "",
                "text": "",
                "context_text": "Email address",
                "value": "",
                "checked": False,
                "selector": "#email",
                "x": 100,
                "y": 120,
                "width": 240,
                "height": 40,
            }
        ]
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/apply",
            "title": "Apply",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {"viewport_text": "Email address", "controls": controls},
        }

    async def vision_click(
        self,
        x: int,
        y: int,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", "active_typable": True, "active_tag": "input", "active_hint": "Email address"}

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        assert selector == "#email"
        return await self.vision_click(
            fallback_x,
            fallback_y,
            expected_target_identity=expected_target_identity,
            expected_page_context=expected_page_context,
        )

    async def vision_type(self, text: str) -> dict:
        self.typed = True
        self.typed_values.append(text)
        shown = text if self.observed_value is None else self.observed_value
        return {
            "ok": True,
            "action": "type",
            "active_typable": True,
            "active_has_value": bool(shown),
            "active_tag": "input",
            "active_value": shown,
        }

    async def vision_type_control(
        self,
        selector: str,
        text: str,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        assert selector == "#email"
        return await self.vision_type(text)


