class _ScrollOscillationBody:
    def __init__(self, *, progress: bool = False) -> None:
        self.progress = progress
        self.scrolls = 0
        self.scroll_y = 0

    async def capture_screenshot(self) -> dict:
        if self.progress and self.scrolls >= 8:
            controls = []
        else:
            label = f"Visible control {self.scrolls}" if self.progress else "Visible control"
            controls = [
                {
                    "tag": "button",
                    "role": "button",
                    "text": label,
                    "context_text": label,
                    "x": 100,
                    "y": 120,
                    "width": 180,
                    "height": 40,
                }
            ]
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/apply",
            "title": "Apply",
            "scroll_y": self.scroll_y,
            "scroll_height": 600,
            "document_lifecycle_token": "scroll-fixture-document",
            "page_evidence": {
                "viewport_text": "Scrolling page",
                "controls": controls,
                "document_lifecycle_token": "scroll-fixture-document",
            },
        }

    async def vision_scroll(self, dy: int) -> dict:
        before = self.scroll_y
        self.scrolls += 1
        self.scroll_y = max(0, self.scroll_y + dy)
        return {"ok": True, "before_scroll_y": before, "scroll_y": self.scroll_y}


class _IndependentContainerScrollBody:
    def __init__(self) -> None:
        self.scrolls = 0
        self.positions = {"#first-region-control": 0, "#second-region-control": 1000}

    async def capture_screenshot(self) -> dict:
        controls = (
            []
            if self.scrolls >= 4
            else [
                {
                    "index": 1,
                    "tag": "button",
                    "role": "option",
                    "text": "First region item",
                    "selector": "#first-region-control",
                    "x": 100,
                    "y": 120,
                    "width": 180,
                    "height": 40,
                },
                {
                    "index": 2,
                    "tag": "button",
                    "role": "option",
                    "text": "Second region item",
                    "selector": "#second-region-control",
                    "x": 400,
                    "y": 120,
                    "width": 180,
                    "height": 40,
                },
            ]
        )
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/two-regions",
            "title": "Two regions",
            "scroll_y": 0,
            "scroll_height": 600,
            "document_lifecycle_token": "two-region-document",
            "page_evidence": {
                "viewport_text": "Two independent scrollable regions",
                "controls": controls,
                "document_lifecycle_token": "two-region-document",
            },
        }

    async def vision_scroll(self, dy: int, **binding: object) -> dict:
        selector = str(binding.get("selector") or "")
        before = self.positions[selector]
        after = before + dy
        self.positions[selector] = after
        self.scrolls += 1
        return {
            "ok": True,
            "action": "scroll",
            "mode": "element_scroll",
            "before_scroll_position": before,
            "scroll_position": after,
            "before_scroll_y": 0,
            "scroll_y": 0,
            "scroll_target_kind": "container",
            "scroll_container_identity_hash": (
                "a" * 32 if selector == "#first-region-control" else "b" * 32
            ),
            "scroll_attempted": True,
            "target_identity_matched": True,
        }


