class _FinalSubmitBody:
    def __init__(self, *, payment_control: bool = False, unhandled_control: bool = False) -> None:
        self.payment_control = payment_control
        self.unhandled_control = unhandled_control
        self.submitted = False
        self.capture_count = 0
        self.clicks: list[tuple[int, int, bool]] = []
        self.control_clicks: list[tuple[str, int, int, bool]] = []

    async def capture_screenshot(self) -> dict:
        self.capture_count += 1
        controls: list[dict] = []
        if self.payment_control:
            controls.append({"index": 1, "tag": "input", "type": "text", "autocomplete": "cc-number", "text": "", "value": "", "context_text": "Card number", "x": 10, "y": 100, "width": 200, "height": 40})
        if self.unhandled_control:
            controls.append({"index": 2, "tag": "input", "type": "text", "text": "", "value": "", "context_text": "Email address", "x": 10, "y": 160, "width": 200, "height": 40})
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/thanks" if self.submitted else "https://example.test/apply",
            "title": "Submitted" if self.submitted else "Apply",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {
                "viewport_text": "Thank you. Application submitted." if self.submitted else "Ready to submit application.",
                "controls": controls,
            },
        }

    async def vision_click(
        self,
        x: int,
        y: int,
        *,
        allow_final_submit: bool = False,
        **_expected_binding: object,
    ) -> dict:
        self.clicks.append((x, y, bool(allow_final_submit)))
        if allow_final_submit:
            self.submitted = True
            return {"ok": True, "action": "click", "url_changed": True, "after_url": "https://example.test/thanks"}
        return {
            "ok": False,
            "action": "click",
            "blocked_submit": True,
            "label": "Submit application",
            "selector": "#submit",
            "target_tag": "button",
            "target_type": "submit",
            "target_role": "button",
            "target_text": "Submit application",
            "dispatch_path": "dom_activation",
            "x": x,
            "y": y,
        }

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        *,
        allow_final_submit: bool = False,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        self.control_clicks.append((selector, fallback_x, fallback_y, bool(allow_final_submit)))
        if allow_final_submit:
            self.submitted = True
            return {"ok": True, "action": "click", "mode": "control_selector", "url_changed": True, "after_url": "https://example.test/thanks"}
        return {
            "ok": False,
            "action": "click",
            "mode": "control_selector",
            "blocked_submit": True,
            "label": "Submit application",
            "selector": selector or "#submit",
            "target_tag": "button",
            "target_type": "submit",
            "target_role": "button",
            "target_text": "Submit application",
            "dispatch_path": "dom_activation",
            "x": fallback_x,
            "y": fallback_y,
        }


