    return {
        "status": "approved",
        "selector": selector,
        "label": label,
        "x": 390,
        "y": 442,
        "approval_token": f"approval-{question_id}",
        "question_id": question_id,
        "authorization": {
            "source": "human_chat",
            "message_id": question_id + 1000,
            "question_id": question_id,
        },
        "target_identity": {
            "target_selector": selector,
            "target_text": label,
            "target_tag": "button",
            "target_type": "submit",
            "target_role": "button",
            "dispatch_path": "dom_activation",
            "page_url": page_url,
        },
        "page_context": {"url": page_url},
    }


