class _GuardedIntermediateBody:
    def __init__(self, *, inside_form: bool = False) -> None:
        self.started = False
        self.inside_form = inside_form
        self.clicks: list[tuple[int, int, bool]] = []
        self.control_clicks: list[tuple[str, int, int, bool, bool]] = []

    async def capture_screenshot(self) -> dict:
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/task",
            "title": "Application form" if self.started else "Task details",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {
                "viewport_text": "Application form is open." if self.started else "Task details. Start the application.",
                "controls": [],
            },
        }

    async def vision_click(
        self,
        x: int,
        y: int,
        *,
        allow_final_submit: bool = False,
        **_expected_binding: object,
    ) -> dict:
        self.clicks.append((x, y, bool(allow_final_submit)))
        return {
            "ok": False,
            "action": "click",
            "blocked_submit": True,
            "label": "Start",
            "target_label": "Start",
            "selector": "#start",
            "dispatch_path": "dom_activation",
            "x": x,
            "y": y,
            "submit_detection_basis": "contextual",
            "submit_detection": {
                "tag": "button",
                "type_attribute": "button",
                "resolved_type": "button",
                "inside_form": self.inside_form,
                "form_owner": "application" if self.inside_form else "",
                "text": "Start",
            },
        }

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        *,
        allow_final_submit: bool = False,
        allow_guarded_intermediate: bool = False,
        **_expected_binding: object,
    ) -> dict:
        self.control_clicks.append(
            (selector, fallback_x, fallback_y, bool(allow_final_submit), bool(allow_guarded_intermediate))
        )
        if allow_final_submit:
            raise AssertionError("guarded intermediate recovery must never receive final-submit authority")
        if allow_guarded_intermediate:
            self.started = True
            return {
                "ok": True,
                "action": "click",
                "mode": "control_selector",
                "surface_changed": True,
                "guarded_intermediate_revalidated": True,
                "submit_detection_basis": "contextual",
            }
        return await self.vision_click(fallback_x, fallback_y)


class _CustomButtonClickBody:
    """A non-submit-like custom control that Chrome's structural guard would allow."""

    def __init__(self) -> None:
        self.clicked = False
        self.coordinate_clicks: list[tuple[int, int]] = []
        self.control_clicks: list[tuple[str, int, int]] = []

    async def capture_screenshot(self) -> dict:
        controls = [] if self.clicked else [
            {
                "index": 1,
                "tag": "button",
                "type": "button",
                "role": "button",
                "text": "Commit selected seats",
                "context_text": "Review selected seats",
                "selector": "#commit-seats",
                "x": 250,
                "y": 180,
                "width": 300,
                "height": 48,
            }
        ]
        return {
            "ok": True,
            "image": base64.b64encode(b"custom-button-fixture-screenshot").decode(),
            "width": 800,
            "height": 600,
            "url": "https://example.test/seats",
            "title": "Seat selection",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {
                "viewport_text": (
                    "The selected seats are committed."
                    if self.clicked
                    else "Review selected seats before committing the external reservation."
                ),
                "controls": controls,
            },
        }

    async def vision_click(
        self,
        x: int,
        y: int,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        self.coordinate_clicks.append((x, y))
        self.clicked = True
        return {"ok": True, "action": "click", "surface_changed": True}

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        **_expected_binding: object,
    ) -> dict:
        self.control_clicks.append((selector, fallback_x, fallback_y))
        self.clicked = True
        return {
            "ok": True,
            "action": "click",
            "mode": "control_selector",
            "surface_changed": True,
            "control_selector_resolved": True,
        }


class _StaleFinalSubmitBody(_FinalSubmitBody):
    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        *,
        allow_final_submit: bool = False,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        self.control_clicks.append((selector, fallback_x, fallback_y, bool(allow_final_submit)))
        return {
            "ok": False,
            "action": "click",
            "mode": "control_selector",
            "failure_reason": "final_submit_target_mismatch",
            "control_selector_resolved": False,
            "activation_attempted": False,
            "activation_count": 0,
        }


class _TwoTextareaBody:
    def __init__(self) -> None:
        self.typed_values: list[str] = []

    async def capture_screenshot(self) -> dict:
        index = len(self.typed_values)
        controls = []
        if index < 2:
            label = ["Why this company?", "Describe a different project."][index]
            controls = [
                {
                    "index": 1,
                    "tag": "textarea",
                    "type": "",
                    "role": "textbox",
                    "text": "",
                    "context_text": label,
                    "dom_context": [{"relation": "previous_sibling", "depth": 1, "text": label}],
                    "value": "",
                    "selector": "#open-response",
                    "x": 100,
                    "y": 120,
                    "width": 360,
                    "height": 120,
                }
            ]
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/apply",
            "title": "Apply",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {"viewport_text": "Open response", "controls": controls},
        }

    async def vision_type(self, text: str) -> dict:
        self.typed_values.append(text)
        return {
            "ok": True,
            "action": "type",
            "active_typable": True,
            "active_has_value": True,
            "active_tag": "textarea",
            "active_value": text,
        }

    async def vision_type_control(
        self,
        selector: str,
        text: str,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        assert selector == "#open-response"
        return await self.vision_type(text)


def test_vision_loop_reobserves_after_transport_interruption_without_repeating_unknown_click(monkeypatch) -> None:
    init_db()
    body = _TransportInterruptedClickBody()
    contexts: list[dict] = []
    plans: list[dict] = []
    decisions = iter(
        [
            {"action": "click", "x": 110, "y": 120, "reason": "Continue to the visible review section."},
            {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "The review section is visible."},
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        if kind == "plan":
            plans.append(data)

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return next(decisions)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.clicks == 1
    assert body.captures == 2
    assert any("action outcome is unknown" in item for item in contexts[-1]["recent_actions"])
    assert any(plan.get("action") == "reobserve" for plan in plans)


