def test_vision_loop_retries_body_rejected_screenshot_with_fresh_observation(
    monkeypatch,
) -> None:
    init_db()
    body = _RejectedScreenshotBody(retryable=True)
    events: list[tuple[str, dict]] = []
    plans: list[dict] = []

    async def narrate(kind: str, data: dict) -> None:
        if kind == "plan":
            plans.append(data)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda _run_id, event_type, payload: events.append((event_type, payload)),
    )
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        extension_run,
        "_decide_vision_action",
        lambda user_id, image, view, context: {
            "action": "done",
            "x": 0,
            "y": 0,
            "artifact_role": "",
            "reason": "The review page is visible.",
        },
    )

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=3,
        )
    )

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.captures == 2
    rejected = [
        payload
        for event_type, payload in events
        if event_type == "VISION_SCREENSHOT_CAPTURE_REJECTED"
    ]
    assert rejected == [
        {
            "operation": "screenshot",
            "failure_reason": "screenshot_observation_drift",
            "error": "",
            "retryable": True,
            "image_discarded": True,
            "recovery_attempt": 1,
            "recovery_limit": 4,
            "runtime_build": extension_run._VISION_RUNTIME_BUILD,
            "evidence_stage": "pre_capture_context",
            "before_surface_signature": "before-surface",
            "after_surface_signature": "after-surface",
            "surface_probe_complete": False,
        }
    ]
    assert any(
        plan.get("action") == "reobserve"
        and plan.get("failure_reason") == "screenshot_observation_drift"
        for plan in plans
    )


