def test_vision_loop_recovers_one_off_nontransport_body_exception(monkeypatch) -> None:
    init_db()

    class FlakyOnce(_TransportInterruptedClickBody):
        async def vision_click(self, x, y, **kwargs) -> dict:
            self.clicks += 1
            if self.clicks == 1:
                raise RuntimeError("boom password: hunter2hunter2")
            self.clicked = True
            return {"ok": True, "action": "click"}

    body = FlakyOnce(transport_error=False)
    contexts: list[dict] = []

    async def narrate(kind: str, data: dict) -> None:
        pass

    def decide(user_id, image, view, context):
        contexts.append(context)
        return {"action": "click", "x": 110, "y": 120, "reason": "Continue to review."}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    assert summary.get("reason") != "body_execution_exception"
    assert body.clicks >= 2
    recent_text = " ".join(str(item) for ctx in contexts[1:2] for item in (ctx.get("recent_actions") or []))
    assert "action_failed" in recent_text
    assert "hunter2hunter2" not in recent_text


def test_desktop_surface_hides_address_bar_actions_browser_surface_offers_them() -> None:
    class Plain:
        pass

    class Switching:
        def available_surfaces(self):
            return ["browser", "desktop"]

        async def switch_surface(self, target):
            return {"ok": True}

    hidden = {"navigate", "reload", "switch_tab", "watch"}
    assert hidden <= set(extension_run._actions_unavailable_on_body(Switching(), "desktop"))
    assert hidden <= set(extension_run._actions_unavailable_on_body(Plain(), "desktop"))
    assert not hidden & set(extension_run._actions_unavailable_on_body(Switching(), "browser"))
    assert not hidden & set(extension_run._actions_unavailable_on_body(Plain(), "browser"))


