class _TimedReleaseBody:
    """Arm, then fire while a short ready window is open: the fire click must follow a wait
    for the ready text without a fresh model turn in between."""

    def __init__(self, *, ready_text_appears: bool) -> None:
        self.ready_text_appears = ready_text_appears
        self.clicks: list[tuple[int, int]] = []
        self.waits: list[tuple[int, str]] = []

    async def capture_screenshot(self) -> dict:
        return {
            "ok": True,
            "image": "jpeg",
            "width": 800,
            "height": 600,
            "url": "https://example.test/timed",
            "title": "Timed release",
            "scroll_y": 0,
            "scroll_height": 600,
            "page_evidence": {"viewport_text": "Status: Idle Arm system Fire", "controls": []},
        }

    async def vision_click(self, x: int, y: int, **_binding: object) -> dict:
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", "surface_changed": True}

    async def vision_wait(self, wait_ms: int, *, text: str = "") -> dict:
        self.waits.append((wait_ms, text))
        matched = bool(text) and self.ready_text_appears
        return {"ok": matched or not text, "action": "wait", "waited_ms": 900, "text_matched": matched}


def _timed_release_decisions() -> list[dict]:
    return [
        {
            "action": "click",
            "x": 100,
            "y": 200,
            "reason": "Arm the system; fire as soon as it reads ready.",
            "then": [
                {"action": "wait", "wait_ms": 2000, "text": "Ready - fire now"},
                {"action": "click", "x": 300, "y": 200, "text": ""},
            ],
        },
        {"action": "done", "reason": "Released."},
    ]


def test_followup_click_fires_the_moment_its_wait_text_is_seen(monkeypatch) -> None:
    init_db()
    body = _TimedReleaseBody(ready_text_appears=True)
    decisions = iter(_timed_release_decisions())
    judged: list[dict] = []

    def judge(*args, **kwargs):
        judged.append(dict(kwargs.get("action") or {}))
        return {"classification": "intermediate", "confidence": 0.99, "evidence": "Fixture: in-page step.", "metadata": {}}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence", judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    assert body.waits == [(2000, "Ready - fire now")]
    assert body.clicks == [(100, 200), (300, 200)]
    # The fire click was judged before the sequence started (its own pre-judgment) and the
    # arm click inline: two verdicts, and none after the wait.
    assert len(judged) == 2


