def test_a_field_and_its_verify_button_run_in_one_decision(monkeypatch) -> None:
    # frames from the brain seat: code + Verify, passcode + Submit, word + Unlock each cost a second
    # turn because a click after a type was never pre-judged. Now it is, like a click after a click.
    init_db()
    body = _CodeAndVerifyBody()
    judged: list[dict] = []
    scripted = [
        {
            "action": "type", "control": 1, "x": 220, "y": 120, "text": "555-123-4567",
            "grounding_source": "profile", "grounding_quote": "555-123-4567", "reason": "Enter the code.",
            "then": [{"action": "click", "control": 2, "x": 420, "y": 120, "text": ""}],
        },
    ]
    calls: list[int] = []

    def fake_decide(*_args: object) -> dict:
        calls.append(1)
        if len(calls) <= len(scripted):
            return scripted[len(calls) - 1]
        return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    def judge(*args, **kwargs):
        judged.append(dict(kwargs.get("action") or {}))
        return {"classification": "intermediate", "confidence": 0.99, "evidence": "Fixture: in-page check.", "metadata": {}}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence", judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    assert body.type_control_calls[:1] == [("#code", "555-123-4567")]
    assert len(body.clicks) == 1
    assert judged  # the chained click was consequence-checked before it ran


