def test_a_payment_final_click_never_uses_the_rerender_tolerance(monkeypatch) -> None:
    # A re-rendered page that keeps every control's label, value, and state may take an ordinary
    # final click; a payment stays bound to the exact page state it was approved on.
    init_db()

    class _RerenderedPaymentBody(_FinalSubmitBody):
        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            return {**shot, "document_state_signature": "v1:fresh-ids", "document_semantic_signature": "sv2:same"}

    outcomes: dict[bool, list] = {}
    for payment in (False, True):
        body = _RerenderedPaymentBody()
        pending = _approved_final_action(question_id=7300 + int(payment))
        pending["page_context"] = {
            "url": "https://example.test/apply",
            "document_state_signature": "v1:approved-ids",
            "document_semantic_signature": "sv2:same",
        }
        pending["payment"] = payment
        with SessionLocal() as db:
            user = models.User(email=f"final-pay-{uuid.uuid4().hex}@example.com", name="Final Pay")
            db.add(user)
            db.flush()
            run = models.OperatorRun(
                user_id=user.id,
                goal="Submit application",
                target_url="https://example.test/apply",
                current_state="WAITING_FOR_USER",
                confidence_state={"pending_final_action": pending},
            )
            db.add(run)
            db.commit()
            run_id, user_id = run.id, user.id

        async def narrate(kind: str, data: dict) -> None:
            pass

        monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
        monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
        monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
        monkeypatch.setattr(
            extension_run,
            "_final_action_outcome_verdict",
            lambda *args, **kwargs: {"status": "failed", "confidence": 0.99, "evidence": "Pending."},
        )
        monkeypatch.setattr(
            extension_run,
            "_decide_vision_action",
            lambda *args, **kwargs: {"action": "ask_user", "reason": "Review.", "question": "Review?", "options": []},
        )
        asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=2))
        outcomes[payment] = list(body.control_clicks)

    assert outcomes[False], "an ordinary final click proceeds on the semantic match"
    assert outcomes[True] == [], "a payment final click is refused before dispatch"


