def test_autonomous_consequential_step_on_a_generic_task_continues_to_the_models_done(monkeypatch) -> None:
    """A click the model proposed as an ordinary step, routed through the final-action path only by
    the safety gates and executed by standing autonomy, is one step of a delegated task: the loop
    re-observes and the model decides when the goal is done."""
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"generic-continue-{uuid.uuid4().hex}@example.test", name="Generic Continue")
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            goal="Work through every challenge on this page.",
            target_url="https://example.test/review",
            current_state="RUNNING",
        )
        db.add(run)
        db.commit()
        run_id, user_id = run.id, user.id
    body = _FinalSubmitBody()
    ordinary_step = {"action": "click", "x": 390, "y": 442, "reason": "Submit the embedded challenge form."}
    decisions = iter([ordinary_step, {"action": "done", "reason": "Every challenge on the page is complete."}])
    db_events: list[tuple[str, dict]] = []

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_final_action_mode_for_user", lambda user_id: "autonomous")
    monkeypatch.setattr(extension_run, "_payment_floor_verdict", lambda *args, **kwargs: {"payment": False, "deterministic_hit": False, "judge_payment": False, "summary": ""})
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        extension_run,
        "_final_action_outcome_verdict",
        lambda *args, **kwargs: {"status": "succeeded", "confidence": 0.99, "evidence": "The frame shows Accepted."},
    )
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))
    progress_marks: list[int] = []
    original_record = extension_run.BrainEscalation.record_progress

    def record_progress(self, *args, **kwargs):
        progress_marks.append(1)
        return original_record(self, *args, **kwargs)

    monkeypatch.setattr(extension_run.BrainEscalation, "record_progress", record_progress)

    summary = asyncio.run(
        run_vision_loop(body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=4)
    )

    assert body.control_clicks == [("#submit", 390, 442, True)]
    assert any(event == "FINAL_ACTION_AUTONOMOUSLY_AUTHORIZED" for event, _payload in db_events)
    # A verified consequential step is progress (v5_memory run 1713: a native app's submit changes no url or
    # title, and the same Approve radio of each next request counted toward being withheld).
    assert progress_marks, "the verified step resets the no-progress counters"
    # The run did not end on the click; the model's own done ended it.
    assert summary.get("reason") != "final_action_submitted"
    assert next(decisions, None) is None


_OPEN_PLAN = "[done] 1. Review" + chr(10) + "[ ] 4. Escalate SLA" + chr(10) + "[ ] 5. Close"


def _model_final_run(monkeypatch, decisions: list[dict], *, max_steps: int = 4, payment_on_call: int = 0, completion: list[str] | None = None, grade_log: list | None = None, delivery_only: bool = False, event_log: list | None = None):
    """A generic delegated run in Full autonomy whose decisions are scripted; returns (summary, body, contexts)."""
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"plan-open-{uuid.uuid4().hex}@example.test", name="Plan Open")
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            goal="Work every ticket in the helpdesk.",
            target_url="https://example.test/helpdesk",
            current_state="RUNNING",
        )
        db.add(run)
        db.commit()
        run_id, user_id = run.id, user.id
    class _StillReadyBody(_FinalSubmitBody):
        """Each ticket's page keeps showing the quoted control text, so every approval context stays grounded."""

        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            shot["page_evidence"]["viewport_text"] = "Ready to submit application."
            return shot

    body = _StillReadyBody()
    queue = itertools.chain(iter(decisions), itertools.repeat({"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}))
    contexts: list[dict] = []

    def decide(_user_id, _image, _view, context):
        contexts.append(dict(context))
        return dict(next(queue, {"action": "wait", "wait_ms": 100, "reason": "Pause."}))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_final_action_mode_for_user", lambda user_id: "autonomous")
    floor_calls: list[int] = []

    def floor(*args, **kwargs):
        floor_calls.append(1)
        paying = payment_on_call and len(floor_calls) >= payment_on_call
        return {"payment": bool(paying), "deterministic_hit": False, "judge_payment": False, "summary": "Pays." if paying else ""}

    monkeypatch.setattr(extension_run, "_payment_floor_verdict", floor)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: (event_log.append((event_type, payload)) if event_log is not None else None))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        extension_run,
        "_final_action_outcome_verdict",
        lambda *args, **kwargs: {"status": "succeeded", "confidence": 0.99, "evidence": "The fixture confirmation is visible."},
    )
    verdicts = iter(completion or [])

    def grade(*args, **kwargs):
        if grade_log is not None:
            grade_log.append(kwargs)
        verdict = next(verdicts, "complete")
        if verdict == "raise":
            raise RuntimeError("grader down")
        return {
            "verdict": verdict,
            "verified_summary": "The page shows it.",
            "missing": "the Notice period value",
            "missing_only_delivery": bool(delivery_only and verdict == "incomplete"),
        }

    monkeypatch.setattr(extension_run, "_verify_task_completion", grade)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    summary = asyncio.run(
        run_vision_loop(body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=max_steps)
    )
    return summary, body, contexts


def test_model_declared_final_with_open_plan_parts_continues(monkeypatch) -> None:
    # Run 1779 shape: the model's final action verified while its own plan still lists open parts.
    summary, body, contexts = _model_final_run(
        monkeypatch, [{**_final_click_decision("Close the ticket."), "plan": _OPEN_PLAN}], max_steps=3
    )
    assert body.control_clicks == [("#submit", 390, 442, True)], "the final action ran once and stays verified"
    assert summary.get("reason") != "final_action_submitted"  # a later graded done may still end COMPLETED
    lines = contexts[1]["recent_actions"]
    assert any("consequential_action_verified" in line and "[ ] 4. Escalate SLA" in line for line in lines)
    assert any("plan_open_parts" in line for line in lines)


def test_model_declared_final_without_open_plan_parts_stays_terminal(monkeypatch) -> None:
    plan = "[done] 1. Review" + chr(10) + "[done] 2. Close"
