def test_a_bounced_done_answer_is_pending_not_delivered_and_the_accepted_one_is(monkeypatch) -> None:
    plan = "[done] 1. Find the password"
    bounced = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Reported.", "answer": "first-try", "plan": plan}
    accepted = {**bounced, "answer": "second-try"}
    log: list = []
    _summary, _body, contexts = _model_final_run(
        monkeypatch, [bounced, {**_final_click_decision("Reveal."), "plan": plan}, accepted],
        max_steps=5, completion=["incomplete", "incomplete", "complete"], grade_log=log, delivery_only=True,
    )
    # The bounced done is graded with its own answer, but the user never saw it: the later final-action grade
    # sees nothing delivered, and the send-back asks for the answer again.
    assert log[0]["delivered_answer"] == "first-try"
    assert log[1]["delivered_answer"] == ""
    assert any("was not shown to the user" in line for line in contexts[2]["recent_actions"])
    assert log[2]["delivered_answer"] == "second-try"


