def test_model_declared_final_inconclusive_grade_is_sent_back_never_completed_and_never_repeated(monkeypatch) -> None:
    # Run 1857 shape: the grader answered unavailable after the final click. That is never "complete": the run
    # goes back to the brain like an incomplete grade, and the action that already succeeded is not repeated.
    plan = "[done] 1. Review"
    for grade in ("unverified", "unavailable", "raise", "garbled"):
        summary, body, contexts = _model_final_run(
            monkeypatch,
            [{**_final_click_decision("Close."), "plan": plan}, {**_final_click_decision("Close again."), "plan": plan}],
            max_steps=4,
            completion=[grade],
        )
        assert summary.get("reason") != "final_action_submitted", grade
        assert len(body.control_clicks) == 1, grade
        assert any("SUCCEEDED" in line and "could not run" in line and "finish" not in line.lower() for line in contexts[1]["recent_actions"]), grade
        assert any("final_action_repeat_refused" in line for line in contexts[2]["recent_actions"]), grade


