def test_distinct_invalid_value_fingerprints_activate_exact_control_kind_cooldown(monkeypatch) -> None:
    init_db()
    body = _SiblingRepeatedInvalidTypeRecoveryBody()
    contexts: list[dict] = []
    events: list[tuple[str, dict]] = []
    decisions = iter(
        [
            _invalid_contact_type(control=1, x=220, text="555-123-4567"),
            _invalid_contact_type(control=1, x=220, text="(555) 123-4567"),
            _invalid_contact_type(control=1, x=220, text="5551234567"),
            {
                "action": "ask_user",
                "control": 1,
                "x": 220,
                "y": 140,
                "question": "Contact number *",
                "options": [],
                "proposed_answer": "",
                "reason": "Fresh evidence still rejects faithful formats of the grounded value.",
            },
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return next(decisions)

    _patch_invalid_type_recovery_dependencies(monkeypatch, events)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=6,
        )
    )

    assert summary["state"] == "WAITING_FOR_USER"
    assert body.typed_values == [
        ("#contact-primary", "555-123-4567"),
        ("#contact-primary", "(555) 123-4567"),
    ]
    recovery_context = next(
        context for context in reversed(contexts) if context.get("recovery_constraints")
    )
    constraint = recovery_context["recovery_constraints"][0]
    assert constraint["rule"] == "same_exact_control_action_kind_is_withheld_until_durable_progress"
    assert constraint["distinct_fingerprint_count"] == 2
    assert constraint["withheld_until"] == "durable_progress_elsewhere"
    blocked_event = next(
        payload
        for event_type, payload in events
        if event_type == "VISION_ACTION_PRECONDITION_BLOCKED"
        and payload.get("constraint_rule")
        == "same_exact_control_action_kind_is_withheld_until_durable_progress"
    )
    assert blocked_event["distinct_fingerprint_count"] == 2
    assert blocked_event["fresh_observation_required"] is True


def test_exact_control_kind_cooldown_repeated_violations_end_as_engineering_block(monkeypatch) -> None:
    init_db()
    body = _SiblingRepeatedInvalidTypeRecoveryBody()
    contexts: list[dict] = []
    events: list[tuple[str, dict]] = []
    decisions = iter(
        [
            _invalid_contact_type(control=1, x=220, text="555-123-4567"),
            _invalid_contact_type(control=1, x=220, text="(555) 123-4567"),
            _invalid_contact_type(control=1, x=220, text="5551234567"),
            _invalid_contact_type(control=1, x=220, text="555.123.4567"),
            _invalid_contact_type(control=1, x=220, text="555 123 4567"),
            _invalid_contact_type(control=1, x=220, text="555/123/4567"),
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return next(decisions)

    _patch_invalid_type_recovery_dependencies(monkeypatch, events)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=6,
        )
    )

    aggregate_rule = "same_exact_control_action_kind_is_withheld_until_durable_progress"
    assert summary["state"] == "BLOCKED"
    assert summary["reason"] == "no_progress"
    assert summary["original_reason"] == "recovery_constraint_ignored"
    assert summary["block_kind"] == "awaiting_engineering"
    assert summary["system_block"] is True
    assert summary["needs_user"] is False
    assert summary["constraint_rule"] == aggregate_rule
    assert summary["distinct_fingerprint_count"] == 2
    assert body.typed_values == [
        ("#contact-primary", "555-123-4567"),
        ("#contact-primary", "(555) 123-4567"),
    ]
    guards = [
        receipt
        for receipt in summary["receipts"]
        if receipt.get("outcome") == "precondition_failed"
    ]
    assert len(guards) == 4
    assert all(
        receipt["attempt"]["constraint_rule"] == aggregate_rule
        for receipt in guards
    )
    exhausted = next(
        payload
        for event_type, payload in events
        if event_type == "VISION_ACTION_PRECONDITION_RECOVERY_EXHAUSTED"
    )
    assert exhausted["constraint_rule"] == aggregate_rule
    assert exhausted["block_kind"] == "awaiting_engineering"


