def test_safe_row_digests_keeps_only_a_bounded_well_formed_list() -> None:
    good = [
        {"selector": "#username", "frame": 0, "digest": "row1:1:2"},
        {"selector": "", "frame": 0, "digest": "title1:3:4"},
    ]
    assert _safe_row_digests(good) == good
    assert _safe_row_digests(None) == []
    assert _safe_row_digests("row") == []
    # A bool is not a frame flag; anything but 0 or 1 is not a frame flag either.
    assert _safe_row_digests([{"selector": "#a", "frame": True, "digest": "d"}]) == []
    assert _safe_row_digests([{"selector": "#a", "frame": 2, "digest": "d"}]) == []
    assert _safe_row_digests([{"selector": 3, "frame": 0, "digest": "d"}]) == []
    assert _safe_row_digests([{"selector": "#a", "frame": 0, "digest": ""}]) == []
    assert _safe_row_digests([{"selector": "#a", "frame": 0, "digest": "d"}, "x"]) == []
    # Over the extension's cap (240 rows plus the title) the list proves nothing, so it is withheld.
    assert _safe_row_digests([{"selector": "#a", "frame": 0, "digest": "d"}] * 242) == []


def test_type_expected_page_context_attaches_row_digests_only_for_a_credential() -> None:
    shot = {
        "url": "https://login.example.test/sign-in",
        "surface_signature": "surface-1",
        "document_lifecycle_token": "doc-1",
        "document_state_signature": "state-1",
        "document_row_digests": [
            {"selector": "#username", "frame": 0, "digest": "u1"},
            {"selector": "", "frame": 0, "digest": "t1"},
        ],
    }
    plain = _type_expected_page_context(shot, credential_replay=False)
    assert "document_row_digests" not in plain
    assert plain["document_lifecycle_token"] == "doc-1"

    credential = _type_expected_page_context(shot, credential_replay=True)
    assert credential["document_row_digests"] == shot["document_row_digests"]
    assert credential["document_lifecycle_token"] == "doc-1"

    # No rows in the observation: the credential's expected context carries none, so the extension keeps
    # the strict whole-page check.
    bare = _type_expected_page_context(
        {"url": "https://login.example.test/sign-in", "document_lifecycle_token": "doc-1"},
        credential_replay=True,
    )
    assert bare["document_row_digests"] == []


