class _LifecycleRefusalBody(_PreActionRevalidationBody):
    """Never clicks: every click is withheld before dispatch with one page-context field."""

    def __init__(self, field: str) -> None:
        super().__init__()
        self.field = field

    async def vision_click_control(
        self,
        selector: str,
        fallback_x: int,
        fallback_y: int,
        **_expected_binding: object,
    ) -> dict:
        self.control_clicks.append((selector, fallback_x, fallback_y))
        return {
            "ok": False,
            "action": "click",
            "mode": "control_selector",
            "failure_reason": "page_context_drift",
            "page_context_mismatch_field": self.field,
            "activation_attempted": False,
            "activation_dispatched": False,
            "activation_count": 0,
        }


@pytest.mark.parametrize(
    ("field", "phrase"),
    [
        ("document_lifecycle_token", "the browser's document identity for this page no longer matches"),
        ("document_state_signature", "the page's controls, or a control's value, changed"),
    ],
)
def test_repeated_revalidation_refusal_names_the_changed_part(monkeypatch, field: str, phrase: str) -> None:
    # Run 1794: eight identical withheld credential typings, each with the same unnamed reason. The first
    # refusal must now say which part of the page changed, and the warning after three repeats must too.
    init_db()
    body = _LifecycleRefusalBody(field)
    contexts: list[dict] = []
    db_events: list[tuple[str, dict]] = []
    decisions = iter(
        [
            {
                "action": "click",
                "control": 1,
                "x": 220,
                "y": 140,
                "text": "",
                "reason": f"Open the options control from fresh observation {attempt}.",
            }
            for attempt in range(1, 5)
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        pass

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return next(decisions)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda run_id, event_type, payload: db_events.append((event_type, payload)),
    )
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=4,
        )
    )

    recent = [item for context in contexts[1:] for item in context.get("recent_actions", [])]
    first = next(item for item in recent if item.startswith("stale_observation:"))
    assert phrase in first
    warned = [item for item in recent if item.startswith("repeated_revalidation_failure:")]
    assert warned, "the third identical refusal must warn"
    assert phrase in warned[0]


