class _OffScreenControlBody:
    """A page whose Save control (stable id 7) lies below the viewport until the body scrolls it into view."""

    def __init__(self, *, scroll_result: dict | None = None, label: str = "Email address") -> None:
        self.scrolled = False
        self.scroll_calls: list[tuple[str, dict]] = []
        self.control_clicks: list[str] = []
        self.clicked = False
        self.label = label
        self.scroll_result = scroll_result or {"ok": True, "in_view": True, "scrolled_into_view": True}

    async def capture_screenshot(self) -> dict:
        controls = []
        if not self.clicked:
            controls.append({"index": 1, "tag": "input", "type": "text", "role": "", "text": "", "context_text": "Name",
                             "value": "", "selector": "#name", "x": 100, "y": 120, "width": 240, "height": 40})
            if self.scrolled:
                controls.append({"index": 7, "tag": "input", "type": "text", "role": "", "text": "", "context_text": self.label,
                                 "value": "", "selector": "#far", "x": 100, "y": 300, "width": 240, "height": 40})
        evidence = {"viewport_text": "Name", "controls": controls}
        if not self.scrolled and not self.clicked:
            evidence["remembered_controls"] = [{
                "index": 7, "page": "https://example.test/apply", "selector": "#far", "tag": "input", "role": "",
                "type": "text", "name": self.label.lower(),
            }]
        return {"ok": True, "image": "jpeg", "width": 800, "height": 600, "url": "https://example.test/apply",
                "title": "Apply", "scroll_y": 0, "scroll_height": 600, "page_evidence": evidence}

    async def vision_scroll_into_view(self, selector: str, *, expected_target_identity: dict | None = None, **_kw: object) -> dict:
        self.scroll_calls.append((selector, dict(expected_target_identity or {})))
        if self.scroll_result.get("ok"):
            self.scrolled = True
        return dict(self.scroll_result)

    async def vision_click_control(self, selector: str, fallback_x: int, fallback_y: int, **_binding: object) -> dict:
        self.clicked = True
        self.control_clicks.append(selector)
        return {"ok": True, "action": "click", "mode": "control_selector", "active_typable": False}


def _run_off_screen_loop(monkeypatch, body, decisions, *, max_steps: int = 5):
    init_db()
    contexts: list[dict] = []
    queue = itertools.chain(iter(decisions), itertools.repeat({"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}))

    async def narrate(kind: str, data: dict) -> None:
        pass

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return next(queue)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=max_steps))
    return summary, contexts


def test_vision_loop_off_screen_remembered_id_is_scrolled_into_view_then_reissued_through_the_gates(monkeypatch) -> None:
    body = _OffScreenControlBody()
    click = {"action": "click", "control": 7, "x": 0, "y": 0, "reason": "Save the draft."}
    summary, contexts = _run_off_screen_loop(
        monkeypatch, body, [dict(click), dict(click), {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}]
    )
    assert body.scroll_calls == [("#far", {"tag": "input", "role": "", "type": "text"})]
    # The scroll step ran nothing else; the click ran once, on the fresh observation, by the control's selector.
    assert body.control_clicks == ["#far"], ([c.get("recent_actions") for c in contexts], {k: summary.get(k) for k in ("state", "reason")})
    assert any("scrolled into view" in item and "NOT RUN" in item for item in contexts[1]["recent_actions"])
    assert summary["state"] == "READY_FOR_REVIEW", ({k: summary.get(k) for k in ("state", "reason")}, [c.get("recent_actions") for c in contexts])


def test_vision_loop_off_screen_id_that_vanishes_after_the_scroll_is_refused_once(monkeypatch) -> None:
    body = _OffScreenControlBody(label="Email address")
    # The body scrolls but the next observation never lists id 7 (the element changed identity).
    body.scroll_result = {"ok": True, "in_view": True}

    async def capture_without_it() -> dict:
        shot = await _OffScreenControlBody.capture_screenshot(body)
        shot["page_evidence"]["controls"] = [c for c in shot["page_evidence"]["controls"] if c["index"] != 7]
        shot["page_evidence"]["remembered_controls"] = [{
            "index": 7, "page": "https://example.test/apply", "selector": "#far", "tag": "input", "role": "",
            "type": "text", "name": "email address",
        }]
        return shot

    body.capture_screenshot = capture_without_it  # type: ignore[method-assign]
    click = {"action": "click", "control": 7, "x": 0, "y": 0, "reason": "Save the draft."}
    summary, contexts = _run_off_screen_loop(
        monkeypatch, body, [dict(click), dict(click), {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}]
    )
    assert len(body.scroll_calls) == 1
    assert body.control_clicks == []
    assert any("control_off_screen_unreachable" in item for item in contexts[2]["recent_actions"])


