def test_vision_loop_model_arbitrates_conflicting_index_and_coordinate_without_a_keyword_rule(monkeypatch) -> None:
    init_db()
    body = _ConflictingControlReferenceBody()
    events: list[tuple[str, dict]] = []
    question = "How many years of professional software engineering experience do you have?"
    decisions = iter(
        [
            {
                # The inventory index is stale, while the screenshot point is on the intended field.
                # There is no explicit option text, so deterministic exact-text repair cannot decide.
                "action": "click",
                "control": 7,
                "x": 200,
                "y": 240,
                "question": question,
                "reason": "Open the visible experience dropdown.",
            },
            {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Review is ready."},
        ]
    )
    judge_calls: list[dict] = []

    def reference_judge(user_id: int, **kwargs) -> dict:
        judge_calls.append(kwargs)
        assert kwargs["indexed_control"]["selector"] == "#sponsorship"
        assert kwargs["coordinate_control"]["selector"] == "#experience"
        assert kwargs["action"]["question"] == question
        return {"choice": "coordinate", "reason": "The coordinate candidate carries the stated question."}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_control_reference_judge", reference_judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=lambda *args, **kwargs: asyncio.sleep(0),
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=4,
        )
    )

    assert summary["state"] == "READY_FOR_REVIEW"
    assert len(judge_calls) == 1
    assert body.control_clicks == [("#experience", 200, 240)]
    verdict = next(payload for event, payload in events if event == "VISION_CONTROL_REFERENCE_JUDGE_VERDICT")
    assert verdict["choice"] == "coordinate"
    reconciled = next(payload for event, payload in events if event == "VISION_CONTROL_REFERENCE_RECONCILED")
    assert reconciled["resolution_source"] == "model_coordinate"


