def test_vision_loop_control_reference_judge_that_never_answers_is_ambiguous_not_a_hang(monkeypatch) -> None:
    # v5_reconcile run 1718 waited 83 minutes on this judge while DNS lookups failed.
    import time as _time

    init_db()
    body = _ConflictingControlReferenceBody()
    events: list[tuple[str, dict]] = []
    contexts: list[dict] = []

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        if len(contexts) == 1:
            return {
                "action": "click",
                "control": 7,
                "x": 200,
                "y": 240,
                "question": "How many years of professional software engineering experience do you have?",
                "reason": "Open the experience dropdown.",
            }
        return {"action": "ask_user", "question": "Which control should I use?", "options": [], "reason": "No verdict."}

    def stalled_judge(*args, **kwargs) -> dict:
        _time.sleep(1.0)
        return {"choice": "coordinate", "reason": "too late"}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_CONTROL_REFERENCE_JUDGE_TIMEOUT_SECONDS", 0.1)
    monkeypatch.setattr(extension_run, "_call_control_reference_judge", stalled_judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    started = _time.monotonic()
    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=lambda *args, **kwargs: asyncio.sleep(0),
            run_id=0,
            user_id=0,
            skip_navigate=True,
            max_steps=3,
        )
    )

    assert _time.monotonic() - started < 30
    verdict = next(payload for event, payload in events if event == "VISION_CONTROL_REFERENCE_JUDGE_VERDICT")
    assert verdict["choice"] == "ambiguous"
    assert verdict["reason"] == "control_reference_judge_timeout"
    # No verdict is no permission: the conflicting click is withheld.
    assert body.control_clicks == []
    assert summary["state"] == "WAITING_FOR_USER"


