def test_vision_loop_empty_completion_uses_reduced_payload_then_engineering_block(monkeypatch) -> None:
    init_db()
    body = _ChoiceBody()
    events: list[tuple[str, dict]] = []
    db_events: list[tuple[str, dict]] = []
    contexts: list[dict] = []

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return {
            "_outcome_type": "empty_completion",
            "failure_reason": "provider_empty_output",
            "_model_metadata": {
                "provider": "openrouter",
                "model": "vision-model",
                "parse_status": "empty",
                "raw_output_empty": True,
                "raw_output_chars": 0,
                "finish_reason": "length",
                "max_tokens": 3000,
            },
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr("app.lumen_model.LumenModelClient.judge_grounding", lambda self, **kwargs: {"grounded": False, "entry_index": -1, "reason": "Not supported."})
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))

    assert summary["state"] == "BLOCKED"
    assert summary["reason"] == "provider_empty_output_exhausted"
    assert summary["block_kind"] == "awaiting_engineering"
    assert summary["system_block"] is True
    # Every step's capped reply is retried once within the step (the odd calls), told it was cut off;
    # each retry caps again, so three steps reach the ladder.
    assert len(contexts) == 6
    assert contexts[0].get("payload_mode") is None
    assert contexts[0].get("max_tokens_override") is None
    assert "reply_cut_off" not in contexts[0]
    assert contexts[1]["reply_cut_off"]["max_tokens"] == 3000
    assert contexts[1].get("payload_mode") is None
    # A reply that ran into the output cap skips the same-payload retry: the smaller payload comes next.
    assert contexts[2]["payload_mode"] == "reduced_after_empty_completion"
    # Escalation rung is 2x the base (3000 -> 6000), capped at 8192 since the failover work.
    assert contexts[2]["max_tokens_override"] == 6000
    assert "reply_cut_off" not in contexts[2]
    assert contexts[4]["payload_mode"] == "reduced_after_empty_completion"
    assert contexts[4]["max_tokens_override"] == 6000
    assert [event for event, _ in db_events].count("VISION_MODEL_EMPTY_COMPLETION") == 3
    assert [event for event, _ in db_events].count("VISION_MODEL_REPLY_CUT_OFF") == 3
    assert summary["model_attempts"][-1]["finish_reason"] == "length"
    assert summary["model_attempts"][-1]["max_tokens"] == 3000
    assert any(kind == "stop" and data.get("reason") == "provider_empty_output_exhausted" for kind, data in events)


