def test_vision_loop_length_empty_upgrades_base_before_retry_timeout(monkeypatch) -> None:
    init_db()
    body = _ChoiceBody()
    contexts: list[dict] = []
    saved_profiles: list[dict] = []
    calls = {"count": 0}

    async def narrate(kind: str, data: dict) -> None:
        pass

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        calls["count"] += 1
        if calls["count"] == 1:
            return {
                "_outcome_type": "empty_completion",
                "failure_reason": "provider_empty_output",
                "_model_metadata": {
                    "provider": "openrouter",
                    "model": "vision-model",
                    "parse_status": "empty",
                    "raw_output_empty": True,
                    "finish_reason": "length",
                    "max_tokens": 2048,
                },
            }
        raise asyncio.TimeoutError("simulated retry timeout")

    async def fake_save(profile: dict, *, force: bool = False, run_id: int | None = None) -> bool:
        saved_profiles.append(dict(profile))
        return True

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_vision_profile_key_for_user", lambda user_id: ("openrouter", "vision-model"))
    monkeypatch.setattr(extension_run, "_save_vision_decision_profile_async", fake_save)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
