def test_vision_loop_choice_equivalence_executes_via_grounding_judge(monkeypatch) -> None:
    init_db()
    body = _CountryChoiceBody()
    db_events: list[tuple[str, dict]] = []
    judge_calls: list[dict] = []
    runtime_provider = _resolved_vision_provider(
        55,
        display_name="Run vision provider",
        provider_type="gemini",
        model_name="gemini-test",
    )
    decisions = iter(
        [
            {"action": "click", "x": 20, "y": 146, "text": "United States", "question": "Country", "reason": "Select the country from profile data."},
            {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Review is ready."},
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        pass

    def judge(
        self,
        *,
        control: str,
        value: str,
        entries: list[dict],
        interaction_context: dict | None = None,
        primary_provider_id: int | None = None,
        image=None,
    ) -> dict:
        judge_calls.append(
            {
                "control": control,
                "value": value,
                "entries": entries,
                "primary_provider_id": primary_provider_id,
                "image": image,
            }
        )
        assert all(entry["source"] != "page" for entry in entries)
        assert any(entry["source"] == "profile" and entry["value"] == "USA" for entry in entries)
        return {
            "grounded": True,
            "entry_index": next(
                index
                for index, entry in enumerate(entries)
                if entry["value"] == "USA"
            ),
            "status": "grounded",
            "reason": "USA is equivalent to United States.",
            "metadata": {
                "provider": "gemini",
                "provider_id": 55,
                "model": "gemini-test",
                "finish_reason": "STOP",
                "parse_status": "json",
                "max_tokens": 1024,
                "attempt_count": 1,
                "normalization": "validated",
            },
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _CountryContextEngine)
    monkeypatch.setattr(
        extension_run,
        "_vision_provider_for_user",
        lambda user_id: runtime_provider,
    )
    monkeypatch.setattr("app.lumen_model.LumenModelClient.judge_grounding", judge)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.clicks == [(20, 146)]
    assert len(judge_calls) == 1
    assert judge_calls[0]["primary_provider_id"] == 55
    verdict = next(
        payload
        for event, payload in db_events
        if event == "VISION_GROUNDING_JUDGE_VERDICT"
        and payload.get("grounded") is True
        and payload.get("cached") is False
    )
    assert verdict["judge_status"] == "grounded"
    assert verdict["provider_id"] == 55
    assert verdict["model"] == "gemini-test"
    assert verdict["finish_reason"] == "STOP"
    assert verdict["parse_status"] == "json"
    assert verdict["reason"] == "USA is equivalent to United States."
    step_timings = [payload for event, payload in db_events if event == "STEP_TIMING"]
    assert step_timings[0]["judge_ms"] >= 0
    click_receipt = next(receipt for receipt in summary["receipts"] if receipt["target"]["label"].startswith("Select"))
    assert click_receipt["verification"]["grounding_source"] == "profile:judge"


