def test_grounding_judge_cache_key_changes_with_question_relationship_or_candidates() -> None:
    base_context = {
        "model_stated_question": "Country",
        "selected_control": {"index": 6, "text": "United States +1"},
        "target_binding_verification": {"verified": True},
    }
    sparse_entries = [
        {"source": "profile", "label": "identity.name", "value": "Jordan Park"}
    ]
    rich_entries = [
        *sparse_entries,
        {"source": "profile", "label": "country", "value": "United States"},
    ]

    sparse = extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context=base_context,
        entries=sparse_entries,
    )
    rich = extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
    )
    changed_question = extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context={**base_context, "model_stated_question": "Phone country code"},
        entries=rich_entries,
    )

    assert sparse != rich
    assert rich != changed_question
    assert rich != extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
        primary_provider_id=55,
    )
    assert rich != extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
        primary_provider_identity=(
            "env",
            "openrouter",
            "env-vision-model",
            "https://provider.example.test/v1",
        ),
    )
    assert rich != extension_run._vision_grounding_judge_cache_key(
        "United States (+1)",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
    )
    assert extension_run._vision_grounding_judge_cache_key(
        "C",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
    ) != extension_run._vision_grounding_judge_cache_key(
        "C++",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
    )
    assert rich == extension_run._vision_grounding_judge_cache_key(
        "United States +1",
        "option:6",
        interaction_context=base_context,
        entries=rich_entries,
    )


def test_generic_grounding_rejection_retrieves_model_stated_evidence_before_asking(monkeypatch) -> None:
    init_db()
    # This test is about retrieval before asking: no profile is preloaded and no documents extracted.
    monkeypatch.setattr(extension_run, "_compact_profile_safe", lambda _user_id: ({}, []))
    monkeypatch.setattr(extension_run, "_ensure_documents_extracted_safe", lambda _user_id: {"status": "current"})
    with SessionLocal() as db:
        user = models.User(
            email=f"grounding-retrieval-{uuid.uuid4().hex}@example.test",
            name="Grounding Retrieval",
        )
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            application_id=None,
            goal="Complete the visible form using saved profile evidence.",
            target_url="https://example.test/apply",
            current_state="RUNNING",
            confidence_state={
                "browser_task": {
                    "candidate_data_access": "on_demand",
                    "candidate_data_scopes": ["profile", "resume"],
                }
            },
        )
        db.add(run)
        db.commit()
        run_id = int(run.id)
        user_id = int(user.id)

    body = _CountryDialCodeChoiceBody()
    unrelated_query = "Retrieve an unrelated saved preference."
    value_action = {
        "action": "click",
        "control": 6,
        "x": 160,
        "y": 146,
        "text": "United States +1",
        "question": "Country",
        "grounding_source": "profile",
        "grounding_quote": "United States",
        "reason": "Select the country option supported by profile evidence.",
    }
    decisions = iter(
        [
            {
                "action": "query_candidate",
                "query": unrelated_query,
                "source_scope": "profile",
                "x": 0,
                "y": 0,
                "reason": "Inspect an authorized saved fact before handling the visible choice.",
            },
            dict(value_action),
            dict(value_action),
            dict(value_action),
            dict(value_action),
            {
                "action": "done",
                "x": 0,
                "y": 0,
                "artifact_role": "",
                "reason": "Review is ready.",
            },
        ]
    )
    retrievals: list[dict] = []
    judge_calls: list[dict] = []
    decision_contexts: list[dict] = []
    db_events: list[tuple[str, dict]] = []

    def retrieve(
        user_id: int,
        *,
        query: str,
        source_scope: str,
        context: dict,
        excluded_facts: list[dict] | None = None,
        task_context: dict | None = None,
    ) -> dict:
        assert excluded_facts is None
        retrievals.append({"query": query, "source_scope": source_scope})
        facts = (
            [
                {
                    "source": "resume",
                    "label": "resume.location",
                    "value": "United States",
                }
            ]
            if query == "Country"
            else []
        )
        return {
            "facts": facts,
            "reason": "The country fact matches the model-stated question.",
            "metadata": {"provider": "fixture", "model": "fixture-retriever"},
            "fallback": False,
            "candidate_count": len(facts),
        }

    def judge_grounding(self, **kwargs) -> dict:
        judge_calls.append(kwargs)
        return {
            "grounded": True,
            "entry_index": 0,
            "reason": "The country fact supports the selected option.",
        }

    monkeypatch.setattr(
        "app.lumen_model.LumenModelClient.judge_target_binding",
        lambda self, **kwargs: {
            "matches": True,
            "reason": "The option belongs to the Country combobox.",
            "metadata": {},
        },
    )
    monkeypatch.setattr(
        "app.lumen_model.LumenModelClient.judge_grounding",
        judge_grounding,
    )
    # One normal model-owned query consumes its complete distinct-query budget. The
    # verifier-owned grounding evidence ladder must retain an independent bounded budget.
    monkeypatch.setattr(extension_run, "_CANDIDATE_QUERY_MAX_DISTINCT", 1)
    monkeypatch.setattr(extension_run, "_retrieve_candidate_evidence", retrieve)
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda run_id, event_type, payload: db_events.append(
            (event_type, payload)
        ),
    )
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)

    def decide(*args, **kwargs) -> dict:
        context = kwargs.get("context") or args[3]
        action = next(decisions)
        decision_contexts.append(
            {
                "action": action["action"],
                "retrieved_candidate_facts": list(
                    context.get("retrieved_candidate_facts") or []
                ),
            }
        )
        return action

    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=lambda *args, **kwargs: asyncio.sleep(0),
            run_id=run_id,
            user_id=user_id,
            skip_navigate=True,
            max_steps=8,
        )
    )

    assert summary["state"] == "READY_FOR_REVIEW"
    assert retrievals == [
        {"query": unrelated_query, "source_scope": "profile"},
        {"query": "Country", "source_scope": "all"},
    ]
    value_contexts = [
        item for item in decision_contexts if item["action"] == "click"
    ]
    assert [
        item["retrieved_candidate_facts"] for item in value_contexts[:3]
    ] == [[], [], []]
    assert value_contexts[3]["retrieved_candidate_facts"] == [
        {
            "source": "resume",
            "label": "resume.location",
            "value": "United States",
        }
    ]
    assert len(judge_calls) == 1
    assert judge_calls[0]["entries"][0]["source"] == "resume"
    assert judge_calls[0]["entries"][0]["value"] == "United States"
    assert judge_calls[0]["interaction_context"]["model_stated_question"] == "Country"
    recovery_event = next(
        payload
        for event, payload in db_events
        if event == "VISION_CANDIDATE_EVIDENCE_RETRIEVED"
        and payload.get("trigger") == "grounding_rejection_before_user_question"
    )
    assert recovery_event["budget_owner"] == "grounding_recovery"
    assert body.clicks == [(160, 146)]
    with SessionLocal() as db:
        questions = list(
            db.execute(
                select(models.OperatorQuestion).where(
                    models.OperatorQuestion.run_id == run_id
                )
            ).scalars()
        )
    assert questions == []


