def test_vision_loop_option_click_without_text_derives_then_escalates_when_ungrounded(monkeypatch) -> None:
    init_db()
    body = _ChoiceBody()
    events: list[tuple[str, dict]] = []
    db_events: list[tuple[str, dict]] = []
    contexts: list[dict] = []

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return {
            "action": "click",
            "x": 20,
            "y": 146,
            "text": "",
            "question": "Visible choice question",
            "reason": "Click the visible option.",
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr("app.lumen_model.LumenModelClient.judge_grounding", lambda self, **kwargs: {"grounded": False, "entry_index": -1, "reason": "Not supported."})
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))

    assert summary["state"] == "WAITING_FOR_USER"
    assert summary["reason"] == "needs_answer"
    ask = summary["ask"]
    assert ask["label"] == "Visible choice question"
    assert ask["required"] is True
    assert ask["is_unsure"] is True
    assert ask["element_ref"]["role"] == "div/option"
    assert ask["element_ref"]["control_signature"]
    assert body.clicks == []
    assert [event for event, _ in db_events].count("VISION_GROUNDING_CITATION_REJECTED") == 4
    assert any(
        payload.get("reason") == "choice_click_ungrounded"
        and payload.get("derived_text") is True
        and payload.get("derived_choice_text") == "Option A"
        for event, payload in db_events
        if event == "VISION_GROUNDING_CITATION_REJECTED"
    )
    assert any("Option A" in item and "not grounded" in item for item in contexts[-1]["recent_actions"])
    assert any(
        kind == "ask"
        and data.get("label") == "Visible choice question"
        and data.get("options") == []
        for kind, data in events
    )
    assert any(
        event == "VISION_GROUNDING_RECOVERY_EXHAUSTED"
        and payload.get("user_question_persisted") is True
        and payload.get("browser_mutation_attempted") is False
        for event, payload in db_events
    )


