def test_vision_loop_composed_textarea_accepts_short_resume_quote(monkeypatch) -> None:
    init_db()
    long_answer = "I have built AI automation for support workflows, and I would bring that experience to this role."
    body = _TextareaBody(observed_value=long_answer)
    grounding_judge_calls: list[dict] = []
    decisions = iter(
        [
            {"action": "click", "x": 220, "y": 160, "reason": "Focus the textarea."},
            {
                "action": "type",
                "x": 0,
                "y": 0,
                "text": long_answer,
                "grounding_source": "resume",
                "grounding_quote": "Built AI automation for support workflows",
                "reason": "Type a composed answer grounded in the resume.",
            },
            {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Review is ready."},
        ]
    )

    async def narrate(kind: str, data: dict) -> None:
        pass

    def judge_grounding(
        self,
        *,
        control: str,
        value: str,
        entries: list[dict],
        interaction_context: dict | None = None,
        primary_provider_id: int | None = None,
    ) -> dict:
        grounding_judge_calls.append(
            {
                "control": control,
                "value": value,
                "entries": entries,
                "interaction_context": interaction_context,
            }
        )
        entry_index = next(
            index
            for index, entry in enumerate(entries)
            if entry["source"] == "resume" and "Built AI automation for support workflows" in entry["value"]
        )
        return {
            "grounded": True,
            "entry_index": entry_index,
            "reason": "The composition faithfully renders the cited resume experience.",
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr("app.lumen_model.LumenModelClient.judge_grounding", judge_grounding)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_resume_facts_for_user_safe", lambda user_id: {"resume_text": "Built AI automation for support workflows."})
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.typed_values == [long_answer]
    assert len(grounding_judge_calls) == 1


def test_vision_loop_long_composition_is_claim_judged_before_typing(monkeypatch) -> None:
    init_db()
