def test_a_failed_claim_judge_call_is_not_cached_for_the_run(monkeypatch) -> None:
    # The error record used to be cached (and persisted), so every later attempt at the same answer
    # was rejected without asking the judge again.
    init_db()
    long_answer = (
        "I built an AI support workflow grounded in documented user feedback and operating needs. "
        "I collaborated with teammates, tested the workflow carefully, and used what I learned to "
        "improve the implementation while keeping the response accurate, reliable, and useful."
    )
    assert len(long_answer) >= 200
    with SessionLocal() as db:
        user = models.User(email=f"claim-cache-{uuid.uuid4().hex}@example.test", name="Claim Cache")
        db.add(user)
        db.flush()
        application = models.Application(user_id=user.id, status="draft")
        db.add(application)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            application_id=application.id,
            goal="Complete the form",
            target_url="https://example.test/apply",
            current_state="RUNNING",
        )
        db.add(run)
        db.commit()
        run_id = run.id
        user_id = user.id

    db_events: list[tuple[str, dict]] = []
    judge_calls = {"count": 0}

    async def narrate(kind: str, data: dict) -> None:
        pass

    def judge(*args, **kwargs) -> dict:
        judge_calls["count"] += 1
        if judge_calls["count"] == 1:
            return {"supported": False, "unsupported_claims": [], "error": "provider timeout"}
        return {"supported": True, "unsupported_claims": []}

    action = {
        "action": "type",
        "control": 1,
        "x": 220,
        "y": 160,
        "text": long_answer,
        "grounding_source": "profile",
        "grounding_quote": "Jordan",
        "question": "Why are you interested in this role?",
        "reason": "Compose a grounded response for this question.",
    }
    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_call_claim_support_judge", judge)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(action))

    first_body = _TextareaBody(observed_value=long_answer)
    asyncio.run(run_vision_loop(first_body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=1))

    cache_key = extension_run._vision_claim_judge_cache_key(long_answer)
    with SessionLocal() as db:
        state = dict(db.get(models.OperatorRun, run_id).confidence_state or {})
        persisted = dict(state.get(extension_run._CLAIM_JUDGE_CACHE_STATE_KEY) or {})
    assert cache_key not in persisted
    assert first_body.typed_values == []

    second_body = _TextareaBody(observed_value=long_answer)
    asyncio.run(run_vision_loop(second_body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=1))

    verdicts = [payload for event, payload in db_events if event == "VISION_CLAIM_JUDGE_VERDICT"]
    assert [payload["cached"] for payload in verdicts] == [False, False]
    assert judge_calls["count"] == 2
    assert second_body.typed_values == [long_answer]


def test_claim_verdicts_are_keyed_on_the_exact_composition_and_its_evidence() -> None:
    key = extension_run._vision_claim_judge_cache_key
    assert key("I have 1.5 years of C experience.") != key("I have 15 years of C experience.")
    assert key("Five years of C.") != key("Five years of C++.")
    assert key("Five  years of C.") == key("five years of c.")
    digest = extension_run._vision_claim_judge_evidence_digest
    assert digest([{"source": "resume", "text": "A"}]) != digest([{"source": "resume", "text": "A"}, {"source": "memory", "text": "B"}])

def test_vision_loop_unsupported_long_claims_block_after_model_owned_replan(
    monkeypatch,
) -> None:
    init_db()
    long_answer = (
        "I created a chatbot serving 10K users and increased conversion by 80 percent across every workflow. "
        "The system eliminated all support delays, guaranteed perfect answers, and produced millions in revenue "
        "while reducing operating costs to zero for the entire organization."
    )
    assert len(long_answer) >= 200
    body = _TextareaBody(observed_value=long_answer)
    contexts: list[dict] = []
    db_events: list[tuple[str, dict]] = []
    judge_calls = {"count": 0}

    async def narrate(kind: str, data: dict) -> None:
        pass

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return {
            "action": "type",
            "x": 220,
            "y": 160,
            "text": long_answer,
            "grounding_source": "profile",
            "grounding_quote": "Jordan",
            "question": "Why are you interested in this role?",
            "reason": "Compose the response.",
        }

    def judge(user_id: int, *, answer: str, entries: list[dict]) -> dict:
        judge_calls["count"] += 1
        return {"supported": False, "unsupported_claims": ["serving 10K users", "increased conversion by 80 percent"]}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_call_claim_support_judge", judge)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))

    assert summary["state"] == "WAITING_FOR_USER"
    assert summary["reason"] == "needs_answer"
    ask = summary["ask"]
    assert ask["label"] == "Why are you interested in this role?"
    assert ask["required"] is True
    assert ask["is_unsure"] is True
    assert ask["selector"] == "#textarea-answer"
    assert ask["element_ref"]["selector"] == "#textarea-answer"
    assert ask["element_ref"]["control_signature"]
    assert body.typed_values == []
    assert judge_calls["count"] == 1
    verdicts = [payload for event, payload in db_events if event == "VISION_CLAIM_JUDGE_VERDICT"]
    assert [payload["cached"] for payload in verdicts] == [False, True, True, True]
    rejections = [payload for event, payload in db_events if event == "VISION_GROUNDING_CITATION_REJECTED"]
    assert [payload["failure_count"] for payload in rejections] == [1, 2, 3, 4]
    assert any(
        event == "VISION_GROUNDING_RECOVERY_EXHAUSTED"
        and payload.get("user_question_persisted") is True
        and payload.get("browser_mutation_attempted") is False
        for event, payload in db_events
    )
    feedback = " ".join(item for context in contexts for item in context.get("recent_actions") or [])
    assert '"serving 10K users"' in feedback
    assert "rewrite using only facts from the user's data; do not invent metrics, scales, or outcomes" in feedback


def test_long_answer_failure_signature_survives_rewrites_and_reason_changes() -> None:
    first = {"action": "type", "text": "First rewritten long answer. " * 12, "question": "Explain the impact."}
    second = {"action": "type", "text": "A completely different replacement composition. " * 10, "question": "Explain the impact."}

    first_sig = extension_run._vision_grounding_citation_failure_signature(
        first,
        "textarea:impact",
        failure_reason="grounding_citation_quote_not_found_in_source",
    )
    second_sig = extension_run._vision_grounding_citation_failure_signature(
        second,
        "textarea:impact",
        failure_reason="grounding_citation_claim_unsupported",
    )

    assert first_sig == second_sig == ("type", "textarea:impact", "long_composed_answer_grounding")


