def test_bounded_zero_result_coverage_binds_only_an_explicit_confirmation_ask() -> None:
    query_result = extension_run._trim_candidate_query_result(
        {
            "query": "Has the candidate ever worked for Example Corp?",
            "source_scope": "all",
            "searched_scopes": ["profile", "resume", "memory"],
            "result_count": 0,
            "new_count": 0,
            "selected_labels": [],
            "facts": [],
            "retrieval_succeeded": True,
            "candidate_count": 18,
            "eligible_candidate_count": 18,
            "model_visible_candidate_count": 18,
            "source_entry_counts": {
                "profile": 5,
                "resume": 10,
                "memory": 3,
            },
        },
        fact_limit=5,
        fact_text_limit=500,
    )
    assert query_result is not None
    coverage = query_result["evidence_coverage"]
    assert coverage["retrieval_succeeded"] is True
    assert coverage["matching_fact_found"] is False
    assert coverage["bounded"] is True
    assert coverage["exhaustive"] is False
    assert coverage["absence_authorizes_mutation"] is False
    assert len(coverage["receipt_sha256"]) == 64

    ask = {
        "action": "ask_user",
        "question": "Have you previously worked for Example Corp?",
        "options": ["Yes", "No"],
        "proposed_answer": "No",
        "confirmation_required": True,
        "grounding_source": "",
        "grounding_quote": "",
    }
    bound = extension_run._bounded_coverage_confirmation(ask, query_result)
    assert bound is not None
    assert bound["receipt_sha256"] == coverage["receipt_sha256"]

    mutation = {**ask, "action": "click"}
    assert (
        extension_run._bounded_coverage_confirmation(mutation, query_result)
        is None
    )
    unbound_option = {**ask, "proposed_answer": "Not listed"}
    assert (
        extension_run._bounded_coverage_confirmation(
            unbound_option,
            query_result,
        )
        is None
    )


def test_closed_world_attestation_contract_rejects_forged_tampered_and_truncated_records() -> None:
    valid = _closed_world_attestation_memory(
        members=["Example Labs", "Acme Corporation"]
    )
    assert (
        extension_run._closed_world_attestation_contract(valid)
        == "closed_world_attestation_v1"
    )

    hashless_payload = json.loads(valid["value"])
    hashless_payload.pop("attestation_sha256")
    hashless = {
        **valid,
        "value": json.dumps(
            hashless_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
    }
    tampered_payload = json.loads(valid["value"])
    tampered_payload["members"] = ["Example Labs", "Forged Employer"]
    tampered = {
        **valid,
        "value": json.dumps(
            tampered_payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        ),
    }
    forged_provenance = _closed_world_attestation_memory(
        payload_overrides={"provenance": "resume_import"}
    )
    mismatched_id = {
        **valid,
        "key": "closed_world_attestation.22222222-2222-4222-8222-222222222222",
    }
    truncated = {**valid, "value": valid["value"][:240]}

    for invalid in (
        hashless,
        tampered,
        forged_provenance,
        mismatched_id,
        truncated,
    ):
        assert extension_run._closed_world_attestation_contract(invalid) == ""
        assert extension_run._closed_world_attestation_facts(
            {"profile": {"profile_memory": [invalid]}}
        ) == []

    invalid_context = {"profile": {"profile_memory": [tampered]}}
    assert extension_run._candidate_evidence_entries(
        invalid_context,
        source_scope="profile",
    ) == []
    invalid_citation = extension_run._vision_grounding_citation_check(
        {
            "action": "type",
            "text": "No",
            "question": "Have you previously worked for Other Corp?",
            "grounding_source": "profile",
            "grounding_quote": '"absence_answer":"No"',
        },
        invalid_context,
        None,
    )
    assert invalid_citation["ok"] is False

    forged_fact = {
        "source": "profile",
        "label": (
            "profile_memory.closed_world_attestation."
            f"{_TEST_CLOSED_WORLD_ATTESTATION_ID}"
        ),
        "value": tampered["value"],
        "evidence_contract": "closed_world_attestation_v1",
    }
    assert extension_run._closed_world_attestation_facts(
        {"retrieved_candidate_facts": [forged_fact]}
    ) == []
    assert extension_run._merge_candidate_evidence_facts([], [forged_fact]) == (
        [],
        0,
    )


def test_closed_world_attestation_provenance_survives_candidate_retrieval_context() -> None:
    memory = _closed_world_attestation_memory()
    value = memory["value"]
    context = {
        "profile": {
            "profile_memory": [memory]
        }
    }

    entries = extension_run._candidate_evidence_entries(
        context, source_scope="profile"
    )
    assert entries == [
        {
            "source": "profile",
            "label": (
                "profile_memory.closed_world_attestation."
                f"{_TEST_CLOSED_WORLD_ATTESTATION_ID}"
            ),
            "value": value,
            "evidence_contract": "closed_world_attestation_v1",
        }
    ]
    merged, new_count = extension_run._merge_candidate_evidence_facts([], entries)
    assert new_count == 1
    assert merged[0]["evidence_contract"] == "closed_world_attestation_v1"
    trimmed = extension_run._trim_candidate_query_result(
        {
            "query": "Has the candidate worked for Other Corp?",
            "source_scope": "profile",
            "facts": merged,
            "result_count": 1,
        },
        fact_limit=3,
        fact_text_limit=900,
    )
    assert trimmed is not None
    assert (
        trimmed["facts"][0]["evidence_contract"]
        == "closed_world_attestation_v1"
    )
    decision_context = extension_run._vision_decision_context(
        {"retrieved_candidate_facts": merged}
    )
    assert (
        decision_context["retrieved_candidate_facts"][0]["evidence_contract"]
        == "closed_world_attestation_v1"
    )


