def test_missing_ask_proposal_repair_replans_browser_action_without_user_confirmation(
    monkeypatch,
) -> None:
    init_db()
    email = "a@b.com"
    body = _LedgerBody(observed_value=email)
    contexts: list[dict] = []
    db_events: list[tuple[str, dict]] = []
    decisions = iter(
        [
            {
                "action": "query_candidate",
                "query": "Email address",
                "source_scope": "profile",
                "x": 0,
                "y": 0,
                "reason": "Retrieve the saved answer for the visible field.",
            },
            {
                "action": "ask_user",
                "control": 1,
                "question": "Email address",
                "proposed_answer": "",
                "reason": "Ask because no answer was proposed yet.",
            },
            {
                "action": "type",
                "control": 1,
                "x": 220,
                "y": 140,
                "text": email,
                "question": "Email address",
                "grounding_source": "profile",
                "grounding_quote": email,
                "reason": "Use the recovered grounded answer.",
            },
            {
                "action": "done",
                "x": 0,
                "y": 0,
                "artifact_role": "",
                "reason": "The visible field is complete.",
            },
        ]
    )

    with SessionLocal() as db:
        user = models.User(
            email=f"grounded-proposal-{uuid.uuid4().hex}@example.test",
            name="Grounded Proposal",
        )
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            application_id=None,
            goal="Fill the visible email field from authorized saved data.",
            target_url="https://example.test/apply",
            current_state="RUNNING",
            confidence_state={
                "browser_task": {
                    "candidate_data_access": "on_demand",
                    "candidate_data_scopes": ["profile"],
                }
            },
        )
        db.add(run)
        db.commit()
        run_id = int(run.id)
        user_id = int(user.id)

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(dict(context))
        return next(decisions)

    monkeypatch.setattr(
        extension_run,
        "_candidate_retrieval_context_for_user",
        lambda *args, **kwargs: {"profile": {"email": email}},
    )
    monkeypatch.setattr(
        extension_run,
        "_retrieve_candidate_evidence",
        lambda *args, **kwargs: {
            "facts": [
                {
                    "source": "profile",
                    "label": "profile.contact.email",
                    "value": email,
                }
            ],
            "reason": "Selected the saved email.",
            "metadata": {"provider": "fixture", "model": "fixture-retriever"},
            "fallback": False,
            "candidate_count": 1,
        },
    )
    monkeypatch.setattr(
        extension_run,
        "_call_application_proposal_repair",
        lambda *args, **kwargs: {
            "decision": "propose",
            "answer": email,
            "supporting_entry_indexes": [0],
            "supporting_entries": [
                {
                    "source": "profile",
                    "label": "profile.contact.email",
                    "value": email,
                }
            ],
            "rationale": "Use the exact saved email.",
            "metadata": {"provider": "fixture", "model": "fixture-repair"},
        },
    )
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda run_id, event_type, payload: db_events.append(
            (event_type, payload)
        ),
    )
    monkeypatch.setattr(
        extension_run,
        "_record_context_usage_for_run",
        lambda *args, **kwargs: None,
    )
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=lambda *args, **kwargs: asyncio.sleep(0),
            run_id=run_id,
            user_id=user_id,
            skip_navigate=True,
            max_steps=4,
        )
    )

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.typed_values == [email]
    assert any(
        "grounded_proposal_ready" in item
        for item in contexts[2]["recent_actions"]
    )
    replan_event = next(
        payload
        for event, payload in db_events
        if event == "VISION_GROUNDED_PROPOSAL_REPLAN"
    )
    assert replan_event["browser_mutation_attempted"] is False
    assert replan_event["operator_question_persisted"] is False
    assert replan_event["answer_chars"] == len(email)
    assert email not in str(replan_event)


def test_grounded_proposal_recovery_budget_is_isolated_from_model_queries(
    monkeypatch,
) -> None:
    init_db()
    email = "proposal-budget@example.test"
    question = "Email address"
    unrelated_query = "Retrieve an unrelated saved preference."
    body = _LedgerBody(observed_value="")
    contexts: list[dict] = []
    retrievals: list[dict] = []
    repair_calls: list[list[dict]] = []
    db_events: list[tuple[str, dict]] = []
    decisions = iter(
        [
            {
                "action": "query_candidate",
                "query": unrelated_query,
                "source_scope": "profile",
                "x": 0,
                "y": 0,
                "reason": "Inspect one authorized saved fact.",
            },
            *[
                {
                    "action": "ask_user",
                    "control": 1,
                    "question": question,
                    "options": [],
                    "proposed_answer": "",
                    "reason": "The browser model omitted a proposed answer.",
                }
                for _ in range(2)
            ],
            {
                "action": "done",
                "x": 0,
                "y": 0,
                "artifact_role": "",
                "reason": "Stop after receiving the grounded handoff.",
            },
        ]
    )

    with SessionLocal() as db:
        user = models.User(
            email=f"proposal-budget-{uuid.uuid4().hex}@example.test",
            name="Proposal Budget",
        )
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            application_id=None,
            goal="Use authorized saved data for the visible field.",
            target_url="https://example.test/apply",
            current_state="RUNNING",
            confidence_state={
                "browser_task": {
                    "candidate_data_access": "on_demand",
                    "candidate_data_scopes": ["profile"],
                }
            },
        )
        db.add(run)
        db.commit()
        run_id = int(run.id)
        user_id = int(user.id)

    def decide(
        selected_user_id: int,
        image: dict,
        view: dict,
        context: dict,
    ) -> dict:
        assert selected_user_id == user_id
        contexts.append(dict(context))
        return next(decisions)

    def retrieve(
        selected_user_id: int,
        *,
        query: str,
        source_scope: str,
        context: dict,
        task_context: dict | None = None,
    ) -> dict:
        assert selected_user_id == user_id
        retrievals.append({"query": query, "source_scope": source_scope})
        facts = (
            [
                {
                    "source": "profile",
                    "label": "profile.contact.email",
                    "value": email,
                }
            ]
            if query == question
            else []
        )
        return {
            "facts": facts,
            "reason": "Selected only evidence relevant to the exact query.",
            "metadata": {"provider": "fixture", "model": "fixture-retriever"},
            "fallback": False,
            "candidate_count": len(facts),
        }

    def repair(*args, **kwargs) -> dict:
        entries = list(kwargs["entries"])
        repair_calls.append(entries)
        assert any(
            entry.get("source") == "profile" and entry.get("value") == email
            for entry in entries
        )
        return {
            "decision": "propose",
            "answer": email,
            "supporting_entry_indexes": [0],
            "supporting_entries": [
                {
                    "source": "profile",
                    "label": "profile.contact.email",
                    "value": email,
                }
            ],
            "rationale": "Use the exact saved email.",
            "metadata": {"provider": "fixture", "model": "fixture-repair"},
        }

    # The first model-owned lookup fully consumes its ledger. Proposal recovery must
    # still retain its own one-query-per-question evidence capability.
    monkeypatch.setattr(extension_run, "_CANDIDATE_QUERY_MAX_DISTINCT", 1)
    monkeypatch.setattr(
        extension_run,
        "_candidate_retrieval_context_for_user",
        lambda *args, **kwargs: {"profile": {"email": email}},
    )
    monkeypatch.setattr(extension_run, "_retrieve_candidate_evidence", retrieve)
    monkeypatch.setattr(
        extension_run,
        "_call_application_proposal_repair",
        repair,
    )
    monkeypatch.setattr(
        extension_run,
        "_db_event",
        lambda run_id, event_type, payload: db_events.append(
            (event_type, payload)
        ),
    )
    monkeypatch.setattr(
        extension_run,
        "_record_context_usage_for_run",
        lambda *args, **kwargs: None,
    )
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=lambda *args, **kwargs: asyncio.sleep(0),
            run_id=run_id,
            user_id=user_id,
            skip_navigate=True,
            max_steps=4,
        )
    )

    # A generic task has no completion audit, so the model's `done` after the replan ends it.
    assert summary["state"] == "READY_FOR_REVIEW", summary
    assert retrievals == [
        {"query": unrelated_query, "source_scope": "profile"},
        {"query": question, "source_scope": "profile"},
    ]
    assert len(repair_calls) == 1
    assert contexts[2]["retrieved_candidate_facts"] == [
        {
            "source": "profile",
            "label": "profile.contact.email",
            "value": email,
        }
    ]
    assert any(
        "grounded_proposal_ready" in item
        for item in contexts[3]["recent_actions"]
    )
    retrieved = next(
        payload
        for event, payload in db_events
        if event == "VISION_CANDIDATE_EVIDENCE_RETRIEVED"
        and payload.get("trigger") == "ask_user_before_persistence"
    )
    assert retrieved["budget_owner"] == "proposal_repair"
    replan = next(
        payload
        for event, payload in db_events
        if event == "VISION_GROUNDED_PROPOSAL_REPLAN"
    )
    assert replan["browser_mutation_attempted"] is False
    assert replan["operator_question_persisted"] is False
    assert body.clicks == []
    assert body.typed_values == []
    with SessionLocal() as db:
        questions = list(
            db.scalars(
                select(models.OperatorQuestion).where(
                    models.OperatorQuestion.run_id == run_id
                )
            ).all()
        )
    assert questions == []


