def test_vision_loop_bounds_scroll_only_search_without_durable_progress(monkeypatch) -> None:
    init_db()
    body = _VisionBody()
    events: list[tuple[str, dict]] = []
    # A brain that scrolls forever: each cycle stop recovers in-loop until the budget is spent.
    decisions = (
        {"action": "scroll", "x": 400, "y": 300, "direction": "down", "amount": 500, "reason": f"Scroll down {i}."}
        for i in itertools.count()
    )

    async def narrate(kind: str, data: dict) -> None:
        events.append((kind, data))

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=60))

    assert summary["state"] == "BLOCKED"
    assert summary["reason"] == "no_progress"
    assert summary["block_kind"] == "awaiting_engineering"
    assert summary["system_block"] is True
    assert summary["model_failure_reason"] == "page_state_cycle_exhausted"
    assert 1 < body.scrolls < 60
    assert any(kind == "stop" and data.get("reason") == "no_progress" for kind, data in events)


