def test_vision_loop_tells_a_tab_switch_from_a_reload_and_restores_read_backs(monkeypatch) -> None:
    # os_dialogs from the brain seat: adopting a second tab and switching back each logged "the page
    # was reloaded or replaced" and wiped the ledger, though neither document was reloaded.
    init_db()
    decisions: list[dict] = []
    tokens = ["archive-tab", "relay-tab", "archive-tab"]

    class _TwoTabBody(_VisionBody):
        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            token = tokens[min(len(decisions), len(tokens) - 1)]
            shot["document_lifecycle_token"] = token
            shot["page_evidence"] = {**(shot.get("page_evidence") or {}), "document_lifecycle_token": token}
            return shot

    async def narrate(kind: str, data: dict) -> None:
        pass

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        decisions.append(dict(context))
        if len(decisions) >= len(tokens):
            return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Stopping for the test."}
        return {"action": "wait", "wait_ms": 50, "reason": "Let the other tab settle."}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(run_vision_loop(_TwoTabBody(), url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=6))

    assert len(decisions) >= 3
    switched = " ".join(str(item) for item in decisions[1].get("recent_actions") or [])
    returned = " ".join(str(item) for item in decisions[2].get("recent_actions") or [])
    assert "different document" in switched and "reloaded or replaced" not in switched
    assert "already worked on" in returned


def test_null_application_run_stays_generic_minimal_even_with_malformed_task_state(monkeypatch) -> None:
    from app import vision_agent

    init_db()
    body = _MovieVisionBody()
    contexts: list[dict] = []
    prompts: list[dict] = []
    db_events: list[tuple[str, dict]] = []

    with SessionLocal() as db:
        user = models.User(email=f"generic-context-{uuid.uuid4().hex}@example.com", name="Generic Context")
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            application_id=None,
            goal="Choose a movie showtime and seats, then stop before payment or confirmation.",
            target_url="https://cinema.example/showtimes",
            current_state="RUNNING",
            confidence_state={"browser_task": "malformed"},
        )
        db.add(run)
        db.commit()
        run_id = int(run.id)
        user_id = int(user.id)

    class _ForbiddenContextEngine:
        def __init__(self, db: object) -> None:
            raise AssertionError("generic task must not preload candidate profile")

    def forbidden_private_loader(*args, **kwargs):
        raise AssertionError("generic task must not preload private candidate or upload context")

    async def narrate(kind: str, data: dict) -> None:
        pass

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(dict(context))
        prompts.append(vision_agent.build_prompt(view, context))
        return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "The requested non-consequential work is complete."}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _ForbiddenContextEngine)
    monkeypatch.setattr(extension_run, "_resume_facts_for_user_safe", forbidden_private_loader)
    monkeypatch.setattr(extension_run, "_saved_answers_for_user", forbidden_private_loader)
    monkeypatch.setattr(extension_run, "_upload_documents_for_user", forbidden_private_loader)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    summary = asyncio.run(
        run_vision_loop(
            body,
            url=None,
            narrate=narrate,
            run_id=run_id,
            user_id=user_id,
            skip_navigate=True,
            max_steps=3,
        )
    )

    assert summary["state"] == "READY_FOR_REVIEW"
    assert contexts
    for context in contexts:
        assert "profile" not in context
        assert "profile_provenance" not in context
        assert "resume_facts" not in context
        assert "saved_answers" not in context
        assert "available_documents" not in context
        assert context["application_context"] is False
        assert context["generic_browser_task"] is True
        assert context["candidate_data_scopes"] == []
    for prompt in prompts:
        assert "user_profile" not in prompt
        assert "user_profile_provenance" not in prompt
        assert "resume_facts" not in prompt
        assert "saved_answers" not in prompt
        assert "available_documents" not in prompt
        assert "Do not use query_candidate" in prompt["instruction"]
    policy = [payload for event_type, payload in db_events if event_type == "VISION_CONTEXT_POLICY_APPLIED"]
    assert policy == [
        {
            "policy": "generic_task_minimal",
            "generic_browser_task": True,
            "preload_profile": False,
            "preload_resume_facts": False,
            "preload_saved_answers": False,
            "preload_upload_documents": False,
            "candidate_retrieval": "withheld_for_run",
            "candidate_data_access": "none",
            "candidate_data_scopes": [],
            "runtime_build": extension_run._VISION_RUNTIME_BUILD,
        }
    ]
    assert not any(event_type == "VISION_DOCUMENT_CONTEXT_SELECTED" for event_type, _payload in db_events)


