    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))

    step_timings = [payload for event, payload in db_events if event == "STEP_TIMING"]
    run_summary = [payload for event, payload in db_events if event == "RUN_TIMING_SUMMARY"]

    assert summary["state"] == "READY_FOR_REVIEW"
    assert body.screenshots == 2
    assert [payload["reused_observation"] for payload in step_timings[:4]] == [False, True, True, False]
    assert step_timings[0]["outcome"] == "done_rejected"
    assert step_timings[-1]["outcome"] == "done"
    assert run_summary
    assert run_summary[-1]["steps"] == len(step_timings)
    assert run_summary[-1]["executed_actions"] == 0
    assert "Timing:" in summary["summary_timing"]


