class _DriveBody:
    device_id = "test-device"


def test_drive_pause_interrupt_preserves_waiting_state_and_message(monkeypatch) -> None:
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"vision-drive-pause-{uuid.uuid4().hex}@example.com", name="Vision Pause")
        db.add(user)
        db.flush()
        run = models.OperatorRun(user_id=user.id, goal="test pause", target_url="https://example.test", current_state="RUNNING")
        db.add(run)
        db.flush()
        thread = models.ChatThread(user_id=user.id, run_id=run.id, title="test", mode="run")
        db.add(thread)
        db.commit()
        run_id = run.id
        thread_id = thread.id

    async def fake_run_vision_loop(body, *, url, narrate, run_id, user_id, skip_navigate=False, max_steps=60, should_cancel=None):
        with SessionLocal() as db:
            run = db.get(models.OperatorRun, run_id)
            run.current_state = "WAITING_FOR_USER"
            run.status_message = "Paused. Lumen will not continue this session until you resume it."
            run.confidence_state = {
                **(run.confidence_state or {}),
                "user_pause": {"active": True, "paused_from_state": "RUNNING"},
                "session_control": {"status": "paused", "reason": "Paused by user"},
            }
            run.updated_at = models.utcnow()
            db.commit()
        assert should_cancel is not None
        assert should_cancel() == "session_paused"
        return {"state": "WAITING_FOR_USER", "reason": "session_paused", "actions": 0, "receipts": []}

    messages: list[str] = []
    monkeypatch.setattr(extension_run, "run_vision_loop", fake_run_vision_loop)
    monkeypatch.setattr(extension_run, "_db_message", lambda thread_id, content, payload=None: messages.append(content))

    summary = asyncio.run(
        drive_in_browser_application(
            body=_DriveBody(),
            run_id=run_id,
            thread_id=thread_id,
            url="https://example.test",
            skip_navigate=True,
        )
    )

    assert summary["state"] == "WAITING_FOR_USER"
    assert summary["reason"] == "session_paused"
    assert messages == []
    with SessionLocal() as db:
        refreshed = db.get(models.OperatorRun, run_id)
        assert refreshed.current_state == "WAITING_FOR_USER"
        assert refreshed.status_message == "Paused. Lumen will not continue this session until you resume it."
        assert (refreshed.confidence_state or {})["session_control"]["status"] == "paused"


def test_drive_in_browser_application_routes_directly_to_vision(monkeypatch) -> None:
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"vision-{uuid.uuid4().hex}@example.com", name="Vision")
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            goal="test",
            target_url="https://example.test",
            current_state="RUNNING",
            confidence_state={
                "system_block": {"reason": "stale_transport_failure", "needs_user": False},
                "end_to_end": {
                    "system_block": True,
                    "system_block_reason": "stale_transport_failure",
                    "needs_user": False,
                    "block_kind": "awaiting_engineering",
                },
            },
        )
        db.add(run)
        db.flush()
        thread = models.ChatThread(user_id=user.id, run_id=run.id, title="test", mode="run")
        db.add(thread)
        db.commit()
        user_id = user.id
        run_id = run.id
        thread_id = thread.id

    called: dict[str, object] = {}

    async def fake_run_vision_loop(body, *, url, narrate, run_id, user_id, skip_navigate=False, max_steps=60, should_cancel=None):
        called.update({"body": body, "url": url, "run_id": run_id, "user_id": user_id, "skip_navigate": skip_navigate})
        return {"state": "READY_FOR_REVIEW", "reason": "ready_for_review", "actions": 0, "receipts": []}

    monkeypatch.setattr(extension_run, "run_vision_loop", fake_run_vision_loop)

    class _IndicatorDriveBody(_DriveBody):
        def __init__(self) -> None:
            self.indicator_states: list[tuple[bool, int | None, str]] = []

        async def set_control_indicator(
            self,
            active: bool,
            *,
            run_id: int | None = None,
            message: str = "",
        ) -> dict:
            self.indicator_states.append((active, run_id, message))
            return {"ok": True, "visible": active}

    body = _IndicatorDriveBody()
    summary = asyncio.run(drive_in_browser_application(body=body, run_id=run_id, thread_id=thread_id, url="https://example.test", skip_navigate=True))

    assert summary["state"] == "READY_FOR_REVIEW"
    assert called["run_id"] == run_id
    assert called["user_id"] == user_id
    assert called["skip_navigate"] is True
    assert body.indicator_states == [
        (True, run_id, "Lumen is using your computer"),
        (False, run_id, "Lumen is using your computer"),
    ]
    with SessionLocal() as db:
        recovered = dict(db.get(models.OperatorRun, run_id).confidence_state or {})
    assert recovered["system_block"] is None
    assert recovered["end_to_end"]["system_block"] is False
    assert recovered["end_to_end"]["system_block_reason"] is None


