def test_drive_persists_exact_question_before_waiting_state_is_pollable(
    monkeypatch,
    ask: dict,
    expected_question_type: str,
) -> None:
    init_db()
    with SessionLocal() as db:
        user = models.User(
            email=f"ask-publish-order-{uuid.uuid4().hex}@example.com",
            name="Ask Publish Order",
        )
        db.add(user)
        db.flush()
        run = models.OperatorRun(
            user_id=user.id,
            goal="Publish the exact question before waiting",
            target_url="https://example.test",
            current_state="RUNNING",
        )
        db.add(run)
        db.flush()
        thread = models.ChatThread(
            user_id=user.id,
            run_id=run.id,
            title="ask",
            mode="run",
        )
        db.add(thread)
        db.commit()
        run_id = int(run.id)
        thread_id = int(thread.id)

    async def fake_run_vision_loop(*args, **kwargs):
        return {
            "state": "WAITING_FOR_USER",
            "reason": "needs_answer",
            "ask": dict(ask),
            "actions": 0,
            "receipts": [],
        }

    original_cas = extension_run._db_set_state_if_live
    poll_observation: dict[str, object] = {}

    def poll_before_waiting_publication(
        run_id: int,
        state: str,
        status_message: str,
        state_patch=None,
    ):
        from app.cognition import OperatorChatService

        with SessionLocal() as db:
            run = db.get(models.OperatorRun, run_id)
            poll_observation["run_state"] = run.current_state
            question = OperatorChatService(db).ensure_question_for_run(
                run_id,
                thread_id=thread_id,
                announce=False,
            )
            assert question is not None
            poll_observation["question_type"] = question.question_type
            poll_observation["prompt"] = question.prompt
            poll_observation["schema"] = dict(
                question.expected_answer_schema or {}
            )
            db.commit()
        return original_cas(run_id, state, status_message, state_patch)

    monkeypatch.setattr(extension_run, "run_vision_loop", fake_run_vision_loop)
    monkeypatch.setattr(
        extension_run,
        "_db_set_state_if_live",
        poll_before_waiting_publication,
    )

    summary = asyncio.run(
        drive_in_browser_application(
            body=_DriveBody(),
            run_id=run_id,
            thread_id=thread_id,
            url="https://example.test",
            skip_navigate=True,
        )
    )

    assert summary["state"] == "WAITING_FOR_USER"
    assert poll_observation["run_state"] == "RUNNING"
    assert poll_observation["question_type"] == expected_question_type
    assert poll_observation["question_type"] != "blocked_reason"
    if expected_question_type == "field_approval":
        fields = (poll_observation["schema"] or {}).get("fields") or []
        assert fields and fields[0]["label"] == ask["label"]
    else:
        assert poll_observation["prompt"] == ask["label"]


