        assert db.get(models.OperatorRun, run_id).current_state == "CANCELLED"
        questions = list(
            db.scalars(
                select(models.OperatorQuestion).where(
                    models.OperatorQuestion.run_id == run_id
                )
            ).all()
        )
        tasks = list(
            db.scalars(
                select(models.RuntimeTask).where(models.RuntimeTask.run_id == run_id)
            ).all()
        )
        assert questions and all(question.status != "pending" for question in questions)
        assert tasks and all(task.status not in {"pending", "approved"} for task in tasks)
        assert not list(
            db.scalars(
                select(models.ChatMessage).where(
                    models.ChatMessage.thread_id == thread_id,
                    models.ChatMessage.role == "assistant",
                )
            ).all()
        )


