def test_drive_result_cannot_overwrite_cancellation_before_state_cas(monkeypatch) -> None:
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"vision-final-cas-cancel-{uuid.uuid4().hex}@example.com", name="Vision CAS Cancel")
        db.add(user)
        db.flush()
        run = models.OperatorRun(user_id=user.id, goal="submit", target_url="https://example.test", current_state="RUNNING")
        db.add(run)
        db.flush()
        thread = models.ChatThread(user_id=user.id, run_id=run.id, title="test", mode="run")
        db.add(thread)
        db.commit()
        run_id = run.id
        thread_id = thread.id

    async def fake_run_vision_loop(body, *, url, narrate, run_id, user_id, skip_navigate=False, max_steps=60, should_cancel=None):
        return {"state": "COMPLETED", "reason": "final_action_submitted", "actions": 1, "receipts": []}

    original_cas = extension_run._db_set_state_if_live

    def cancel_then_cas(run_id: int, state: str, status_message: str, state_patch=None):
        with SessionLocal() as db:
            current = db.get(models.OperatorRun, run_id)
            current.current_state = "CANCELLED"
            current.status_message = "Stopped from chat."
            current.updated_at = models.utcnow()
            db.commit()
        return original_cas(run_id, state, status_message, state_patch)

    messages: list[str] = []
    monkeypatch.setattr(extension_run, "run_vision_loop", fake_run_vision_loop)
    monkeypatch.setattr(extension_run, "_db_set_state_if_live", cancel_then_cas)
    monkeypatch.setattr(extension_run, "_db_message", lambda thread_id, content, payload=None: messages.append(content))

    summary = asyncio.run(drive_in_browser_application(body=_DriveBody(), run_id=run_id, thread_id=thread_id, url=None, skip_navigate=True))

    assert summary["state"] == "CANCELLED"
    assert messages == []
    with SessionLocal() as db:
        refreshed = db.get(models.OperatorRun, run_id)
        assert refreshed.current_state == "CANCELLED"
        assert refreshed.status_message == "Stopped from chat."


