def _jpeg_b64(width: int, height: int) -> str:
    import io

    from PIL import Image, ImageDraw

    img = Image.new("RGB", (width, height), (240, 240, 240))
    draw = ImageDraw.Draw(img)
    draw.rectangle((width // 4, height // 4, width // 2, height // 2), fill=(30, 30, 200))
    out = io.BytesIO()
    img.save(out, "JPEG", quality=90)
    return base64.b64encode(out.getvalue()).decode()


def test_zoom_crop_attachment_cuts_native_pixels_from_model_coordinates() -> None:
    # The model speaks 1120px-downscaled coordinates; the crop must come from the
    # pre-downscale capture. A 2240px-wide shot means coord_scale=2.0.
    shot = {"image": _jpeg_b64(2240, 1200)}
    action = {"action": "zoom", "x": 100, "y": 100, "to_x": 300, "to_y": 200}
    result = extension_run._zoom_crop_attachment(shot, action, 2.0)
    assert result["ok"] is True and result["zoomed"] is True
    assert result["region_model"] == [100, 100, 300, 200]
    assert result["region_native"] == [200, 200, 600, 400]
    # 400px native width is below the legibility floor, so the crop is upscaled
    # (bounded), never returned as a tiny thumbnail.
    assert result["crop_width"] >= 400
    assert result["crop_width"] <= 400 * 3
    raw = base64.b64decode(result["data"], validate=True)
    assert raw[:2] == b"\xff\xd8"  # JPEG magic


def test_zoom_crop_attachment_keeps_colours_while_stretching_contrast() -> None:
    import io

    from PIL import Image, ImageDraw

    # v2_vision_trial's indicator arrow (#b13030) on its panel (#f7f9fc): a per-channel stretch
    # turned the arrow black and the panel cyan in the crop the brain read colours from.
    img = Image.new("RGB", (1120, 600), (247, 249, 252))
    ImageDraw.Draw(img).rectangle((300, 250, 600, 280), fill=(177, 48, 48))
    out = io.BytesIO()
    img.save(out, "PNG")
    shot = {"image": base64.b64encode(out.getvalue()).decode()}

    result = extension_run._zoom_crop_attachment(shot, {"action": "zoom", "x": 250, "y": 200, "to_x": 650, "to_y": 330}, 1.0)

    crop = Image.open(io.BytesIO(base64.b64decode(result["data"]))).convert("RGB")
    red, green, blue = crop.getpixel((crop.width // 2, crop.height // 2))
    assert red > 100 and red > green + 60 and red > blue + 60


def test_zoom_crop_attachment_fails_closed_on_degenerate_regions() -> None:
    shot = {"image": _jpeg_b64(800, 600)}
    too_small = extension_run._zoom_crop_attachment(shot, {"x": 10, "y": 10, "to_x": 12, "to_y": 12}, 1.0)
    assert too_small["ok"] is False
    assert too_small["failure_reason"] == "zoom_region_too_small"
    off_screen = extension_run._zoom_crop_attachment(shot, {"x": 790, "y": 590, "to_x": 1400, "to_y": 1200}, 1.0)
    # A region that starts on-screen is clamped to the capture, not rejected.
    assert off_screen["ok"] is True
    assert off_screen["region_native"][2] <= 800 and off_screen["region_native"][3] <= 600
    unreadable = extension_run._zoom_crop_attachment({"image": "not-base64!"}, {"x": 0, "y": 0, "to_x": 100, "to_y": 100}, 1.0)
    assert unreadable["ok"] is False
    assert unreadable["failure_reason"] == "zoom_screenshot_unreadable"


def test_zoom_counts_as_verified_but_not_durable_page_progress() -> None:
    ok = {"ok": True, "zoomed": True, "region_model": [0, 0, 100, 100]}
