def test_sibling_controls_sharing_section_text_keep_their_own_identity():
    from app.extension_run import _control_label, _control_signature

    shared = "Note for later: this applicant's contact preferences are Email and SMS"
    first = {
        "tag": "input",
        "context_text": shared,
        "accessibility_context": [{"relation": "label", "text": "First name *"}],
    }
    confirm = {
        "tag": "input",
        "context_text": shared,
        "accessibility_context": [{"relation": "label", "text": "Confirm email *"}],
    }
    back = {"tag": "button", "text": "Back", "context_text": "Referral code (optional)"}
    proceed = {"tag": "button", "text": "Continue to step 3", "context_text": "Referral code (optional)"}
    unnamed = {"tag": "input", "type": "radio", "context_text": "Work mode"}

    assert _control_label(first) == "First name *"
    assert _control_label(confirm) == "Confirm email *"
    assert _control_signature(first) != _control_signature(confirm)
    assert _control_label(back) == "Back"
    assert _control_signature(back) != _control_signature(proceed)
    # With no name of its own, a control is still identified by its surrounding text.
    assert _control_label(unnamed) == "Work mode"


