def test_secret_judge_learns_which_hosts_showed_the_typed_text():
    from app.extension_run import _page_text_sources_seen_this_run, _secret_classifier_action_evidence

    memory = [
        {"url": "http://127.0.0.1:8001/relay", "text": "Relay console Your relay code is: RC-YVJN Return to the desk"},
        {"url": "https://bank.example/otp", "text": "Your one-time code is 882211"},
    ]
    current = "http://127.0.0.1:8001/desk"
    sources = _page_text_sources_seen_this_run({"viewport_text": "Relay code Verify relay code"}, memory, current)

    relay = _secret_classifier_action_evidence(
        {"action": "type", "text": "RC-YVJN"}, page_texts=[text for _, text in sources], page_text_sources=sources, current_url=current
    )
    assert relay["typed_text_verbatim_from_page"] is True
    assert relay["typed_text_page_hosts"] == ["127.0.0.1"]
    assert relay["current_page_host"] == "127.0.0.1"

    carried = _secret_classifier_action_evidence(
        {"action": "type", "text": "882211"}, page_texts=[text for _, text in sources], page_text_sources=sources, current_url=current
    )
    assert carried["typed_text_page_hosts"] == ["bank.example"]
    assert carried["current_page_host"] == "127.0.0.1"
    assert "882211" not in str(carried)


