def test_zoom_crop_brings_faint_print_up_to_readable_contrast():
    import base64
    import io

    from PIL import Image

    from app.extension_run import _zoom_crop_attachment

    image = Image.new("RGB", (400, 200), (255, 255, 255))
    for x in range(150, 250):
        for y in range(90, 100):
            image.putpixel((x, y), (201, 201, 201))  # #c9c9c9 "print" on white
    buffer = io.BytesIO()
    image.save(buffer, "PNG")
    shot = {"image": base64.b64encode(buffer.getvalue()).decode()}

    zoom = _zoom_crop_attachment(shot, {"x": 100, "y": 60, "to_x": 300, "to_y": 140}, 1.0)

    assert zoom["ok"] is True
    crop = Image.open(io.BytesIO(base64.b64decode(zoom["data"]))).convert("L")
    assert min(crop.getdata()) < 80, "faint grey print is stretched toward black"


