def test_rendered_surface_binding_gets_the_screenshot_with_the_point_marked() -> None:
    import io

    from PIL import Image

    blank = Image.new("RGB", (120, 80), (255, 255, 255))
    buf = io.BytesIO()
    blank.save(buf, format="PNG")
    image = {"media_type": "image/png", "data": base64.b64encode(buf.getvalue()).decode("ascii")}

    marked = extension_run._mark_point_on_image(image, (60, 40))
    assert marked and marked["media_type"] == "image/png"
    out = Image.open(io.BytesIO(base64.b64decode(marked["data"]))).convert("RGB")
    assert out.size == (120, 80)
    assert out.getpixel((60 + 11, 40)) != (255, 255, 255)  # the ring
    assert out.getpixel((5, 5)) == (255, 255, 255)  # the rest of the page is untouched
    assert extension_run._mark_point_on_image(image, None) is None
    assert extension_run._mark_point_on_image({"data": "not-base64!"}, (1, 1)) is None


def test_surface_type_point_only_for_rendered_surfaces_and_capable_bodies() -> None:
    async def with_point(selector, text, *, expected_target_identity=None, expected_page_context=None, point=None):
        return {}

    async def without_point(selector, text, *, expected_target_identity=None, expected_page_context=None):
        return {}

    canvas = {"tag": "canvas", "selector": "#pf", "x": 60, "y": 40, "width": 840, "height": 420}
    field = {"tag": "input", "selector": "#name", "x": 60, "y": 40, "width": 300, "height": 40}
    action = {"action": "type", "x": 100, "y": 50}
    assert extension_run._rendered_surface_control(canvas)
    assert not extension_run._rendered_surface_control(field)
    # An offset from the control's observed corner, in capture pixels.
    assert extension_run._surface_point_kwargs(with_point, canvas, action, 2.0) == {"point": (140, 60)}
    # A point off the observed control is not sent.
    assert extension_run._surface_point_kwargs(with_point, canvas, {"x": 10, "y": 10}, 2.0) == {}
    assert extension_run._surface_point_kwargs(with_point, field, action, 2.0) == {}
    assert extension_run._surface_point_kwargs(without_point, canvas, action, 2.0) == {}
    assert extension_run._surface_point_kwargs(with_point, canvas, {"action": "type"}, 2.0) == {}


