def test_page_state_fingerprint_tells_browser_dialog_states_apart() -> None:
    page = {"url": "https://example.test/", "title": "Deck", "page_evidence": {"viewport_text": "Bay 4", "controls": []}}

    def with_dialog(**dialog):
        return {**page, "page_evidence": {**page["page_evidence"], "native_dialog": dialog}}

    plain = extension_run._page_state_fingerprint(page)
    confirm = extension_run._page_state_fingerprint(with_dialog(type="confirm", message="Begin maintenance?", typed_prompt=None))
    prompt = extension_run._page_state_fingerprint(with_dialog(type="prompt", message="Service code?", typed_prompt=None))
    typed = extension_run._page_state_fingerprint(with_dialog(type="prompt", message="Service code?", typed_prompt="SV-1"))
    assert len({plain, confirm, prompt, typed}) == 4
    # The page alone is unchanged by the dialog: without one, the fingerprint is what it was.
    assert extension_run._page_state_fingerprint(dict(page)) == plain


def test_generic_task_citation_mislabelled_as_goal_is_read_back_from_the_page() -> None:
    sheet = "Configuration sheet: Conductor: Ruthenium Gas mixture: exactly Argon and Xenon"
    generic = {"goal": "Complete the configuration page.", "page_evidence": {"viewport_text": sheet, "controls": []}}
    typed = {"action": "type", "text": "Ruthenium", "grounding_source": "goal", "grounding_quote": "Conductor: Ruthenium"}

    relabelled = extension_run._vision_grounding_citation_check(typed, generic, {"tag": "input", "text": "Conductor"})
    assert relabelled["ok"] is True
    assert relabelled["source"] == "page"
    assert relabelled["source_corrected"] is True

    # A quote the page never showed is still rejected.
    invented = extension_run._vision_grounding_citation_check(
        {**typed, "grounding_quote": "Conductor: Osmium", "text": "Osmium"}, generic, {"tag": "input", "text": "Conductor"}
    )
    assert invented["ok"] is False

    # Application runs keep the page out of user facts: no relabel to the page there.
    application = {**generic, "application_context": True, "job": {"title": "Engineer"}}
    if not extension_run._context_is_generic_browser_task(application):
        kept = extension_run._vision_grounding_citation_check(typed, application, {"tag": "input", "text": "Conductor"})
        assert kept.get("source") != "page"


class _StatefulTwoFieldBody(_QuestionBindingBody):
    """Each typed value changes the document state; a type bound to a stale state is refused."""

    def __init__(self) -> None:
        super().__init__()
        self.values: dict[str, str] = {}
        self.refused: list[str] = []

    def _state(self) -> str:
        return "state:" + ",".join(f"{key}={value}" for key, value in sorted(self.values.items()))

    async def capture_screenshot(self) -> dict:
        controls = [
            {"index": 1, "tag": "input", "type": "text", "text": "First name", "value": self.values.get("#first", ""),
             "selector": "#first", "x": 100, "y": 100, "width": 300, "height": 30},
            {"index": 2, "tag": "input", "type": "text", "text": "Last name", "value": self.values.get("#last", ""),
             "selector": "#last", "x": 100, "y": 160, "width": 300, "height": 30},
        ]
        return {
            "ok": True, "image": "jpeg", "width": 800, "height": 600, "url": "https://example.test/form",
            "title": "Form", "surface_signature": "s", "document_state_signature": self._state(),
            "scroll_y": 0, "scroll_height": 600,
            "page_evidence": {"viewport_text": "Applicant file: Ada Lovelace. First name Last name", "controls": controls},
        }

    async def vision_type_control(self, selector: str, text: str, **binding: object) -> dict:
        expected = binding.get("expected_page_context") or {}
        if expected.get("document_state_signature") != self._state():
            self.refused.append(selector)
            return {"ok": False, "action": "type", "failure_reason": "page_context_drift",
                    "page_context_mismatch_field": "document_state_signature"}
        self.values[selector] = text
        self.type_control_calls.append((selector, text))
        return {"ok": True, "action": "type", "mode": "control_selector", "active_typable": True,
                "active_has_value": True, "active_tag": "input", "active_value": text, "active_selector": selector,
                "after_document_state_signature": self._state()}


