def _switching_body(browser, desktop):
    from app.surface_body import SurfaceSwitchingBody

    return SurfaceSwitchingBody(browser, primary_surface="browser", factories={"desktop": lambda: desktop})


def test_vision_loop_switches_to_the_real_screen_and_back(monkeypatch) -> None:
    init_db()
    desktop = _DesktopScreenBody()
    body = _switching_body(_VisionBody(), desktop)
    decisions = iter(
        [
            {"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "The page waits on a browser prompt."},
            {"action": "click", "control": 1, "x": 940, "y": 135, "reason": "Allow the browser prompt."},
            {"action": "switch_surface", "target": "browser", "x": 0, "y": 0, "reason": "Back to the page."},
        ]
    )
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    surfaces_seen: list[tuple[str, list]] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        surfaces_seen.append((context.get("execution_surface"), list(context.get("surfaces") or [])))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(
        extension_run,
        "_judge_click_consequence",
        lambda *args, **kwargs: {"classification": "ordinary_reversible", "confidence": 0.99, "evidence": "Fixture."},
    )
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=6))

    assert [surface for surface, _ in surfaces_seen[:4]] == ["browser", "desktop", "desktop", "browser"]
    assert surfaces_seen[0][1] == ["browser", "desktop"]
    assert desktop.clicks and desktop.clicks[0][0] in {"control", "point"}
    assert body.execution_surface == "browser"


class _TaskListPageBody(_VisionBody):
    """A task page whose viewport shows only the first tasks; its tab's whole text names all four."""

    VIEWPORT = "Paperwork 0 / 4 1. Rename the invoice 2. Move the receipt 3. Label the passport scan"

    def __init__(self, reads: list) -> None:
        super().__init__()
        self.reads = list(reads)
        self.read_calls = 0

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["url"] = "https://example.test/paperwork"
        shot["title"] = "Paperwork"
        shot["page_evidence"] = {**shot["page_evidence"], "viewport_text": self.VIEWPORT}
        return shot

    async def read_run_tab_text(self, *, max_chars: int) -> dict:
        assert max_chars == extension_run._RUN_TAB_TEXT_CHARS
        self.read_calls += 1
        result = self.reads[min(self.read_calls - 1, len(self.reads) - 1)]
        if isinstance(result, Exception):
            raise result
        return dict(result)


