class _BackgroundedBrowserBody(_VisionBody):
    """Chrome's window is behind another app for the first `hidden` captures (the user is working elsewhere)."""

    def __init__(self, hidden: int) -> None:
        super().__init__()
        self.hidden = hidden

    async def capture_screenshot(self) -> dict:
        if self.captures < self.hidden:
            self.captures += 1
            return {"ok": False, "action": "screenshot", "failure_reason": "screenshot_target_surface_unavailable",
                    "target_surface_failure_reason": "target_surface_not_foreground", "retryable": True,
                    "image_discarded": True, "tab_active": True, "window_focused": False}
        return await super().capture_screenshot()


def _run_backgrounded(
    monkeypatch, body: _VisionBody, *, wait_seconds: float, max_steps: int = 3, raises: bool = False, locked: bool = False
) -> tuple[dict, list[dict], list[str]]:
    init_db()
    contexts: list[dict] = []
    events: list[str] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Seen."}

    async def narrate(kind: str, data: dict) -> None:
        if data.get("action") == "wait":
            events.append("WAIT:" + str(data.get("summary")))

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_screen_locked", lambda: locked)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, *args, **kwargs: events.append(event_type))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    monkeypatch.setattr(extension_run, "_BROWSER_FOREGROUND_POLL_SECONDS", 0.0)
    monkeypatch.setattr(extension_run, "_BROWSER_FOREGROUND_WAIT_SECONDS", wait_seconds)
    raise_calls: list[int] = []

    def fake_raise() -> bool:
        raise_calls.append(1)
        if raises:
            body.hidden = 0  # the OS put Chrome in front
        return raises

    monkeypatch.setattr(extension_run, "_bring_browser_to_front", fake_raise)
    result = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=max_steps))
    return result, contexts, events


def test_a_browser_window_behind_another_app_is_waited_for_without_spending_steps(monkeypatch) -> None:
    """Run 52: the user answered a question in another app, Chrome lost the front, and the run blocked as
    screenshot_failed within five seconds. Twelve polls with a three-step budget prove the wait is not steps."""
    body = _BackgroundedBrowserBody(hidden=12)
    result, contexts, events = _run_backgrounded(monkeypatch, body, wait_seconds=600.0)
    assert result.get("reason") != "screenshot_failed"
    assert body.captures == 13 and contexts, "the page is observed and decided on once the window is back"
    assert events.count("VISION_SCREENSHOT_CAPTURE_REJECTED") == 1, "one rejection per wait, not one per poll"
    assert events.count("VISION_BROWSER_BROUGHT_TO_FRONT") == 1, "Chrome is raised once per wait, not every poll"


def test_a_locked_screen_says_so_never_raises_chrome_and_ends_as_a_resumable_screen_block(monkeypatch) -> None:
    """Run 54: the Mac locked mid-run; "Chrome isn't in front" was the wrong thing to tell the user."""
    body = _BackgroundedBrowserBody(hidden=100)
    result, contexts, events = _run_backgrounded(monkeypatch, body, wait_seconds=0.0, max_steps=10, locked=True)
    assert result.get("block_kind") == "screen_unavailable" and result.get("reason") == "browser_view_unavailable"
    assert "VISION_BROWSER_BROUGHT_TO_FRONT" not in events and not contexts
    waiting = [item for item in events if item.startswith("WAIT:")]
    assert all("locked" in item for item in waiting)


def test_a_browser_behind_the_lumen_window_is_brought_to_the_front_once(monkeypatch) -> None:
    """macOS refuses Chrome's own focus request while the Lumen window the task came from is in front."""
    body = _BackgroundedBrowserBody(hidden=50)
    result, contexts, events = _run_backgrounded(monkeypatch, body, wait_seconds=600.0, raises=True)
    assert contexts and body.captures == 2, "the capture right after raising Chrome sees the page"
    assert events.count("VISION_BROWSER_BROUGHT_TO_FRONT") == 1


def test_a_browser_window_that_never_comes_back_still_ends_blocked(monkeypatch) -> None:
    body = _BackgroundedBrowserBody(hidden=100)
    result, contexts, _events = _run_backgrounded(monkeypatch, body, wait_seconds=0.0, max_steps=10)
    assert result.get("reason") == "screenshot_failed" and not contexts


