def test_screen_text_reads_a_slashed_zero_in_a_code_as_zero() -> None:
    # Windows OCR read Consolas's slashed zero in "DECF-604811-5" as the letter Ø (run 1662).
    from app import screen_ocr

    original = screen_ocr.read_lines
    try:
        screen_ocr.read_lines = lambda images, **_kw: [["Container ID", "DECF-6\u00d84811-5", "K\u00f8benhavn 2\u00d8\u00d8 docks"]]
        assert screen_ocr.find_text("DECF-604811-5", [b"x"]) == {"found": True, "image_index": 0, "line": "DECF-604811-5"}
        # The letter O is never a zero, and a word with no digit keeps its letter.
        assert screen_ocr.find_text("DECF-6O4811-5", [b"x"]) == {"found": False}
        assert screen_ocr.find_text("K0benhavn 200", [b"x"]) == {"found": False}
        assert screen_ocr.find_text("K\u00f8benhavn 200", [b"x"])["found"] is True
    finally:
        screen_ocr.read_lines = original


def test_screen_text_zero_misreads_differ_only_at_the_values_zeros() -> None:
    # Run 1663: OCR read Consolas's zero in ZKDX-161085-2 as "e". Tolerated only where the value has a
    # 0, flagged as a misread (not proof alone), and never the letter O or another case.
    from app import screen_ocr

    original = screen_ocr.read_lines
    try:
        screen_ocr.read_lines = lambda images, **_kw: [["Container ID", "ZKDX-161e85-2"]]
        assert screen_ocr.find_text("ZKDX-161085-2", [b"x"]) == {"found": False}
        hit = screen_ocr.find_text("ZKDX-161085-2", [b"x"], zero_misreads=True)
        assert hit == {"found": True, "image_index": 0, "line": "ZKDX-161e85-2", "zero_misread": True}
        assert screen_ocr.find_text("ZKDX-161O85-2", [b"x"], zero_misreads=True) == {"found": False}
        assert screen_ocr.find_text("zkdx-161085-2", [b"x"], zero_misreads=True) == {"found": False}
        assert screen_ocr.find_text("ZKDX-161985-2", [b"x"], zero_misreads=True) == {"found": False}
        # Only the screen's slashed zero is folded: a value carrying Ø is not the zero the screen showed.
        screen_ocr.read_lines = lambda images, **_kw: [["DECF-604811-5"]]
        assert screen_ocr.find_text("DECF-6\u00d84811-5", [b"x"]) == {"found": False}
    finally:
        screen_ocr.read_lines = original


class _GaugeBody(_VisionBody):
    def __init__(self) -> None:
        super().__init__()
        self.watch_calls: list[dict] = []
        self.clicked: list[str] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"] = {
            "viewport_text": "Watch the gauge. Sample",
            "controls": [
                {"index": 1, "tag": "button", "text": "Sample", "selector": "#sample", "x": 10, "y": 10, "width": 80, "height": 30},
                {"index": 2, "tag": "span", "text": "-", "selector": "#gauge", "x": 100, "y": 10, "width": 80, "height": 30},
            ],
        }
        return shot

    async def vision_click_control(self, selector: str, x: int, y: int, **_kwargs: object) -> dict:
        self.clicked.append(selector)
        return {"ok": True, "action": "click", "surface_changed": True, "verification_observed": True}

    async def vision_watch(self, *, selector: str = "", point=None, duration_ms: int = 0) -> dict:
        self.watch_calls.append({"selector": selector, "point": point, "duration_ms": duration_ms})
        return {"ok": True, "action": "watch", "watched_ms": duration_ms, "samples": 300,
                "values": [{"t_ms": 0, "text": "-"}, {"t_ms": 500, "text": "#1: 450"}, {"t_ms": 1000, "text": "#2: 977"}]}


def test_click_then_watch_reports_every_value_to_the_model(monkeypatch) -> None:
    init_db()
    body = _GaugeBody()
    decisions = iter([
        {"action": "click", "control": 1, "x": 50, "y": 25, "reason": "Start sampling.",
         "then": [{"action": "watch", "control": 2, "wait_ms": 13000}]},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    contexts: list[dict] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence",
                        lambda *args, **kwargs: {"classification": "ordinary_reversible", "confidence": 0.99, "evidence": "Fixture."})
