class _QuietClickGaugeBody(_GaugeBody):
    """The Sample press's own read-back sees no change; what the gauge (or a status) shows next is set
    per test."""

    def __init__(self, values: list[str], *, wait_matched: bool = False) -> None:
        super().__init__()
        self.values = list(values)
        self.wait_matched = wait_matched
        self.waits: list[dict] = []

    async def vision_click_control(self, selector: str, x: int, y: int, **kwargs: object) -> dict:
        result = await super().vision_click_control(selector, x, y, **kwargs)
        return {**result, "surface_changed": False, "title_changed": False, "url_changed": False}

    async def vision_watch(self, *, selector: str = "", point=None, duration_ms: int = 0) -> dict:
        self.watch_calls.append({"selector": selector, "point": point, "duration_ms": duration_ms})
        return {"ok": True, "action": "watch", "watched_ms": duration_ms, "samples": 300,
                "values": [{"t_ms": index * 500, "text": text} for index, text in enumerate(self.values)]}

    async def vision_wait(self, wait_ms: int, *, text: str = "") -> dict:
        self.waits.append({"wait_ms": wait_ms, "text": text})
        return {"ok": True, "action": "wait", "waited_ms": wait_ms, "text_matched": bool(text) and self.wait_matched}

    async def vision_scroll(self, dy: int, **_kwargs: object) -> dict:
        self.scrolls += 1
        return {"ok": True, "before_scroll_y": 0, "scroll_y": dy}


_SCROLL_DOWN = {"action": "scroll", "control": 0, "x": 0, "y": 0, "direction": "down", "amount": 300}


def _run_click_chain(monkeypatch, body, then: list[dict], judge=None) -> str:
    """One click chained into ``then``; returns the recent actions the next decision read."""
    decisions = iter([
        {"action": "click", "control": 1, "x": 50, "y": 25, "reason": "Start sampling.", "then": then},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    contexts: list[dict] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(dict(context))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence",
                        judge or (lambda *args, **kwargs: {"classification": "ordinary_reversible", "confidence": 0.99, "evidence": "Fixture."}))
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))
    return " ".join(str(item) for item in (contexts[1].get("recent_actions") or [])) if len(contexts) > 1 else ""


def test_a_click_whose_effect_is_not_yet_visible_still_runs_its_chained_watch(monkeypatch) -> None:
    # v3_tempo: the Sample press came back "click_unverified" (the gauge starts after the click's own
    # read-back), the chained watch was dropped, and a separate watch a turn later missed readings.
    init_db()
    body = _QuietClickGaugeBody(["-", "#1: 450", "#2: 977"])

    recent = _run_click_chain(monkeypatch, body, [{"action": "watch", "control": 2, "wait_ms": 13000}, _SCROLL_DOWN])

    assert body.clicked == ["#sample"]
    assert body.watch_calls == [{"selector": "#gauge", "point": None, "duration_ms": 13000}]
    # The gauge moved: the watch saw the click take effect, so the rest of the chain runs.
    assert body.scrolls == 1
    assert "click_effect_not_observed" not in recent


def test_a_watch_that_saw_nothing_change_does_not_confirm_an_unverified_click(monkeypatch) -> None:
    # A watch always reports its first reading: one unchanged value is no reaction to the click.
    init_db()
    body = _QuietClickGaugeBody(["-"])

    recent = _run_click_chain(monkeypatch, body, [{"action": "watch", "control": 2, "wait_ms": 4000}, _SCROLL_DOWN])

    assert body.clicked == ["#sample"] and len(body.watch_calls) == 1, "the observation itself still runs"
    assert body.scrolls == 0, "nothing after it runs on the assumption the click worked"
    assert "sequence_aborted at step 2: click_effect_not_observed" in recent
    assert "the click at step 1 came back unverified" in recent


def test_a_wait_for_text_confirms_an_unverified_click_only_when_the_text_appears(monkeypatch) -> None:
    wait = {"action": "wait", "wait_ms": 3000, "text": "Sampling started"}
    for matched, scrolls in ((True, 1), (False, 0)):
        init_db()
        body = _QuietClickGaugeBody(["-"], wait_matched=matched)

        recent = _run_click_chain(monkeypatch, body, [dict(wait), _SCROLL_DOWN])

        assert body.waits == [{"wait_ms": 3000, "text": "Sampling started"}]
        assert body.scrolls == scrolls, matched
        assert ("click_effect_not_observed" in recent) is (not matched)


def _ordinary_judge(*args: object, **kwargs: object) -> dict:
    return {"classification": "intermediate", "confidence": 0.99, "evidence": "Fixture."}


_CLICK_TWO = {"action": "click", "control": 2, "x": 60, "y": 30, "reason": "Press TWO."}


def _freeze_wait_credit(monkeypatch) -> None:
    """A bare wait counts from the previous dispatch, so the real time the fixture's steps take (xdist load) would
    shave the planned wait_ms. Evaluate the plan at the dispatch instant: zero elapsed, production logic intact."""
    real_plan = extension_run._bare_wait_plan

    def plan(step_timing: dict, requested_ms: int, *, now: float) -> tuple[int, int]:
        ref = step_timing.get("_dispatch_ref")
        return real_plan(step_timing, requested_ms, now=float(ref) if isinstance(ref, (int, float)) else now)

    monkeypatch.setattr(extension_run, "_bare_wait_plan", plan)


def test_a_bare_wait_is_transparent_between_an_unverified_click_and_an_independent_click(monkeypatch) -> None:
    _freeze_wait_credit(monkeypatch)
    # MiniWoB button-delay: click ONE, wait N s, click TWO. ONE changes nothing visible; the chain must still
    # run the wait and TWO so the real gap is the planned one.
    init_db()
    body = _QuietClickGaugeBody(["-"])

    recent = _run_click_chain(monkeypatch, body, [{"action": "wait", "wait_ms": 1000}, dict(_CLICK_TWO)], judge=_ordinary_judge)

    assert body.waits == [{"wait_ms": 1000, "text": ""}], recent
    assert body.clicked == ["#sample", "#gauge"]
    assert "verification_failed" not in recent


def test_a_dependent_action_after_a_bare_wait_still_aborts_an_unverified_click(monkeypatch) -> None:
    init_db()
    body = _QuietClickGaugeBody(["-"])

