class _QuietClickWaitingScreenBody(_DesktopScreenBody):
    def __init__(self) -> None:
        super().__init__()
        self.waits: list[int] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        for control in shot["page_evidence"]["controls"]:
            control.update({"x": 20, "y": 10})  # under the chain's click point (50, 25)
        return shot

    async def vision_click_control(self, selector: str, x: int, y: int, **_kwargs: object) -> dict:
        self.clicks.append(("control", selector))
        return {"ok": True, "action": "click", "surface_changed": False, "title_changed": False, "url_changed": False}

    async def vision_wait(self, wait_ms: int, **_kwargs: object) -> dict:
        self.waits.append(wait_ms)
        return {"ok": True, "action": "wait", "waited_ms": wait_ms}


def test_an_unverified_desktop_click_does_not_chain_into_a_wait_that_only_sleeps(monkeypatch) -> None:
    # On the real screen a wait's text is dropped (it only sleeps), so it observes nothing.
    init_db()
    body = _QuietClickWaitingScreenBody()

    recent = _run_click_chain(
        monkeypatch, body, [{"action": "wait", "wait_ms": 1500, "text": "Allowed"}, {"action": "key", "key": "Enter"}]
    )

    assert body.clicks == [("control", "uia:allow")]
    assert body.waits == []
    assert "sequence_aborted at step 1: verification_failed" in recent


def test_only_a_browser_watch_or_wait_for_text_observes_and_only_a_change_is_a_reaction() -> None:
    watch, wait_text, plain_wait = {"action": "watch"}, {"action": "wait", "text": "Ready"}, {"action": "wait", "text": ""}
    assert extension_run._action_observes_reaction(watch, "browser")
    assert extension_run._action_observes_reaction(wait_text, "browser")
    assert not extension_run._action_observes_reaction(plain_wait, "browser")
    assert not extension_run._action_observes_reaction({"action": "scroll"}, "browser")
    assert not extension_run._action_observes_reaction(watch, "desktop")
    assert not extension_run._action_observes_reaction(wait_text, "desktop")

    def watched(*texts: str, ok: bool = True) -> dict:
        return {"ok": ok, "action": "watch", "values": [{"t_ms": index, "text": text} for index, text in enumerate(texts)]}

    assert extension_run._observation_saw_reaction("watch", watched("-", "#1: 450"))
    assert not extension_run._observation_saw_reaction("watch", watched("-"))
    assert not extension_run._observation_saw_reaction("watch", watched())
    assert not extension_run._observation_saw_reaction("watch", watched("-", "#1", ok=False))
    assert extension_run._observation_saw_reaction("wait", {"ok": True, "text_matched": True})
    assert not extension_run._observation_saw_reaction("wait", {"ok": True, "text_matched": False})
    assert not extension_run._observation_saw_reaction("wait", {"ok": True})
    assert not extension_run._observation_saw_reaction("scroll", {"ok": True, "scroll_y": 300})


class _TkFieldScreenBody(_DesktopScreenBody):
    """The real screen with a Tk entry UIA exposes only as an unnamed pane."""

    def __init__(self) -> None:
        super().__init__()
        self.typed: list[str] = []

    async def capture_screenshot(self) -> dict:
        import io

        from PIL import Image

        shot = await super().capture_screenshot()
        buffer = io.BytesIO()
        Image.new("RGB", (1600, 900), (240, 240, 240)).save(buffer, format="PNG")
        shot["image"] = base64.b64encode(buffer.getvalue()).decode("ascii")
        shot["page_evidence"] = {
            "viewport_text": "Field Unit - Dispatch. Dock code",
            "controls": [{"index": 1, "tag": "pane", "role": "Pane", "text": "", "selector": "uia:hwnd=1;rid=2",
                          "x": 200, "y": 240, "width": 160, "height": 40}],
        }
        return shot

    async def vision_type(self, text: str, **_kwargs: object) -> dict:
        self.typed.append(text)
        return {"ok": True, "action": "type", "desktop_surface": True, "active_typable": True}


def test_desktop_type_at_a_point_without_an_accessible_field_is_judged_from_pixels(monkeypatch) -> None:
    # The type goes where the click just before it put the caret, so that point is what is judged.
    init_db()
    body = _TkFieldScreenBody()
    decisions = iter([
        {"action": "click", "control": 0, "x": 268, "y": 264, "reason": "Put the caret in the dock code entry.",
         "then": [{"action": "type", "control": 0, "x": 268, "y": 264, "text": "D7-6KJ", "question": "Dock code",
                   "grounding_source": "goal", "grounding_quote": "D7-6KJ"}]},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    judged: list[dict] = []

    def binding_judge(user_id: int, **kwargs) -> dict:
        judged.append(kwargs)
        return {"matches": True, "reason": "The ring is on the Dock code entry."}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_target_binding_judge", binding_judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(next(decisions, done)))

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    assert judged, "the binding was judged instead of failing as unresolved"
    assert judged[0].get("image") and judged[0].get("selected_point") == {"x": 268, "y": 264}


def test_desktop_typing_into_focus_is_bound_at_the_field_just_clicked(monkeypatch) -> None:
    init_db()
    body = _TkFieldScreenBody()
    decisions = iter([
        {"action": "click", "control": 0, "x": 268, "y": 264, "question": "Dock code", "reason": "Focus the dock code entry."},
        {"action": "type", "control": 0, "x": 0, "y": 0, "text": "D7-6KJ", "question": "Dock code",
         "grounding_source": "goal", "grounding_quote": "D7-6KJ", "reason": "Enter the dock code."},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    judged: list[dict] = []

    def binding_judge(user_id: int, **kwargs) -> dict:
        judged.append(kwargs)
        return {"matches": True, "reason": "The ring is on the Dock code entry."}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_target_binding_judge", binding_judge)
    monkeypatch.setattr(extension_run, "_judge_click_consequence",
                        lambda *args, **kwargs: {"classification": "ordinary_reversible", "confidence": 0.99, "evidence": "Fixture."})
    contexts: list[dict] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return dict(next(decisions, done))

    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    # The type into focus is bound at the field just clicked: the same question at the same point
    # reuses that visual verdict instead of failing as an unresolved binding.
    assert judged and judged[0].get("selected_point") == {"x": 268, "y": 264}
    feedback = " ".join(item for context in contexts for item in context.get("recent_actions") or [])
    assert "target_binding_unresolved" not in feedback


