def test_the_real_screen_fingerprint_follows_its_pixels() -> None:
    import io

    from PIL import Image, ImageDraw

    def desktop_shot(text: str) -> dict:
        img = Image.new("RGB", (1920, 1200), (235, 235, 235))
        draw = ImageDraw.Draw(img)
        draw.rectangle([500, 500, 800, 540], fill=(255, 255, 255))
        if text:
            draw.text((510, 510), text, fill=(0, 0, 0))
        buffer = io.BytesIO()
        img.save(buffer, format="JPEG", quality=70)
        return {"url": "desktop://windows", "image": base64.b64encode(buffer.getvalue()).decode("ascii"),
                "page_evidence": {"viewport_text": "Visible Windows: Field Unit", "controls": []}}

    empty, typed = desktop_shot(""), desktop_shot("D9-JZF")
    assert extension_run._page_state_fingerprint(empty) == extension_run._page_state_fingerprint(desktop_shot(""))
    assert extension_run._page_state_fingerprint(empty) != extension_run._page_state_fingerprint(typed)


def test_a_follow_click_carries_the_target_pixels_and_a_search_region() -> None:
    import io

    from PIL import Image

    img = Image.new("RGB", (1200, 800), (16, 23, 36))
    buffer = io.BytesIO()
    img.save(buffer, format="PNG")
    shot = {"image": base64.b64encode(buffer.getvalue()).decode("ascii")}

    def click(x, y, *, follow=None, **_kwargs):
        return None

    canvas = {"tag": "canvas", "x": 100, "y": 200, "width": 600, "height": 300}
    kwargs = extension_run._follow_click_kwargs(click, {"action": "click", "follow": True}, shot, canvas, 400, 350)
    follow = kwargs["follow"]
    assert follow["template"] and follow["template_center"] == [22, 22]
    assert follow["region"] == [92, 192, 708, 508]
    assert extension_run._follow_click_kwargs(click, {"action": "click"}, shot, canvas, 400, 350) == {}

    def plain_click(x, y, **_kwargs):
        return None

    assert extension_run._follow_click_kwargs(plain_click, {"action": "click", "follow": True}, shot, canvas, 400, 350) == {}


