def test_a_value_the_page_showed_counts_as_page_text_while_typing_on_the_desktop(monkeypatch) -> None:
    init_db()
    body = _switching_body(_ExportPageBody(), _TkFieldScreenBody())
    decisions = iter([
        {"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "Use the save dialog."},
        {"action": "type", "control": 0, "x": 268, "y": 264, "text": "report-K7QX.txt", "question": "File name",
         "grounding_source": "page", "grounding_quote": "report-K7QX.txt", "reason": "Name the report."},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    classifier_calls: list[dict] = []

    def classify(*args, **kwargs) -> dict:
        classifier_calls.append(kwargs)
        return {"verdict": "ordinary", "confidence": 0.97, "reason": "Filename.", "evidence": "Fixture.",
                "metadata": {"provider": "fixture", "normalization": "validated"}}

    async def narrate(kind: str, data: dict) -> None:
        pass

    events: list[tuple[str, dict]] = []
    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_secret_request_classifier", classify)
    monkeypatch.setattr(extension_run, "_call_target_binding_judge", lambda user_id, **kwargs: {"matches": True, "reason": "ok"})
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(next(decisions, done)))

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    # The page's own text (verbatim, one page host) proves the value without a model, so the
    # classifier is not asked at all and the gate records the provenance proof.
    typed = [call for call in classifier_calls if (call.get("action_evidence") or {}).get("action") == "type"]
    assert typed == []
    verdicts = [payload for event, payload in events if event == "VISION_SECRET_INTERACTION_CLASSIFIED" and payload.get("action") == "type"]
    assert verdicts and verdicts[0]["verdict"] == "ordinary"
    assert verdicts[0]["classifier_source"] == "page_provenance"
    assert "task page text carried into a native app" in verdicts[0]["reason_text"]


