def test_page_composition_matches_whole_runs_of_the_page_text_only() -> None:
    page = "Outbox: C:/Bench/mission-7/outbox. Save the report as report-ELMZ.txt there. Ref 99482913771."
    assert extension_run._typed_text_composed_of_page_tokens("C:/Bench/mission-7/outbox/report-ELMZ.txt", page)
    assert extension_run._typed_text_composed_of_page_tokens("c:/bench/MISSION-7/outbox/REPORT-elmz.TXT", page)
    assert extension_run._typed_text_composed_of_page_tokens("99482913771", page)
    # A code hidden inside a longer run of the page (digits, or letters) is not one of its words.
    assert not extension_run._typed_text_composed_of_page_tokens("482913", page)
    assert not extension_run._typed_text_composed_of_page_tokens("C:/Bench/mission-7/outbox/482913.txt", page)
    assert not extension_run._typed_text_composed_of_page_tokens("Out", page)
    assert not extension_run._typed_text_composed_of_page_tokens("", page)
    assert not extension_run._typed_text_composed_of_page_tokens("-/.", page)
    assert not extension_run._typed_text_composed_of_page_tokens("report", "")


