def test_a_code_only_inside_a_longer_page_run_or_off_screen_is_not_cleared_on_the_desktop(monkeypatch) -> None:
    # The deterministic page-composition proof reads the text the page showed on screen, word by
    # word: neither a digit run hiding the code nor the tab's off-screen text clears it.
    for text, expected in (
        ("C:/Bench/mission-7/outbox/482913.txt", "uncertain"),
        ("C:/Bench/mission-7/outbox/99482913771.txt", "ordinary"),
    ):
        init_db()
        page = _HiddenRunPageBody()
        body = _switching_body(page, _TkFieldScreenBody())
        decisions = iter([
            {"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "Save dialog."},
            {"action": "type", "control": 0, "x": 268, "y": 264, "text": text, "question": "File name",
             "grounding_source": "page", "grounding_quote": "outbox", "reason": "Name it."},
        ])
        done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
        events: list[tuple[str, dict]] = []
        contexts: list[dict] = []

        async def narrate(kind: str, data: dict) -> None:
            pass

        def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
            contexts.append(dict(context))
            return dict(next(decisions, done))

        monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
        monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: events.append((event_type, payload)))
        monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
        monkeypatch.setattr(extension_run, "_call_secret_request_classifier", lambda *args, **kwargs: {
            "verdict": "uncertain", "confidence": 0.72, "reason": "Unsure.", "evidence": "Fixture.",
            "metadata": {"provider": "fixture", "normalization": "validated_no_distinct_adjudicator"}})
        monkeypatch.setattr(extension_run, "_judge_page_quote_visible", lambda provider, *, images, quote, **_kw: {"visible": False, "confidence": 0.9})
        monkeypatch.setattr(extension_run, "_call_target_binding_judge", lambda user_id, **kwargs: {"matches": True, "reason": "ok"})
        monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)

        asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

        desktop_views = [context["last_page_view"] for context in contexts if context.get("execution_surface") == "desktop"]
        assert desktop_views and "Footer 482913" in desktop_views[0]["document_text"], "the brain still reads it"
        verdicts = [payload for event, payload in events if event == "VISION_SECRET_INTERACTION_CLASSIFIED" and payload.get("action") == "type"]
        assert verdicts and verdicts[0]["verdict"] == expected, (text, verdicts[0]["verdict"])


