def test_a_covered_window_stays_in_desktop_view_memory() -> None:
    memory: dict = {}
    field_unit = {"media_type": "image/png", "data": "field-unit"}
    extension_run._remember_desktop_view(
        memory, field_unit, [{"window_id": "hwnd:1", "title": "Field Unit", "active": True}, {"window_id": "hwnd:2", "title": "notes.txt - Notepad"}]
    )
    for step in range(5):
        # The editor's title changes as it is edited; it is still one window.
        title = "notes.txt - Notepad" if step % 2 else "*notes.txt - Notepad"
        extension_run._remember_desktop_view(
            memory,
            {"media_type": "image/png", "data": f"notepad-{step}"},
            [{"window_id": "hwnd:1", "title": "Field Unit"}, {"window_id": "hwnd:2", "title": title, "active": True}],
        )

    assert memory["images"] == [field_unit, {"media_type": "image/png", "data": "notepad-4"}]
    assert memory["image"]["data"] == "notepad-4"
    assert memory["titles"] == ["Field Unit", "*notes.txt - Notepad"]

    for index in range(extension_run._DESKTOP_VIEW_MEMORY_WINDOWS):
        extension_run._remember_desktop_view(
            memory, {"media_type": "image/png", "data": f"w{index}"}, [{"title": f"Window {index}", "active": True}]
        )
    assert field_unit not in memory["images"]
    assert len(memory["images"]) == extension_run._DESKTOP_VIEW_MEMORY_WINDOWS


class _NotepadScreenBody(_TkFieldScreenBody):
    """A native editor: caret keys keep the OS focus on the text area the model clicked."""

    def __init__(self) -> None:
        super().__init__()
        self.type_calls: list[dict] = []
        self.keys: list[str] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"]["viewport_text"] = "notes.txt - Notepad. Dock code: ________ (dispatch says D7-6KJ)"
        return shot

    async def vision_key(self, key: str, **_kwargs: object) -> dict:
        self.keys.append(key)
        return {"ok": True, "action": "key", "surface_changed": True, "focus_changed": False, "active_typable": True}

    async def vision_type(self, text: str, *, at_caret: bool = False) -> dict:
        self.type_calls.append({"text": text, "at_caret": at_caret})
        return {"ok": True, "action": "type", "desktop_surface": True, "active_typable": True,
                "active_has_value": True, "active_value_matches_expected": True}


def _run_desktop_typing(monkeypatch, body, decisions: list[dict]) -> list[dict]:
    decision_iter = iter(decisions)
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    contexts: list[dict] = []

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        return dict(next(decision_iter, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_target_binding_judge",
                        lambda user_id, **kwargs: {"matches": True, "reason": "The ring is on the blank."})
    monkeypatch.setattr(extension_run, "_judge_click_consequence",
                        lambda *args, **kwargs: {"classification": "ordinary_reversible", "confidence": 0.99, "evidence": "Fixture."})
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True,
                                max_steps=len(decisions) + 1))
    return contexts


