def test_a_typed_point_inside_the_indexed_control_is_one_target() -> None:
    combobox = {"selector": "uia:hwnd=1;rid=10", "tag": "combobox", "text": "Address", "x": 560, "y": 300, "width": 400, "height": 40}
    edit = {"selector": "uia:hwnd=1;rid=11", "tag": "edit", "text": "Address", "x": 570, "y": 305, "width": 360, "height": 30}
    typed = extension_run._reconcile_action_control_references(
        {"action": "type", "text": "C:\mission\outbox"}, indexed_control=combobox, coordinate_control=edit
    )
    assert typed["ok"] is True and typed["control"] is edit and typed["source"] == "coordinate_nested_in_index"
    # A click keeps the arbiter: an inner button inside a field must not silently win.
    clicked = extension_run._reconcile_action_control_references(
        {"action": "click", "text": ""}, indexed_control=combobox, coordinate_control=edit
    )
    assert clicked["ok"] is False


