def test_clicks_on_different_unnamed_controls_are_not_one_repeated_action() -> None:
    fingerprint = extension_run._progress_action_fingerprint
    name_field = fingerprint("click", {"action": "click", "x": 351, "y": 188}, target_text="")
    reference_field = fingerprint("click", {"action": "click", "x": 301, "y": 212}, target_text="")
    jittered_name = fingerprint("click", {"action": "click", "x": 349, "y": 189}, target_text="")
    assert name_field != reference_field, "a field one row down is a different action"
    assert name_field == jittered_name, "re-clicking the same spot is still a repeat"
    # Named controls keep their text identity whatever the point.
    assert fingerprint("click", {"action": "click", "x": 10, "y": 10}, target_text="Save") == fingerprint(
        "click", {"action": "click", "x": 400, "y": 300}, target_text="Save"
    )


