def test_classifier_words_are_kept_only_when_they_cannot_carry_the_value() -> None:
    reason = "The text editor is the user's own app and the value is a shipping container identifier."
    assert _value_free_diagnostic(reason, "BALE-462312-4") == reason
    # Any quoted run of the value, even re-spaced, drops the text entirely.
    assert _value_free_diagnostic("It would type BALE 4623 12-4 into Notepad.", "BALE-462312-4") == ""
    assert _value_free_diagnostic("the id ends in 62312", "BALE-462312-4") == ""
    assert _value_free_diagnostic(reason, "") == reason
