def test_a_blocked_file_dialog_click_points_to_the_real_screen_when_the_run_has_it() -> None:
    from types import SimpleNamespace

    both = SimpleNamespace(available_surfaces=lambda: ["browser", "desktop"])
    text = extension_run._file_dialog_click_feedback(both, "Completed declaration")
    assert "switch_surface to desktop" in text and "Open dialog" in text
    assert "cannot see or close" not in text
    # A saved document goes through upload, and that route survives the recent-action line's shortening.
    assert text.index("use upload with that artifact_role") < text.index("switch_surface")
    assert "use upload with that artifact_role" in text[:300]
    browser_only = SimpleNamespace(available_surfaces=lambda: ["browser"])
    text = extension_run._file_dialog_click_feedback(browser_only, "Completed declaration")
    assert "cannot see or close" in text and "switch_surface" not in text
    assert "cannot see or close" in extension_run._file_dialog_click_feedback(object(), "Résumé")



def test_a_run_that_stops_narrating_ends_blocked_with_a_stack_dump(monkeypatch) -> None:
    init_db()
    from pathlib import Path

    events: list = []
    monkeypatch.setattr(extension_run, "_RUN_STALL_SECONDS", 0.6)
    monkeypatch.setattr(extension_run, "_RUN_STALL_POLL_SECONDS", 0.1)
    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, kind, payload=None, *a, **k: events.append((kind, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action",
                        lambda *args, **kwargs: {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."})

    async def stuck_narrate(kind: str, data: dict) -> None:
        await asyncio.Event().wait()  # a narration hop that never returns

    summary = asyncio.run(run_vision_loop(_KeyScreenBody(), url=None, narrate=stuck_narrate, run_id=0, user_id=0,
                                          skip_navigate=True, max_steps=2))
    assert summary["state"] == "BLOCKED" and summary["reason"] == "runtime_stall"
    dump = Path(summary["stack_dump"])
    assert dump.exists() and "== asyncio tasks ==" in dump.read_text(encoding="utf-8")
    assert any(kind == "RUN_STALL_DETECTED" for kind, _ in events)


