class _EngageBody(_DesktopScreenBody):
    """An Engage button whose every press changes the page (a counter), or toggles between two states."""

    def __init__(self, toggle: bool) -> None:
        super().__init__()
        self.toggle = toggle

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        presses = len(self.clicks)
        state = ("State A" if presses % 2 == 0 else "State B") if self.toggle else f"Engaged {presses} times"
        shot["page_evidence"] = {
            "viewport_text": f"Shuffle drill. {state}",
            "controls": [{"index": 1, "tag": "button", "role": "button", "text": "Engage", "selector": "uia:engage",
                          "x": 900, "y": 120, "width": 80, "height": 30}],
        }
        return shot


