def test_follow_payload_names_why_it_was_not_built() -> None:
    def with_follow(x, y, *, follow=None):
        return None

    def without_follow(x, y):
        return None

    action = {"action": "click", "follow": True}
    skip: dict = {}
    assert extension_run._follow_click_kwargs(without_follow, action, {"image": "x"}, None, 10, 10, skip) == {}
    assert skip["reason"] == "method_no_follow"
    skip = {}
    assert extension_run._follow_click_kwargs(with_follow, action, {"image": ""}, None, 10, 10, skip) == {}
    assert skip["reason"] == "no_image"
    skip = {}
    assert extension_run._follow_click_kwargs(with_follow, action, {"image": "not-an-image"}, None, 10, 10, skip) == {}
    assert skip["reason"] == "exception"
    skip = {}
    assert extension_run._follow_click_kwargs(with_follow, {"action": "click"}, {"image": "x"}, None, 10, 10, skip) == {}
    assert skip == {}, "no follow asked, nothing to explain"


def test_a_failed_follows_frame_and_template_become_run_artifacts(tmp_path, monkeypatch) -> None:
    from types import SimpleNamespace

    monkeypatch.setattr(extension_run, "get_settings", lambda: SimpleNamespace(artifact_root=tmp_path))
    png = base64.b64encode(b"\x89PNG fake").decode("ascii")
    result = {"ok": False, "failure_reason": "follow_target_not_found", "follow_debug_frame": png, "follow_debug_template": png}
    saved = extension_run._save_follow_debug_images(773, 30, result)
    assert "follow_debug_frame" not in saved and "follow_debug_template" not in saved
    assert [p.split("\\")[-1].split("/")[-1] for p in saved["follow_debug_images"]] == ["follow-30-frame.png", "follow-30-template.png"]
    assert (tmp_path / "runs" / "773" / "follow-30-frame.png").read_bytes() == b"\x89PNG fake"


class _LabelClickBody(_TimedReleaseBody):
    def __init__(self) -> None:
        super().__init__(ready_text_appears=True)
        self.label_clicks: list[str] = []

    async def vision_click(self, x: int, y: int, *, target_text: str = "", **_binding: object) -> dict:
        if target_text:
            self.label_clicks.append(target_text)
            return {"ok": True, "action": "click", "surface_changed": True, "target_text_resolved": True}
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", "surface_changed": True}


