class _ScrollingSampleBody(_TimedReleaseBody):
    """Pressing Sample scrolls the page up 200 px; the gauge the model saw is now higher."""

    def __init__(self) -> None:
        super().__init__(ready_text_appears=True)
        self.watch_points: list = []

    async def vision_click(self, x: int, y: int, **_binding: object) -> dict:
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", "surface_changed": True, "scroll_delta_img": [0, 200]}

    async def vision_watch(self, *, selector: str = "", point=None, duration_ms: int = 5000) -> dict:
        self.watch_points.append(tuple(point) if point else None)
        return {"ok": True, "action": "watch", "values": [{"t_ms": 0, "text": "#1: 412"}]}


