def test_the_consequence_judge_sees_the_labeled_control_a_reaction_will_press(monkeypatch) -> None:
    # Run 775: the Commit then-click reached the judge as "control 0, no selector, no point" and was
    # withheld as uncertain every time.
    init_db()
    body = _LabelClickBody()
    judged: list = []

    def judge(*args, **kwargs):
        judged.append(kwargs.get("bound_control"))
        return {"classification": "intermediate", "confidence": 0.99, "evidence": "Fixture."}

    decisions = iter([
        {"action": "click", "x": 100, "y": 200, "reason": "Hold still; commit when the window opens.",
         "then": [{"action": "wait", "wait_ms": 9000, "text": "Ready - fire now"},
                  {"action": "click", "target_text": "Commit", "reason": "Press Commit."}]},
        {"action": "done", "reason": "Committed."},
    ])

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence", judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    labeled = [control for control in judged if isinstance(control, dict) and control.get("text") == "Commit"]
    assert labeled and labeled[0]["tag"] == "button"
    assert body.label_clicks == ["Commit"]



class _AutoWaitBody(_TimedReleaseBody):
    def __init__(self) -> None:
        super().__init__(ready_text_appears=True)
        self.label_clicks: list[tuple[str, int]] = []

    async def vision_click(self, x: int, y: int, *, target_text: str = "", target_wait_ms: int = 0, **_binding: object) -> dict:
        if target_text:
            self.label_clicks.append((target_text, target_wait_ms))
            return {"ok": True, "action": "click", "surface_changed": True, "target_text_resolved": True,
                    "waited_for_target_ms": 8100}
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", "surface_changed": True}


