def test_the_drag_trace_in_step_feedback_is_compact_and_keeps_both_ends() -> None:
    route = [[100 + index * 5, 400 + (index % 3)] for index in range(42)]
    hint = _vision_result_hint(
        {
            "ok": True,
            "action": "drag",
            "drag_route": route,
            "drag_from_tag": "canvas",
            "drag_to_tag": "canvas",
            "drag_distance_model_px": 207,
            "surface_changed": True,
        }
    )
    assert "pointer route in screenshot pixels (100,400) -> " in hint
    assert f"-> ({route[-1][0]},{route[-1][1]}) (12 of 42 points shown)" in hint
    assert "pressed on <canvas>, released on <canvas>" in hint
    assert "the held pointer moved 207px" in hint
    assert "visible page surface changed" in hint
    assert len(hint) < 420
    straight = _vision_result_hint({"ok": True, "action": "drag", "drag_route": [[10, 20], [30, 40]]})
    assert straight == "pointer route in screenshot pixels (10,20) -> (30,40)"
    assert "pointer route" not in _vision_result_hint({"ok": True, "action": "click", "surface_changed": True})


class _DragReceiptBody(_GestureBody):
    """A browser body whose drag returns the extension's receipt fields."""

    async def vision_drag(self, x: int, y: int, to_x: int, to_y: int, *, button: str = "left", path=None, hold_ms: int = 0, modifiers=None) -> dict:
        self.drags.append({"from": (x, y), "to": (to_x, to_y), "path": list(path or [])})
        return {
            "ok": True,
            "action": "drag",
            "mode": "pointer_drag",
            "activation_attempted": True,
            "activation_dispatched": True,
            "drag_from_tag": "canvas",
            "drag_to_tag": "div",
            "drag_distance_px": 260,
            "native_drag_intercepted": False,
            "surface_changed": True,
        }


def test_a_missed_drag_leaves_its_route_in_the_decision_event_and_the_next_prompt(monkeypatch) -> None:
    init_db()
    body = _DragReceiptBody()
    events: list[tuple[str, dict]] = []
    contexts: list[dict] = []
    decisions = iter(
        [
            {
                "action": "drag",
                "x": 100,
                "y": 400,
                "to_x": 300,
                "to_y": 450,
                "path": [{"x": 200, "y": 420}],
                "reason": "Trace the corridor to the exit.",
            },
            {"action": "done", "reason": "Finished."},
        ]
    )

    def decide(_user_id, _image, _view, context):
        contexts.append(context)
        return next(decisions)

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda _run_id, event_type, payload: events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))

    assert body.drags == [{"from": (100, 400), "to": (300, 450), "path": [(200, 420)]}]
    decided = next(payload for event_type, payload in events if event_type == "VISION_AGENT_DECISION" and payload.get("action") == "drag")
    assert decided["path"] == [[200, 420]]
    assert (decided["x"], decided["y"], decided["to_x"], decided["to_y"]) == (100, 400, 300, 450)
    assert len(contexts) >= 2
    drag_line = next(line for line in contexts[1]["recent_actions"] if line.startswith("drag"))
    assert "pointer route in screenshot pixels (100,400) -> (200,420) -> (300,450)" in drag_line
    assert "pressed on <canvas>, released on <div>" in drag_line
    assert "the held pointer moved 260px" in drag_line


