def test_read_backs_the_page_wiped_are_reopened() -> None:
    # v2_form_crucible from the brain seat: the page's step timer cleared the form in place, and
    # session_ledger / satisfied_controls kept claiming the wiped values.
    company = {"tag": "input", "type": "text", "context_text": "Company", "selector": "#company", "value": ""}
    business = {"tag": "input", "type": "radio", "context_text": "Business", "selector": "#acct-business", "checked": False}
    first = {"tag": "input", "type": "text", "context_text": "First name", "selector": "#first", "value": "Lumen"}
    ledger = {
        extension_run._control_signature(company): {"label": "Company", "verified_value": "Halide Labs", "verified": True},
        extension_run._control_signature(first): {"label": "First name", "verified_value": "Lumen", "verified": True},
        "off-screen-signature": {"label": "VAT number", "verified_value": "GB123", "verified": True},
    }
    satisfied = {extension_run._control_signature(business): {"control": "Account type", "value": "Business"}}

    reopened = extension_run._reopen_read_backs_the_page_lost(
        {"controls": [company, business, first]}, ledger, satisfied
    )

    assert set(reopened) == {"Company", "Account type"}
    assert ledger[extension_run._control_signature(company)]["verified_value"] is None
    assert ledger[extension_run._control_signature(first)]["verified_value"] == "Lumen"
    assert ledger["off-screen-signature"]["verified_value"] == "GB123"
    assert satisfied == {}



