# --- Safety review of 2026-10-01's main diff: regression tests -------------------------------------------


def _ordinary_judge(*args, **kwargs):
    return {"classification": "intermediate", "confidence": 0.99, "evidence": "Fixture.", "metadata": {}}


def _run_scripted(monkeypatch, body, scripted, *, judge=_ordinary_judge, max_steps=3, engine=_DummyContextEngine):
    calls: list[int] = []
    contexts: list[dict] = []

    def fake_decide(*args: object) -> dict:
        calls.append(1)
        contexts.append(dict(args[3] or {}) if len(args) > 3 else {})
        if len(calls) <= len(scripted):
            return scripted[len(calls) - 1]
        return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", engine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_judge_click_consequence", judge)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=max_steps))
    return contexts


def test_a_type_that_did_not_read_back_ends_the_chain_before_its_verify_click(monkeypatch) -> None:
    # Review finding 1: a truncating field read back "555-1" and the chained Verify still ran.
    init_db()

    class _TruncatingBody(_CodeAndVerifyBody):
        async def vision_type_control(self, selector: str, text: str, **_binding: object) -> dict:
            self.type_control_calls.append((selector, text))
            return {"ok": True, "action": "type", "mode": "control_selector", "active_typable": True,
                    "active_has_value": True, "active_tag": "input", "active_value": text[:5], "active_selector": selector}

    body = _TruncatingBody()
    _run_scripted(monkeypatch, body, [
        {"action": "type", "control": 1, "x": 220, "y": 120, "text": "555-123-4567",
         "grounding_source": "profile", "grounding_quote": "555-123-4567", "reason": "Enter the code.",
         "then": [{"action": "click", "control": 2, "x": 420, "y": 120, "text": ""}]},
    ])
    assert body.type_control_calls[:1] == [("#code", "555-123-4567")]
