def test_a_chained_enter_is_judged_on_the_observed_focus_not_a_field_an_earlier_decision_typed_into(monkeypatch) -> None:
    # Closure review H(a): the field typed into one decision ago stood in for focus in the next decision's
    # chain, though the page had since moved focus elsewhere.
    init_db()
    judged: list[dict] = []

    def judge(*args, **kwargs):
        judged.append(dict(kwargs.get("bound_control") or {}))
        return _ordinary_judge()

    class _FocusMovedBody(_KeyboardConsoleBody):
        def __init__(self) -> None:
            super().__init__()
            self.keys: list[str] = []

        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            if self.type_control_calls:
                shot["page_evidence"]["controls"][1]["focused"] = True  # the page moved focus to Field B
            return shot

        async def vision_key(self, key, *args, **kwargs) -> dict:
            self.keys.append(str(key))
            return {"ok": True, "action": "key", "key": str(key)}

        async def vision_wait(self, wait_ms: int, *, text: str = "") -> dict:
            return {"ok": True, "action": "wait", "waited_ms": wait_ms}

    body = _FocusMovedBody()
    _run_scripted(monkeypatch, body, [
        {"action": "type", "control": 1, "text": "555-123-4567", "grounding_source": "profile",
         "grounding_quote": "555-123-4567", "reason": "Fill Field A."},
        {"action": "wait", "wait_ms": 100, "reason": "Let it settle.", "then": [{"action": "key", "key": "Enter"}]},
    ], judge=judge, max_steps=4)
    assert body.type_control_calls[:1] == [("#kb-a", "555-123-4567")]
    assert judged and judged[-1].get("selector") == "#kb-b"


