def test_a_type_that_did_not_read_back_blocks_every_later_click_of_its_sequence(monkeypatch) -> None:
    # Closure review M1: [type A (truncated), type B, click Verify] -- the abort only looked one step ahead.
    init_db()

    class _TwoCodesBody(_CodeAndVerifyBody):
        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            shot["page_evidence"]["controls"].insert(1, {
                "index": 3, "tag": "input", "type": "text", "text": "", "value": "", "context_text": "Confirm code",
                "selector": "#code2", "x": 100, "y": 160, "width": 240, "height": 40,
            })
            return shot

        async def vision_type_control(self, selector: str, text: str, **_binding: object) -> dict:
            self.type_control_calls.append((selector, text))
            shown = text[:5] if selector == "#code" else text
            return {"ok": True, "action": "type", "mode": "control_selector", "active_typable": True,
                    "active_has_value": True, "active_tag": "input", "active_value": shown, "active_selector": selector}

    body = _TwoCodesBody()
    _run_scripted(monkeypatch, body, [
        {"action": "type", "control": 1, "x": 220, "y": 120, "text": "555-123-4567",
         "grounding_source": "profile", "grounding_quote": "555-123-4567", "reason": "Enter the code twice.",
         "then": [
             {"action": "type", "control": 3, "x": 220, "y": 180, "text": "555-123-4567",
              "grounding_source": "profile", "grounding_quote": "555-123-4567"},
             {"action": "click", "control": 2, "x": 420, "y": 120, "text": ""},
         ]},
    ])
    assert ("#code", "555-123-4567") in body.type_control_calls
    # The truncated type is unverified, so the chain stops before the second type as well as the click.
    assert ("#code2", "555-123-4567") not in body.type_control_calls
    assert body.clicks == []


def test_the_type_read_back_rule_reads_long_and_sensitive_values_from_what_the_body_compared() -> None:
    # Closure review M1: active_value is capped at 500 characters, so a long cover letter never matched.
    letter = "Dear team, " + "x" * 800
    assert extension_run._type_read_back_matches(
        {"text": letter}, {"active_value": letter[:500], "active_value_ledger": letter}
    ) is True
    huge = "y" * 5000
    assert extension_run._type_read_back_matches(
        {"text": huge}, {"active_value": huge[:500], "active_value_ledger": huge[:4000], "active_value_length": 5000}
    ) is True
    # Review M3: a field whose maxlength cut the value at 4000 holds only a prefix, and is no match.
    assert extension_run._type_read_back_matches(
        {"text": huge}, {"active_value": huge[:500], "active_value_ledger": huge[:4000], "active_value_length": 4000}
    ) is False
    assert extension_run._type_read_back_matches({"text": huge}, {"active_value": huge[:500], "active_value_ledger": huge[:4000]}) is False
    assert extension_run._type_read_back_matches(
        {"text": huge}, {"active_value": "z" * 500, "active_value_ledger": "z" * 4000}
    ) is False
    # A password never leaves the page: the body's exact in-page comparison decides.
    assert extension_run._type_read_back_matches({"text": "s3cret!"}, {"active_value_redacted": True, "active_value_matches_expected": True}) is True
    assert extension_run._type_read_back_failed({"text": "s3cret!"}, {"active_value_redacted": True, "active_value_matches_expected": False}) is True
    assert extension_run._type_read_back_failed({"text": "s3cret!"}, {"active_value_redacted": True}) is False
    assert extension_run._type_read_back_failed({"text": "abc"}, {"ok": True}) is False


