def test_a_desktop_click_whose_focus_is_unknown_still_carries_its_chained_type(monkeypatch) -> None:
    # v3_intake: a Tk entry reports its focus as a plain Pane. Unknown focus is not "the click did not focus a
    # text field": the chained type runs and verifies its own read-back. Only a known non-text control ends it.
    init_db()
    monkeypatch.setattr(extension_run, "_call_secret_request_classifier", lambda *args, **kwargs: {
        "verdict": "ordinary", "confidence": 0.99, "reason": "Fixture.", "evidence": "Fixture.",
        "metadata": {"provider": "fixture", "model": "fixture", "normalization": "validated"}})
    monkeypatch.setattr(extension_run, "_call_credential_target_classifier", lambda *args, **kwargs: {
        "slot": "none", "usage": "none", "confidence": 0.99, "reason": "Fixture.", "evidence": "Fixture."})

    class _TkFormBody(_DesktopScreenBody):
        def __init__(self, typable: bool | None) -> None:
            super().__init__()
            self.typable = typable
            self.typed: list[str] = []

        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            shot["page_evidence"]["viewport_text"] = "Intake Terminal Phone"
            shot["page_evidence"]["controls"] = []
            return shot

        async def vision_click(self, x: int, y: int, **_kwargs: object) -> dict:
            self.clicks.append(("point", x, y))
            return {"ok": True, "action": "click", "surface_changed": True, "active_typable": self.typable,
                    "active_tag": "Pane", "desktop_surface": True}

        async def vision_type(self, text, *args, **kwargs) -> dict:
            self.typed.append(text)
            return {"ok": True, "action": "type", "active_typable": False, "active_has_value": False, "active_value": "",
                    "active_value_matches_expected": False, "value_read_back": False, "typed_where_caret_is": True,
                    "surface_changed": True, "desktop_surface": True}

    scripted = [
        {"action": "click", "control": 0, "x": 420, "y": 215, "reason": "Put the caret in the phone entry.",
         "then": [{"action": "type", "control": 0, "text": "555-123-4567",
                   "grounding_source": "profile", "grounding_quote": "555-123-4567"}]},
    ]
    unknown = _TkFormBody(None)
    contexts = _run_scripted(monkeypatch, unknown, scripted, max_steps=2)
    assert unknown.typed == ["555-123-4567"]
    assert not any("click_did_not_focus_typable" in str(item) for item in (contexts[-1].get("recent_actions") or []))

    button = _TkFormBody(False)
    contexts = _run_scripted(monkeypatch, button, scripted, max_steps=2)
    assert button.typed == []
    assert any("click_did_not_focus_typable" in str(item) for item in (contexts[-1].get("recent_actions") or []))


def test_type_feedback_shows_the_edited_line_and_a_secret_stays_on_keystrokes() -> None:
    action = {"action": "type", "text": "SL-826275", "at_caret": True}
    leftover = {"ok": True, "action": "type", "active_value": "Shipping manifest", "typed_at_caret": True,
                "active_value_matches_expected": False,
                "edited_line_before": "Seal number: ________", "edited_line_after": "Seal number: _SL-826275"}
    feedback = extension_run._type_value_mismatch_feedback(action, leftover)
    assert "'Seal number: ________'" in feedback and "'Seal number: _SL-826275'" in feedback
    assert "Shipping manifest" not in feedback, "the edited line, not the document's head"

    corrupted = {"ok": False, "action": "type", "failure_reason": "typed_text_corrupted",
                 "active_value_matches_expected": False,
                 "edited_line_before": "Seal number: ________", "edited_line_after": "Seal bbber:LLL-826275"}
    assert "'Seal bbber:LLL-826275'" in extension_run._type_value_mismatch_feedback(action, corrupted)
    extra = _vision_verification_extra("type", corrupted)
    assert extra["edited_line_after"] == "Seal bbber:LLL-826275"
    assert extra["failure_reason"] == "typed_text_corrupted"

    matched = {**leftover, "active_value_matches_expected": True, "edited_line_after": "Seal number: SL-826275"}
    assert extension_run._type_value_mismatch_feedback(action, matched) == ""
    # A match still shows the whole line, so a character left outside the selection is visible.
    assert "'Seal number: SL-826275'" in extension_run._vision_result_hint(matched)
    # A redacted (sensitive) result never shows a line.
    assert extension_run._type_value_mismatch_feedback(
        action, {"active_value_redacted": True, "active_value_matches_expected": False, "edited_line_after": "x"}
    ) == ""

    class _DesktopTyping:
        async def vision_type(self, text: str, *, at_caret: bool = False, sensitive: bool = False) -> dict:
            return {}

    class _PageTyping:
        async def vision_type(self, text: str, *, at_caret: bool = False) -> dict:
            return {}

    desktop_type = _DesktopTyping().vision_type
    assert extension_run._type_mode_kwargs(desktop_type, at_caret=True, sensitive=True) == {"at_caret": True, "sensitive": True}
    assert extension_run._type_mode_kwargs(desktop_type, at_caret=False, sensitive=False) == {}
    assert extension_run._type_mode_kwargs(_PageTyping().vision_type, at_caret=False, sensitive=True) == {}
    from app.desktop_body import DesktopBody

    # The native-thread wrapper keeps the real signature, so the run can see the desktop takes the flag.
    assert extension_run._type_mode_kwargs(DesktopBody().vision_type_control, at_caret=False, sensitive=True) == {
        "sensitive": True
    }


