def test_the_verifier_marker_is_a_ring_without_a_cross_inside() -> None:
    # The binding judge read a ring with a crosshair as Chrome's "+" New Tab button over the omnibox.
    import base64
    import io

    from PIL import Image

    out = io.BytesIO()
    Image.new("RGB", (100, 100), (255, 255, 255)).save(out, format="PNG")
    marked = extension_run._mark_point_on_image(
        {"media_type": "image/png", "data": base64.b64encode(out.getvalue()).decode("ascii")}, (50, 50)
    )
    image = Image.open(io.BytesIO(base64.b64decode(marked["data"]))).convert("RGB")
    assert image.getpixel((50, 50)) == (255, 255, 255)
    assert image.getpixel((61, 50)) != (255, 255, 255)


