def test_a_quiet_tab_after_a_type_leaves_no_field_standing_in_for_focus(monkeypatch) -> None:
    # Safety review M1: [type into #kb-a, Tab reported only as a selection change, Enter] judged the Enter
    # against #kb-a, which no longer held focus.
    init_db()

    class _QuietTabAfterTypeBody(_KeyboardConsoleBody):
        def __init__(self) -> None:
            super().__init__()
            self.keys: list[str] = []

        async def vision_key(self, key, *args, **kwargs) -> dict:
            self.keys.append(str(key))
            return {"ok": True, "action": "key", "key": str(key), "selection_changed": True, "selection_length": 3}

    body = _QuietTabAfterTypeBody()
    _run_scripted(monkeypatch, body, [
        {"action": "type", "control": 1, "text": "555-123-4567", "grounding_source": "profile",
         "grounding_quote": "555-123-4567", "reason": "Fill A.",
         "then": [{"action": "key", "key": "Tab"}, {"action": "key", "key": "Enter"}]},
    ], max_steps=1)
    assert body.type_control_calls[:1] == [("#kb-a", "555-123-4567")]
    assert [key.lower() for key in body.keys] == ["tab"]


def test_enter_does_not_ride_a_type_whose_field_reads_back_only_loosely(monkeypatch) -> None:
    # Safety review M2: alphanumerics-only equality read "555.123.4567" as the typed "555-123-4567".
    init_db()

    class _ReformattingFieldBody(_KeyboardConsoleBody):
        def __init__(self) -> None:
            super().__init__()
            self.keys: list[str] = []

        async def vision_type_control(self, selector: str, text: str, **_binding: object) -> dict:
            self.type_control_calls.append((selector, text))
            return {"ok": True, "action": "type", "mode": "control_selector", "active_typable": True,
                    "active_has_value": True, "active_tag": "input", "active_value": "555.123.4567",
                    "active_selector": selector, "surface_changed": True}

        async def vision_key(self, key, *args, **kwargs) -> dict:
            self.keys.append(str(key))
            return {"ok": True, "action": "key", "key": str(key)}

    body = _ReformattingFieldBody()
    _run_scripted(monkeypatch, body, [
        {"action": "type", "control": 1, "text": "555-123-4567", "grounding_source": "profile",
         "grounding_quote": "555-123-4567", "reason": "Search.", "then": [{"action": "key", "key": "Enter"}]},
    ], max_steps=1)
    assert body.keys == []


