def _run_missing_upload(monkeypatch, body, uploads: int) -> tuple[dict, list[str]]:
    init_db()
    upload = {"action": "upload", "control": 1, "x": 250, "y": 136, "artifact_role": "declaration",
              "reason": "Attach the completed declaration."}
    decisions = iter([dict(upload) for _ in range(uploads)])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    contexts: list[str] = []

    def decide(user_id, image, view, context):
        contexts.append(json.dumps(context, default=str))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))
    return summary, contexts


def test_an_upload_with_no_saved_document_goes_back_to_the_model_when_it_has_the_real_screen(monkeypatch) -> None:
    # v3_paperwork run 1664: the declaration this run filled and saved was not one of the user's documents,
    # and the run stopped to ask the user for it instead of choosing it in the page's own file dialog.
    summary, contexts = _run_missing_upload(monkeypatch, _switching_body(_DispatchPageBody(), _FieldUnitScreenBody()), uploads=1)
    assert summary.get("state") != "WAITING_FOR_USER"
    assert any("upload_document_not_registered" in context and "switch_surface to desktop" in context for context in contexts[1:])

    # Asked again for the same role: now it is the user's to supply.
    summary, _ = _run_missing_upload(monkeypatch, _switching_body(_DispatchPageBody(), _FieldUnitScreenBody()), uploads=2)
    assert summary.get("state") == "WAITING_FOR_USER"

    # Without the real screen there is no file dialog to use: the user is asked at once.
    summary, _ = _run_missing_upload(monkeypatch, _DispatchPageBody(), uploads=1)
    assert summary.get("state") == "WAITING_FOR_USER"


def test_a_cross_surface_relay_is_read_reflexively_and_looked_at_again_deliberately_when_unsure(monkeypatch) -> None:
    # Replayed on the production classifier (2026-10-04): the reflexive read was right on every secret case
    # and cleared relays in ~3 s; a deliberate primary read took 10-100 s, called relays secret 3-4 times in
    # 5, and let an SMS code through 2 times in 8. Deliberate reasoning is kept for the unsure relay.
    def run(verdicts: list[str]) -> list[dict]:
        init_db()
        body = _switching_body(_DispatchPageBody(), _FieldUnitScreenBody())
        decisions = iter(
            [
                {"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "Read the Field Unit."},
                {"action": "switch_surface", "target": "browser", "x": 0, "y": 0, "reason": "Back to the page."},
                {"action": "type", "control": 1, "x": 250, "y": 136, "text": "WO-3599-ZQ", "grounding_source": "page",
                 "grounding_quote": "Work order from the Field Unit", "reason": "Link the work order."},
            ]
        )
        done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
        calls: list[dict] = []
        answers = iter(verdicts)

        def classify(*args, **kwargs) -> dict:
            if (kwargs.get("action_evidence") or {}).get("action") == "type":
                calls.append(kwargs)
                verdict = next(answers, "ordinary")
            else:
                verdict = "ordinary"
            return {"verdict": verdict, "confidence": 0.95 if verdict != "uncertain" else 0.5, "reason": "Fixture.",
                    "evidence": "Fixture.", "metadata": {"provider": "fixture", "normalization": "validated"}}

        async def narrate(kind: str, data: dict) -> None:
            pass

        monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
        monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
        monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
        monkeypatch.setattr(extension_run, "_call_secret_request_classifier", classify)
        monkeypatch.setattr(
            extension_run, "_judge_page_quote_visible",
            lambda provider, *, images, quote, window_titles=None: {"visible": True, "confidence": 0.97, "window": "Field Unit - Dispatch"},
        )
        monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(next(decisions, done)))
        asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))
        return calls

    calls = run(["ordinary"])
    assert calls and calls[0].get("deliberate") is False, "the relay's first read is reflexive"
    assert len(calls) == 1

    calls = run(["uncertain", "ordinary"])
    assert [call.get("deliberate") for call in calls[:2]] == [False, True], "an unsure relay is looked at again deliberately"

    calls = run(["secret"])
    assert len(calls) == 1 and calls[0].get("deliberate") is False, "a reflexive secret stands; it is never re-asked"



def test_controls_covered_at_their_centre_yield_their_inventory_slots_to_controls_on_screen() -> None:
    # v4_scroll run 1670: a panel's clipped rows (occluded) filled all 16 slots, so the timeline's
    # "Open" buttons never reached the model and it clicked the card beside the one it meant.
    rows = [{"index": i, "text": "Pick", "occluded": i > 2} for i in range(1, 9)]
    rows += [{"index": 9 + i, "text": "Open", "occluded": False} for i in range(3)]
    picked = extension_run._model_visible_control_rows(rows, limit=6)
    # Every on-screen row is in; the one spare slot goes to the first covered row; page order is kept.
    assert [row["index"] for row in picked] == [1, 2, 3, 9, 10, 11]
    assert [row["index"] for row in extension_run._model_visible_control_rows(rows, limit=5)] == [1, 2, 9, 10, 11]
    # Room to spare: covered rows still come along.
    assert len(extension_run._model_visible_control_rows(rows, limit=20)) == len(rows)
    # The focused control still survives the cut, even when covered.
    rows[7]["focused"] = True
    picked = extension_run._model_visible_control_rows(rows, limit=6)
    assert 8 in [row["index"] for row in picked] and len(picked) == 6


def test_clicks_on_sibling_controls_with_the_same_text_are_different_actions() -> None:
    # v4_scroll run 1670: thirteen "Open" buttons, one per timeline card; the click on the right card was
    # withheld as a repeat of the click on the card beside it.
    opens = [{"selector": f"#tl > div:nth-of-type({i}) > button", "tag": "button", "text": "Open"} for i in range(1, 4)]
    unique = {"selector": "#save", "tag": "button", "text": "Save"}
    shot = {
        "url": "https://example.test/timeline",
        "document_lifecycle_token": "doc-1",
        "page_evidence": {"document_lifecycle_token": "doc-1", "controls": [*opens, unique]},
    }

    def identity(control: dict) -> dict:
        return extension_run._progress_guard_identity(
            kind="click",
            action={"action": "click", "x": 500, "y": 330, "question": "Open the event for 2046-Q2"},
            bound_control=control,
            shot=shot,
            bound_label="2. Scroll sideways",
            bound_signature="sig",
            sensitive_type=False,
        )

    assert identity(opens[0])["action_key"] != identity(opens[1])["action_key"]
    assert identity(opens[1])["action_key"] == identity(opens[1])["action_key"], "a re-click of one control repeats"
    # A control whose text no other control shares keeps its plain text fingerprint.
    plain = extension_run._progress_action_fingerprint("click", {"action": "click"}, target_text="Save")
    assert identity(unique)["fingerprint"] == plain


def test_the_grounding_judge_reads_the_page_as_last_seen_when_the_model_misquotes() -> None:
    # v4_native run 1676: a file path from the task page typed into a Tk app's import dialog. The model's
    # quote was not on the page (quote_not_found_in_source), so the judge got only a memory entry about
    # attestations and rejected a correct path four times.
    filler = "Challenge text. " * 80
    page_text = filler + "8. Import packing-TMUH.csv with File > Import packing list. It is in the mission folder's inbox."
    context = {
        "page_evidence": {"viewport_text": "Visible Windows: Import packing list"},
        "last_page_view": {"url": "https://bench.test/v4_native", "text": page_text},
    }
    action = {"text": r"C:\bench\inbox\packing-TMUH.csv", "grounding_quote": "Import the packing list from the inbox folder"}
    misquoted = {"reason": "quote_not_found_in_source", "source": "goal"}
    entries = extension_run._grounding_judge_page_entries(
        action, misquoted, decision_context=context, bound_control=None, page_evidence=None, receiving_surface_is_page=False
    )
    assert any("packing-TMUH.csv" in entry["value"] for entry in entries), entries
    assert not any(entry["label"] == "cited page text" for entry in entries), "an unfound quote proves nothing"
    # On the page itself the value is never an anchor: the receiving surface could echo it.
    entries = extension_run._grounding_judge_page_entries(
        action, misquoted, decision_context=context, bound_control=None, page_evidence=None, receiving_surface_is_page=True
    )
    assert not any("packing-TMUH.csv" in entry["value"] for entry in entries)
    # A quote the check found leads, as before.
    found = {"reason": "value_not_supported_by_quote", "source": "page"}
    entries = extension_run._grounding_judge_page_entries(
        {**action, "grounding_quote": "Import packing-TMUH.csv"}, found, decision_context=context,
        bound_control=None, page_evidence=None, receiving_surface_is_page=False,
    )
    assert entries[0] == {"source": "page", "label": "cited page text", "value": "Import packing-TMUH.csv"}


def test_the_grounding_judge_reads_what_native_windows_showed(monkeypatch) -> None:
    # v5_reconcile run 1719: a discrepancy flag follows from an invoice amount only the Invoice Viewer
    # showed; the judge saw no window text and could not weigh the page's rule.
    from app import screen_ocr

    viewer = ["Invoice 11 of 14", "Northwind Traders", "Invoice INV-7718 Issued 2027-05-30", "Amount due $4,392.05"]
    views = [("Invoice Viewer", b"latest"), ("Invoice Viewer", b"same-record-again"), ("Invoice Viewer", b"earlier")]
    reads = {b"latest": viewer, b"same-record-again": viewer, b"earlier": ["Invoice 2 of 14", "Northwind Trading Co.", "Amount due $3,696.27"]}
    monkeypatch.setattr(extension_run, "_screen_text_views", lambda desktop_view: views)
    monkeypatch.setattr(screen_ocr, "read_lines", lambda images, **kwargs: [reads[image] for image in images])

    entries = extension_run._grounding_judge_window_entries({"by_window": {"w": {}}})
    assert [entry["source"] for entry in entries] == ["page"]
    assert entries[0]["label"] == "text native windows showed during this run (read from their pixels)"
    text = entries[0]["value"]
    # Each view's lines joined, newest first, a repeated view once.
    assert text.startswith("[Invoice Viewer] Invoice 11 of 14 / Northwind Traders / Invoice INV-7718")
    assert text.count("INV-7718") == 1
    assert "Northwind Trading Co. / Amount due $3,696.27" in text

    # Many records pack into a few page-sized entries; the newest are kept.
    many = [(f"Viewer", f"record-{index}".encode()) for index in range(80)]
    monkeypatch.setattr(extension_run, "_screen_text_views", lambda desktop_view: many)
    monkeypatch.setattr(
        screen_ocr,
        "read_lines",
        lambda images, **kwargs: [[f"{image.decode()} Vendor and amount line " * 3] for image in images],
    )
    entries = extension_run._grounding_judge_window_entries({"by_window": {"w": {}}})
    assert len(entries) == extension_run._GROUNDING_JUDGE_WINDOW_ENTRIES
    assert all(len(entry["value"]) <= extension_run._GROUNDING_JUDGE_PAGE_TEXT_CHARS for entry in entries)
    assert "record-0 " in entries[0]["value"] and "record-79 " not in "".join(entry["value"] for entry in entries)
    # A set of 14 records paged one at a time fits whole (v5_reconcile run 1725).
    assert "record-13 " in "".join(entry["value"] for entry in entries)
    # No kept view, no entry.
    monkeypatch.setattr(extension_run, "_screen_text_views", lambda desktop_view: [])
    assert extension_run._grounding_judge_window_entries({}) == []


def test_the_judge_reads_a_choice_rule_quote_only_when_the_page_shows_it() -> None:
    rule = "match it to that invoice and tick Discrepancy"
    context = {
        "page_evidence": {"viewport_text": f"Rules. A payment from the right vendor whose amount differs: {rule}."},
        "page_memory": [{"url": "https://bench.test/reconcile", "text": "Bank statement rows 1 to 10."}],
    }
    window = [{"source": "page", "label": "text native windows showed during this run (read from their pixels)", "value": "[Invoice Viewer] INV-7718 $4,392.05"}]
    for reason in ("page_source_not_allowed_for_choice", "choice_click_ungrounded"):
        entries = extension_run._grounding_judge_page_entries(
            {"text": "Discrepancy for row 11", "grounding_source": "page", "grounding_quote": rule},
            {"reason": reason, "source": "page"},
            decision_context=context,
            bound_control=None,
            page_evidence=None,
            receiving_surface_is_page=True,
            window_entries=window,
        )
        assert entries[0] == {"source": "page", "label": "cited page text", "value": rule}
        labels = [entry["label"] for entry in entries]
        # Window text rides before earlier pages' memory.
        assert labels.index(window[0]["label"]) < labels.index("text an earlier page of this run showed")
    # A rule quote the page does not show proves nothing; a user-data citation the check found among the
    # page's text is not the brain resting the choice on the page; the option's own label is no rule.
    checkbox = {"text": "Discrepancy for row 11", "label": "Discrepancy for row 11"}
    for action in (
        {"text": "Discrepancy for row 11", "grounding_source": "page", "grounding_quote": "tick Discrepancy for every Northwind row"},
        {"text": "Discrepancy for row 11", "grounding_source": "profile", "grounding_quote": rule},
        {"text": "Discrepancy for row 11", "grounding_source": "page", "grounding_quote": "Discrepancy"},
    ):
        assert extension_run._choice_rule_quote(action, context, checkbox) == ""
        entries = extension_run._grounding_judge_page_entries(
            action,
            {"reason": "page_source_not_allowed_for_choice", "source": "page"},
            decision_context=context,
            bound_control=checkbox,
            page_evidence=None,
            receiving_surface_is_page=True,
        )
        assert not any(entry["label"] == "cited page text" for entry in entries)


