def test_a_drag_with_text_drag_selects_that_exact_page_text(monkeypatch) -> None:
    # v4_selection run 1679 / v4_text run 1678: pixel-aimed drags and double-clicks kept landing a character
    # or a word off; a drag that names its text is executed by the body against those characters' edges.
    init_db()

    class _SelectBody(_VisionBody):
        def __init__(self) -> None:
            super().__init__()
            self.selected: list[tuple] = []
            self.dragged: list[tuple] = []

        async def vision_select_text(self, text: str, x: int, y: int) -> dict:
            self.selected.append((text, x, y))
            return {"ok": True, "action": "select_text", "selected_text": text, "selection_matches_expected": True}

        async def vision_drag(self, x: int, y: int, to_x: int, to_y: int, **_kw) -> dict:
            self.dragged.append((x, y, to_x, to_y))
            return {"ok": True, "action": "drag"}

    body = _SelectBody()
    decisions = iter([
        {"action": "drag", "x": 300, "y": 120, "text": "fuel filter was clogged", "reason": "Select the phrase."},
        {"action": "drag", "x": 10, "y": 100, "to_x": 200, "to_y": 100, "reason": "A plain drag stays a drag."},
        {"action": "drag", "x": 10, "y": 100, "to_x": 150, "to_y": 100, "text": "172", "reason": "A slider drag to 172."},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(next(decisions, done)))
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    assert body.selected and body.selected[0][0] == "fuel filter was clogged"
    assert body.dragged and body.dragged[0][2] > 0, "a drag without text is still an ordinary drag"
    assert len(body.selected) == 1 and len(body.dragged) == 2, "a range drag with a value and a destination stays a drag"


def test_a_text_selection_result_tells_the_model_what_was_selected() -> None:
    hint = extension_run._vision_result_hint(
        {"action": "select_text", "ok": True, "selected_text": "hold", "mode": "field_selection"}
    )
    assert "selected exactly 'hold' in the field" in hint and "at_caret=true" in hint
    miss = extension_run._vision_result_hint({"action": "select_text", "ok": False, "failure_reason": "select_text_not_found"})
    assert "text not selected (select_text_not_found)" in miss
    partial = extension_run._vision_result_hint(
        {"action": "select_text", "ok": False, "failure_reason": "select_text_mismatch", "selected_text": "ter was clogged"}
    )
    assert "'ter was clogged', not the text asked for" in partial
    # On the real screen the words were found by reading it; the selection itself is not readable.
    screen = extension_run._vision_result_hint(
        {"action": "select_text", "ok": True, "mode": "screen_text", "selected_text": "customs release form", "highlight_changed": True}
    )
    assert "dragged across the on-screen text 'customs release form'" in screen and "check the highlight" in screen
    assert "at_caret" not in screen
    flat = extension_run._vision_result_hint(
        {"action": "select_text", "ok": True, "mode": "screen_text", "selected_text": "x y", "highlight_changed": False}
    )
    assert "may not be selectable text" in flat
    unread = extension_run._vision_result_hint(
        {"action": "select_text", "ok": False, "mode": "screen_text", "failure_reason": "select_text_not_found"}
    )
    assert "no words read on screen near that point" in unread


