    desktop.vision_drag = vision_drag
    body = _switching_body(_VisionBody(), desktop)
    decisions = iter([
        {"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "The note is a native window."},
        {"action": "drag", "x": 300, "y": 200, "text": "customs release form", "reason": "Select the phrase."},
    ])
