def test_a_second_zoom_keeps_the_first_crop_until_the_screen_may_change(monkeypatch) -> None:
    # v4_scroll run 1700: the brain alternated zooms of an overview and a map ten times; each crop
    # reached one decision only. Two zooms of an unchanged screen now ride together; any other
    # action drops them.
    import base64
    import io as _io

    from PIL import Image as _Image

    init_db()
    canvas = _Image.new("RGB", (800, 600), (240, 240, 240))
    canvas.paste((200, 30, 30), (40, 40, 160, 120))
    canvas.paste((30, 30, 200), (420, 380, 560, 470))
    buffer = _io.BytesIO()
    canvas.save(buffer, format="JPEG", quality=92)
    jpeg = base64.b64encode(buffer.getvalue()).decode("ascii")

    class _ZoomBody(_VisionBody):
        def __init__(self) -> None:
            super().__init__()
            self.keys: list[str] = []

        async def capture_screenshot(self) -> dict:
            shot = await super().capture_screenshot()
            shot["image"] = jpeg
            return shot

        async def vision_key(self, key: str, **_kw) -> dict:
            self.keys.append(key)
            return {"ok": True, "action": "key", "key": key}

    body = _ZoomBody()
    decisions = iter([
        {"action": "zoom", "x": 30, "y": 30, "to_x": 180, "to_y": 140, "reason": "Read the overview."},
        {"action": "zoom", "x": 400, "y": 360, "to_x": 580, "to_y": 490, "reason": "Read the map."},
        {"action": "key", "key": "Tab", "reason": "Move on."},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    seen: list[tuple[int, dict | None]] = []

    def decide(user_id, image, view, context):
        images = image if isinstance(image, list) else [image]
        seen.append((len(images), context.get("zoom_view")))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=6))

    assert body.keys == ["Tab"]
    assert [count for count, _ in seen[:4]] == [1, 2, 3, 1]
    assert seen[0][1] is None
    assert seen[1][1]["region"] == [30, 30, 180, 140] and "earlier_crops" not in seen[1][1]
    # The newest crop is the SECOND image; the one before it, the THIRD.
    assert seen[2][1]["region"] == [400, 360, 580, 490]
    assert [crop["image"] for crop in seen[2][1]["earlier_crops"]] == [3]
    assert seen[2][1]["earlier_crops"][0]["region"] == [30, 30, 180, 140]
    assert seen[3][1] is None, "a key press may change the screen: the crops are gone"


