def test_a_briefing_past_the_first_900_characters_is_remembered_once_it_is_gone() -> None:
    # v5_memory run 1704: the snapshot kept only 900 characters, the page header took the first 340,
    # and the departed briefing ended at "Your call sign" without the call sign.
    header = "Dispatch shift Challenges complete: 0 / 5 Benchmark in progress. " + "Read the briefing first. " * 12
    rules = " ".join(f"Rule {index}: route sector {index} to depot {index}." for index in range(1, 20))
    briefing = f"{header} {rules} Your call sign for this shift Heron-6 Begin field work"
    assert len(briefing) > 1100
    entry = extension_run._vision_page_memory_entry({"url": "https://bench.test/memory", "page_evidence": {"viewport_text": briefing}})
    assert entry["text"].endswith("Heron-6 Begin field work")
    after = f"{header} Field work Unlock the Field Terminal. Debrief: What was your call sign?"
    departed = extension_run._departed_page_memory([entry], after)
    assert len(departed) == 1 and "Heron-6" in departed[0]["text"] and "Rule 19" in departed[0]["text"]
    assert "Benchmark in progress" not in departed[0]["text"], "text still on the page is not repeated"
    budget = extension_run._VISION_NORMAL_CONTEXT_BUDGET["page_memory_text"]
    assert len(departed[0]["text"]) <= budget, "the departed briefing fits the prompt whole"


