def test_a_zoom_region_digest_sees_a_small_change_inside_the_region_only() -> None:
    # An earlier zoom crop rides along only while its own region is unchanged (safety review round 6:
    # the page-wide digest misses a small painted counter, and the crop feeds the visual quote check).
    import base64
    import io as _io

    from PIL import Image as _Image, ImageDraw as _Draw

    def shot(counter: str) -> dict:
        image = _Image.new("RGB", (400, 300), "white")
        draw = _Draw.Draw(image)
        draw.text((40, 40), f"Count {counter}", fill="black")
        draw.text((260, 240), "footer", fill="black")
        buffer = _io.BytesIO()
        image.save(buffer, format="JPEG", quality=85)
        return {"image": base64.b64encode(buffer.getvalue()).decode("ascii")}

    region = [30, 30, 130, 60]
    digest = extension_run._zoom_region_digest
    assert digest(shot("7"), region) == digest(shot("7"), region) != ""
    assert digest(shot("7"), region) != digest(shot("8"), region), "a changed digit in the region is a change"
    assert digest(shot("7"), [250, 230, 330, 260]) == digest(shot("8"), [250, 230, 330, 260]), "outside it is not"
    assert digest(shot("7"), [10, 10, 10, 50]) == "" and digest({}, region) == ""


def test_the_front_window_at_its_own_scale_tells_a_small_change_apart() -> None:
    # v5_reconcile run 1706: the next invoice in a 600 px viewer moved no cell of the whole-screen
    # thumbnail, so each Prev click read as the same state and was withheld as a repeat.
    import base64
    import io as _io

    from PIL import Image as _Image, ImageDraw as _Draw

    def shot(invoice: int, *, window: bool = True) -> dict:
        image = _Image.new("RGB", (1920, 1200), (30, 30, 30))
        draw = _Draw.Draw(image)
        draw.rectangle((1200, 100, 1800, 600), fill="white")
        draw.text((1250, 150), f"Invoice {invoice} of 14  INV-{3000 + invoice}  $1,0{invoice}5.71", fill="black")
        buffer = _io.BytesIO()
        image.save(buffer, format="JPEG", quality=78)
        windows = [{"active": True, "image_box": [1200, 100, 600, 500]}] if window else []
        return {"image": base64.b64encode(buffer.getvalue()).decode("ascii"), "page_evidence": {"windows": windows}}

    digest = extension_run._desktop_visual_digest
    assert digest(shot(9)) == digest(shot(9)), "the same screen is the same state"
    assert digest(shot(9)) != digest(shot(8)), "the next invoice is a new state"
    assert digest(shot(9, window=False)) == digest(shot(8, window=False)), "the whole-screen thumbnail alone misses it"


def test_the_brain_keeps_working_notes_that_come_back_on_later_steps(monkeypatch) -> None:
    # v5_reconcile run 1706: the brain paged through 14 invoices one at a time and lost what the earlier
    # ones said; it paged back to re-read them until the cycle guard stopped the run.
    from app import model_provider, vision_agent as _vision_agent

    schema = _vision_agent.action_schema()["schema"]
    assert "notes" in schema["properties"] and "notes" in schema["required"]
    long_note = "INV-2481 Meridian $778.22 " * 120
    assert len(_vision_agent.normalize_action({"action": "wait", "wait_ms": 500, "notes": long_note, "reason": "r"})["notes"]) == _vision_agent.NOTES_PER_DECISION_CHARS
    assert "your_notes" in model_provider.PAGE_RENDERED_PROMPT_KEYS, "codes the brain saw are not scrubbed from its own memory"

    init_db()
    body = _VisionBody()
    decisions = iter([
        {"action": "wait", "wait_ms": 200, "notes": "invoice 1: Meridian INV-2481 $778.22", "reason": "Read invoice 1."},
        {"action": "wait", "wait_ms": 200, "notes": "invoice 2: Ironbridge INV-2652 $5,334.58", "reason": "Read invoice 2."},
        {"action": "wait", "wait_ms": 200, "notes": "invoice 2: Ironbridge INV-2652 $5,334.58", "reason": "Same note again."},
    ])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}
    seen: list[list[str]] = []

    def decide(user_id, image, view, context):
        seen.append(list(context.get("your_notes") or []))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    async def vision_wait(wait_ms: int, **_kw) -> dict:
        return {"ok": True, "action": "wait", "waited_ms": wait_ms}

    body.vision_wait = vision_wait
    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=6))

    assert seen[0] == []
    assert seen[1] == ["step 1: invoice 1: Meridian INV-2481 $778.22"]
    assert seen[3] == ["step 1: invoice 1: Meridian INV-2481 $778.22", "step 2: invoice 2: Ironbridge INV-2652 $5,334.58"], (
        "a repeated note is not kept twice"
    )


def test_the_brain_plan_is_one_replaceable_checklist() -> None:
    from app import model_provider, vision_agent as _vision_agent

    schema = _vision_agent.action_schema()["schema"]
    assert "plan" in schema["properties"] and "plan" in schema["required"]
    normalized = _vision_agent.normalize_action({
        "action": "wait", "wait_ms": 500, "reason": "r",
        "plan": "[done] unlock\n\n  [ ]   request 4:  approve \n[ ] debrief",
    })
    assert normalized["plan"] == "[done] unlock\n[ ] request 4: approve\n[ ] debrief"
    assert _vision_agent.normalize_action({"action": "wait", "wait_ms": 500, "reason": "r", "plan": ["[ ] a", "", "[ ] b"]})["plan"] == "[ ] a\n[ ] b"
    assert len(_vision_agent.normalize_action({"action": "wait", "wait_ms": 500, "reason": "r", "plan": "x" * 5000})["plan"]) == _vision_agent.PLAN_MAX_CHARS
