def test_a_desktop_wait_for_text_reaches_a_body_that_takes_text_and_no_other(monkeypatch) -> None:
    # The desktop wait used to drop its text and sleep; it now reads the front window (Windows, and the
    # OSWorld VM). A body whose wait takes no text parameter (only **_) gets a plain pause, never a silently
    # dropped condition.
    import inspect as _inspect

    from app.agent_eval.osworld.body import OSWorldBody
    from app.desktop_body import DesktopBody

    class _PauseOnly:
        async def vision_wait(self, wait_ms: int, **_: object) -> dict:
            return {"ok": True}

    assert "text" in _inspect.signature(DesktopBody.vision_wait).parameters
    assert "text" in _inspect.signature(OSWorldBody.vision_wait).parameters
    assert "text" not in _inspect.signature(_PauseOnly.vision_wait).parameters


def test_run_command_output_reaches_the_next_decision_and_a_body_without_it_refuses(monkeypatch) -> None:
    init_db()
    calls: list[tuple[str, dict]] = []

    class _CommandBody(_VisionBody):
        async def vision_run_command(self, command: str, **kwargs) -> dict:
            calls.append((command, kwargs))
            return {"ok": True, "action": "run_command", "exit_code": 0, "stdout": "42", "stderr": "", "sandbox": "wsl"}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    for body, expect_output in ((_CommandBody(), True), (_VisionBody(), False)):
        seen: list[dict] = []
        decisions = iter([{"action": "run_command", "text": "echo $((6*7))", "wait_ms": 5000, "reason": "Compute."}])

        def decide(_user_id, _image, _view, context):
            seen.append(context)
            return dict(next(decisions, {"action": "wait", "wait_ms": 200, "reason": "Pause."}))

        monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
        asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=2))
        if expect_output:
            assert calls == [("echo $((6*7))", {"timeout_seconds": 5, "run_id": 0})]
            assert seen[1]["last_command"]["stdout"] == "42" and seen[1]["last_command"]["exit_code"] == 0
            assert any("run_command exit=0" in line for line in seen[1]["recent_actions"])
        else:
            assert any("run_command_unavailable" in line for line in seen[1]["recent_actions"])
            assert seen[1]["last_command"]["failure_reason"] == "run_command_unavailable"


def test_the_command_sandbox_refuses_to_run_unproven_and_caps_output(monkeypatch) -> None:
    from app import command_sandbox

    monkeypatch.setattr(command_sandbox, "_PROBE_RESULT", None)
    launched: list[str] = []

    def fake_launch(command, *, scratch, timeout_seconds):
        launched.append(scratch)
        if scratch == "probe":
            return {"ok": True, "stdout": "PASS drives_hidden" + chr(10) + "PASS no_network"}
        return {"ok": True, "exit_code": 0, "stdout": "x"}

    monkeypatch.setattr(command_sandbox, "_launch", fake_launch)
    refused = command_sandbox.run("ls", run_id=7)
    assert refused["ok"] is False and refused["failure_reason"] == "sandbox_unavailable"
    assert "overlays_locked" in refused["failed_checks"] and launched == ["probe"], "nothing ran unsandboxed"
    assert command_sandbox.run("", run_id=7)["failure_reason"] == "command_empty"
    assert command_sandbox.run("x" * (command_sandbox.COMMAND_CHARS + 1), run_id=7)["failure_reason"] == "command_too_long"

    all_pass = chr(10).join(f"PASS {check}" for check in command_sandbox._PROBE_CHECKS)
    monkeypatch.setattr(command_sandbox, "_launch", lambda command, *, scratch, timeout_seconds: {"ok": True, "stdout": all_pass} if scratch == "probe" else {"ok": True, "exit_code": 0, "stdout": "y", "scratch": scratch, "limit": timeout_seconds})
    ran = command_sandbox.run("ls", run_id="9; rm -rf /", timeout_seconds=500)
    assert ran["ok"] and ran["scratch"] == "run-9rm-rf" and ran["limit"] == command_sandbox.MAX_TIMEOUT_SECONDS
    assert command_sandbox._cap("z" * 5000) == ("z" * command_sandbox.OUTPUT_CHARS, True)
    # The launcher never writes into scratch from outside the sandbox (a symlink a command planted there would
    # redirect that write with the WSL user's rights): the command flows on stdin to the innermost bash -s.
    launcher = command_sandbox._LAUNCHER
    assert "cat >" not in launcher and "/bin/bash -s" in launcher and "chmod 777" not in launcher
    assert "MemoryMax=" in launcher and "TasksMax=" in launcher and "head -c" in launcher
    assert command_sandbox._scratch_name(None).startswith("run-adhoc-") and command_sandbox._scratch_name(None) != command_sandbox._scratch_name(None)


