def test_what_a_window_showed_earlier_stays_readable_for_screen_text_proof() -> None:
    # v5_reconcile: invoices are paged one at a time in a native viewer; a number read on invoice 3 must
    # still be provable after the viewer shows invoice 4. Only the latest view goes to the visual judges.
    import base64
    import io as _io

    from PIL import Image as _Image, ImageDraw as _Draw

    def view(invoice: int) -> dict:
        image = _Image.new("RGB", (800, 600), "white")
        _Draw.Draw(image).text((60, 60), f"Invoice {invoice} INV-{3170 + invoice}", fill="black")
        buffer = _io.BytesIO()
        image.save(buffer, format="PNG")
        return {"media_type": "image/png", "data": base64.b64encode(buffer.getvalue()).decode("ascii")}

    window = {"window_id": "hwnd:7", "title": "Invoice Viewer", "active": True}
    front = {"title": "Invoice Viewer", "image_box": [0, 0, 800, 600], "drawn_over": []}
    memory: dict = {}
    for invoice in (3, 4, 4, 5):
        extension_run._remember_desktop_view(memory, view(invoice), [window], foreground_window=front)

    assert memory["images"] == [view(5)], "the visual judges still see only the latest view"
    assert len(memory["history"]) == 2, "invoices 3 and 4 kept once each"
    views = extension_run._screen_text_views(memory)
    assert len(views) == 3 and all(title == "Invoice Viewer" for title, _ in views)
    newest, *earlier = [png for _, png in views]
    assert _Image.open(_io.BytesIO(newest)).size == (800, 600)
    # Cap: only the most recent earlier views are kept.
    for invoice in range(6, 6 + extension_run._DESKTOP_VIEW_HISTORY + 4):
        extension_run._remember_desktop_view(memory, view(invoice), [window], foreground_window=front)
    assert len(memory["history"]) == extension_run._DESKTOP_VIEW_HISTORY


