def test_repeat_views_of_one_record_are_kept_once_whatever_else_the_screen_shows() -> None:
    # v5_reconcile run 1710: the taskbar clock made every capture differ, repeats of the last few
    # invoices filled the history, and the earlier invoices were lost to screen-text proof.
    import base64
    import io as _io

    from PIL import Image as _Image, ImageDraw as _Draw

    def capture(invoice: int, clock: str) -> dict:
        image = _Image.new("RGB", (1000, 700), (40, 40, 40))
        draw = _Draw.Draw(image)
        draw.rectangle((100, 100, 600, 400), fill="white")
        draw.text((140, 140), f"Invoice {invoice} INV-{2700 + invoice}", fill="black")
        draw.text((900, 680), clock, fill="white")  # the taskbar clock, outside the window
        buffer = _io.BytesIO()
        image.save(buffer, format="JPEG", quality=80)
        return {"media_type": "image/jpeg", "data": base64.b64encode(buffer.getvalue()).decode("ascii")}

    window = {"window_id": "hwnd:9", "title": "Invoice Viewer", "active": True}
    front = {"title": "Invoice Viewer", "image_box": [100, 100, 500, 300], "drawn_over": []}
    memory: dict = {}
    sequence = [(5, "8:21"), (5, "8:22"), (5, "8:23"), (6, "8:24"), (6, "8:25"), (7, "8:26")]
    for invoice, clock in sequence:
        extension_run._remember_desktop_view(memory, capture(invoice, clock), [window], foreground_window=front)
    assert len(memory["history"]) == 2, "invoices 5 and 6 once each, however the clock changed"


def test_the_final_action_verifier_reads_a_native_windows_own_text(monkeypatch) -> None:
    # v5_memory runs 1704/1711: a Tk terminal shows "Approved and dispatched." only in pixels; the verifier
    # compared identical control trees and called every submit uncertain.
    import base64
    import io as _io

    from PIL import Image as _Image

    from app import screen_ocr
    from app.lumen_model import LumenModelClient

    buffer = _io.BytesIO()
    _Image.new("RGB", (1200, 800), "white").save(buffer, format="JPEG")
    image = base64.b64encode(buffer.getvalue()).decode("ascii")

    def desktop_shot(status: str, overlaps: list | None = None) -> dict:
        overlaps = [] if overlaps is None else overlaps
        return {
            "url": "desktop://windows/hwnd:5",
            "title": "Field Terminal",
            "image": image,
            "_status": status,
            "page_evidence": {
                "execution_surface": "desktop",
                "windows": [
                    {"window_id": "hwnd:5", "title": "Field Terminal", "active": True, "image_box": [500, 80, 560, 500], "drawn_over": overlaps}
                ],
            },
        }

    def reading(*texts: str) -> list:
        return [{"text": text, "words": [{"t": text, "x": 10, "y": 10 + 20 * index, "w": 100, "h": 14}]} for index, text in enumerate(texts)]

    statuses = iter([reading("Request REQ-1366 (1 of 10)", "Choose Approve or Deny."), reading("Request REQ-2001 (2 of 10)", "Approved and dispatched.")])
    monkeypatch.setattr(screen_ocr, "read_text_lines", lambda images, **kwargs: [next(statuses)])
    captured: dict = {}

    def verify(self, payload, *, image=None):
        captured.update(payload)
        return {"status": "succeeded", "confidence": 0.9, "evidence": "status line"}

    monkeypatch.setattr(LumenModelClient, "verify_final_action_outcome", verify)
    extension_run._final_action_outcome_verdict(
        0, goal="Work the shift", pending={"label": "Submit"}, before_shot=desktop_shot("before"), result={"ok": True}, post_shot=desktop_shot("after")
    )
    assert captured["before"]["window_text"] == ["Request REQ-1366 (1 of 10)", "Choose Approve or Deny."]
    assert captured["after"]["window_text"] == ["Request REQ-2001 (2 of 10)", "Approved and dispatched."]
    # A web page has its own text; no window reading is added.
    web = {"url": "https://example.test", "image": image, "page_evidence": {"execution_surface": "browser"}}
    assert extension_run._front_window_text_entry(web) == {}
    # Another window drawn over the front one (a toast saying "Approved") is blacked out, never read as the
    # front window's own text; unknown stacking reads nothing.
    read: list[bytes] = []
    monkeypatch.setattr(screen_ocr, "read_text_lines", lambda images, **kwargs: read.extend(images) or [reading("Field Terminal")])
    extension_run._front_window_text_entry(desktop_shot("after", [[900, 100, 120, 60]]))
    with _Image.open(_io.BytesIO(read[-1])) as crop:
        assert crop.size == (560, 500)
        assert crop.getpixel((400 + 10, 20 + 10)) == (0, 0, 0)
        assert crop.getpixel((10, 10)) != (0, 0, 0)
    assert extension_run._front_window_text_entry(desktop_shot("after", [[-1, -1, 0, 0]])) == {}


def _front_window_shot(image_box: list, *, size: tuple = (2240, 1260), drawn_over: list | None = None) -> dict:
    import io as _io

    from PIL import Image as _Image

    buffer = _io.BytesIO()
    _Image.new("RGB", size, "white").save(buffer, format="JPEG")
    return {
        "ok": True, "image": base64.b64encode(buffer.getvalue()).decode("ascii"), "width": size[0], "height": size[1],
        "url": "desktop://windows/hwnd:5", "title": "Field Terminal", "scroll_y": 0, "scroll_height": size[1],
        "page_evidence": {
            "execution_surface": "desktop",
            "viewport_text": "",
            "controls": [],
            "windows": [{"window_id": "hwnd:5", "title": "Field Terminal", "active": True, "image_box": image_box, "drawn_over": drawn_over or []}],
        },
    }


def _ocr_line(text: str, *words: tuple) -> dict:
    return {"text": text, "words": [{"t": t, "x": x, "y": y, "w": w, "h": h} for t, x, y, w, h in words]}


def test_front_window_text_boxes_are_where_the_text_is_drawn_in_the_models_screenshot(monkeypatch) -> None:
    # v5_memory run 1721 read "Submit" in front_window_text and missed the button five times aiming by eye.
    # A word the OCR found at (40, 300) of the window crop sits at the window's origin plus that in the capture,
    # and the model's screenshot is the capture divided by coord_scale, as control boxes are projected.
    from app import screen_ocr

    reads: list[int] = []
    first = [_ocr_line("Request REQ-1290", ("Request", 20, 10, 70, 14), ("REQ-1290", 96, 10, 80, 14))]
    # The highlight-recolored reading (same size as the crop) adds a line the first missed; a repeat is dropped.
    second = [_ocr_line("request req-1290", ("request", 20, 10, 70, 14)), _ocr_line("Route B", ("Route", 40, 60, 50, 14), ("B", 94, 60, 10, 14))]

    def read_text_lines(images, **_kw):
        reads.append(len(images))
        return [first, second][: len(images)]

    monkeypatch.setattr(screen_ocr, "read_text_lines", read_text_lines)
    monkeypatch.setattr(extension_run, "_highlights_inverted_png", lambda png: b"recolored")
    lines = extension_run._front_window_text_lines(_front_window_shot([500, 80, 560, 500]))
    assert reads == [2], "one OCR process reads the crop and its recolored view"
    assert [line["text"] for line in lines] == ["Request REQ-1290", "Route B"]
    assert lines[0]["words"][1] == {"t": "REQ-1290", "x": 596.0, "y": 90.0, "w": 80.0, "h": 14.0}
    assert lines[1]["words"][0]["x"] == 540.0 and lines[1]["words"][0]["y"] == 140.0
    # coord_scale 2: capture (520..676, 90..104) -> model (260..338, 45..52).
    assert extension_run._front_window_text_for_model(lines, 2.0) == ["[260,45,78,7] Request REQ-1290", "[270,70,32,7] Route B"]
    assert extension_run._front_window_text_entry(_front_window_shot([500, 80, 560, 500])) == {"window_text": ["Request REQ-1290", "Route B"]}
    # A window hanging off the screen's left/top edge is cut at the capture's edge: the crop starts at 0.
    lines = extension_run._front_window_text_lines(_front_window_shot([-8, -8, 400, 300]))
    assert lines[0]["words"][0]["x"] == 20.0 and lines[0]["words"][0]["y"] == 10.0
    # Not the desktop, or a browser page's window: nothing is read.
    browser = _front_window_shot([500, 80, 560, 500])
    browser["page_evidence"]["execution_surface"] = "browser"
    assert extension_run._front_window_text_lines(browser) == []


def test_front_window_text_splits_a_line_whose_words_stand_apart_and_keeps_its_budget() -> None:
    # Two buttons on one row read as one OCR line "Cancel Submit": one box around both would center between them.
    row = _ocr_line("Cancel Submit", ("Cancel", 100, 400, 52, 14), ("Submit", 190, 400, 50, 14))
    phrase = _ocr_line("Choose Approve or Deny.", ("Choose", 100, 300, 56, 14), ("Approve", 160, 300, 64, 14), ("or", 228, 300, 14, 14), ("Deny.", 246, 300, 42, 14))
    assert extension_run._front_window_text_for_model([phrase, row], 1.0) == [
        "[100,300,188,14] Choose Approve or Deny.",
        "[100,400,52,14] Cancel",
        "[190,400,50,14] Submit",
    ]
    many = [_ocr_line(f"Line {index} " + "x" * 300, (f"Line{index}", 10, 20 * index, 400, 14)) for index in range(60)]
    shown = extension_run._front_window_text_for_model(many, 1.0)
    assert len(shown) == 40
    assert all(len(entry.split("] ", 1)[1]) <= 140 for entry in shown)
    # A bad scale reads as 1; widths and heights never collapse to 0.
    assert extension_run._front_window_text_for_model([_ocr_line("i", ("i", 7, 7, 1, 1))], 0) == ["[7,7,1,1] i"]
    assert extension_run._front_window_text_for_model([_ocr_line("i", ("i", 7, 7, 1, 1))], 4.0) == ["[2,2,1,1] i"]


def test_the_brain_gets_front_window_text_boxes_in_its_own_screenshot_pixels(monkeypatch) -> None:
    from app import screen_ocr

    init_db()
    # A 2240-wide capture is sent at 1120: coord_scale 2.
    shot = _front_window_shot([400, 200, 800, 600])

    class _TkScreen(_DesktopScreenBody):
        async def capture_screenshot(self) -> dict:
            return json.loads(json.dumps(shot))

    monkeypatch.setattr(
        screen_ocr,
        "read_text_lines",
        lambda images, **_kw: [[_ocr_line("Submit", ("Submit", 300, 500, 60, 20))]] + [[] for _ in images[1:]],
    )
    seen: list = []
    decisions = iter([{"action": "switch_surface", "target": "desktop", "x": 0, "y": 0, "reason": "The terminal is a native window."}])
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    def decide(user_id, image, view, context):
        seen.append((context.get("execution_surface"), context.get("front_window_text")))
        return dict(next(decisions, done))

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    body = _switching_body(_VisionBody(), _TkScreen())
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=3))
    desktop_steps = [text for surface, text in seen if surface == "desktop"]
    # Crop (300, 500) + window origin (400, 200) = capture (700, 700); / 2 = model (350, 350).
    assert desktop_steps and desktop_steps[0] == ["[350,350,30,10] Submit"]
    assert seen[0][1] is None, "the browser surface gets no window reading"


