def test_the_secret_gate_reads_a_short_number_by_its_shape_never_as_dictated_by_a_url() -> None:
    # v5_switchboard run 1739: a one-digit Billing count was "verbatim from the user's goal" (the goal names
    # 127.0.0.1:53557) and was then judged a secret at full confidence.
    goal = "Work the shift at http://127.0.0.1:53557/eval/bench/v5_switchboard and file the report."
    evidence = extension_run._secret_classifier_action_evidence({"action": "type", "text": "2"}, goal_text=goal)
    assert evidence["typed_text_verbatim_from_user_goal"] is False
    assert evidence["text_character_classes"] == "digits only"
    # A whole token the user wrote still counts; a piece of a longer token does not.
    assert extension_run._secret_classifier_action_evidence({"action": "type", "text": "the shift"}, goal_text=goal)["typed_text_verbatim_from_user_goal"] is True
    assert extension_run._secret_classifier_action_evidence({"action": "type", "text": "553"}, goal_text=goal)["typed_text_verbatim_from_user_goal"] is False
    assert extension_run._secret_classifier_action_evidence({"action": "type", "text": "AC-72794"}, goal_text=goal)["text_character_classes"] == "letters, digits, and symbols"


def _auto_mode_ask(monkeypatch, *, user_only: bool, mode: str = "autonomous") -> tuple[dict, list[dict], list]:
    init_db()
    contexts: list[dict] = []
    judged: list[dict] = []
    ask = {"action": "ask_user", "question": "Which of the two shift totals should I report?", "options": [], "reason": "Unsure."}

    def decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        contexts.append(context)
        if len(contexts) == 1:
            return dict(ask)
        return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Decided."}

    def judge(user_id: int, **kwargs) -> dict:
        judged.append(kwargs)
        return {"user_only": user_only, "reason": "fixture"}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_final_action_mode_for_run", lambda run_id, user_id: mode)
    monkeypatch.setattr(extension_run, "_call_user_only_question_judge", judge)
    monkeypatch.setattr(
        extension_run,
        "_call_secret_request_classifier",
        lambda *args, **kwargs: {"verdict": "ordinary", "confidence": 0.99, "reason": "A plain question.", "evidence": "", "metadata": {}},
    )
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    summary = asyncio.run(
        run_vision_loop(_ChoiceBody(), url=None, narrate=lambda *a, **k: asyncio.sleep(0), run_id=0, user_id=0, skip_navigate=True, max_steps=4)
    )
    return summary, contexts, judged


def test_auto_mode_hands_a_question_it_can_decide_back_to_the_brain(monkeypatch) -> None:
    # Owner policy 2026-10-06: in auto mode the user is asked only for facts about them nothing holds.
    summary, contexts, judged = _auto_mode_ask(monkeypatch, user_only=False)
    assert judged and judged[0]["question"].startswith("Which of the two shift totals")
    assert len(contexts) >= 2
    assert any("auto_mode_decide_yourself" in item for item in contexts[1]["recent_actions"])
    assert summary["state"] != "WAITING_FOR_USER"


def test_auto_mode_still_asks_for_a_fact_only_the_user_knows_and_approval_mode_never_judges(monkeypatch) -> None:
    summary, contexts, judged = _auto_mode_ask(monkeypatch, user_only=True)
    assert judged
    # A fact only the user knows takes the ordinary ask path: never handed back to the brain.
    assert not any("auto_mode_decide_yourself" in item for context in contexts for item in context.get("recent_actions") or [])
    summary, contexts, judged = _auto_mode_ask(monkeypatch, user_only=False, mode="approval")
    assert judged == []
    assert not any("auto_mode_decide_yourself" in item for context in contexts for item in context.get("recent_actions") or [])


def test_a_resumed_run_keeps_the_window_views_it_saw(monkeypatch, tmp_path) -> None:
    # v5_switchboard run 1739 resumed after a double model timeout blind to the account number a line window
    # had shown: the kept views lived only in the process.
    import base64 as _b64
    import io as _io

    from PIL import Image as _Image

    monkeypatch.setattr(extension_run, "get_settings", lambda: type("S", (), {"artifact_root": tmp_path})())
    buffer = _io.BytesIO()
    _Image.new("RGB", (40, 30), "white").save(buffer, format="PNG")
    png = buffer.getvalue()
    memory = {
        "by_window": {"hwnd:7": {"media_type": "image/png", "data": _b64.b64encode(png).decode("ascii")}},
        "meta": {"hwnd:7": {"title": "Line 3", "image_box": [0, 0, 40, 30], "drawn_over": [], "browser_content": False}},
        "history": [{"png": png, "meta": {"title": "Line 3"}, "digest": "abc"}],
        "titles": ["Line 3"],
    }
    extension_run._persist_desktop_view_memory(42, memory)
    restored = extension_run._load_desktop_view_memory(42)
    assert restored["by_window"] == memory["by_window"]
    assert restored["meta"]["hwnd:7"]["title"] == "Line 3"
    assert restored["history"][0]["png"] == png
    assert restored["image"] == memory["by_window"]["hwnd:7"]
    # Nothing kept, nothing restored; no run, no file.
    assert extension_run._load_desktop_view_memory(43) == {}
    extension_run._persist_desktop_view_memory(0, memory)
    assert extension_run._load_desktop_view_memory(0) == {}


