def test_an_unquoted_choice_rests_only_on_an_instruction_the_task_shows() -> None:
    # Review of 5a8701b: with no rule the brain quoted, an option must never ground itself (its own label, a
    # pre-selected default, a promotion). The judge's own quote must be an instruction the screen shows.
    from app.lumen_model import GROUNDING_WINDOW_TEXT_LABEL

    holds = extension_run._unquoted_choice_support_holds
    screen = {
        "source": "page",
        "label": "text currently on screen",
        "value": "Trip 1: Cheapest that fits. Fly from Seattle to Denver on May 4. From: SEA - Seattle, Washington",
    }
    control = {"text": "SEA - Seattle, Washington", "role": "option"}
    action = {"action": "click", "text": "SEA - Seattle, Washington"}
    assert holds(screen, "Fly from Seattle to Denver on May 4", action, {}, control)
    assert not holds(screen, "SEA - Seattle, Washington", action, {}, control), "the option's own label"
    assert not holds(screen, "Fly from Seattle to Boston", action, {}, control), "not in the entry"
    assert not holds(screen, "", action, {}, control), "no quote"
    current = dict(screen, label="the target field's current content")
    assert not holds(current, "Fly from Seattle to Denver on May 4", action, {}, control), "a pre-selected default"
    earlier = dict(screen, label="text an earlier page of this run showed")
    assert not holds(earlier, "Fly from Seattle to Denver on May 4", action, {}, control)
    fetched = dict(screen, label="text fetch_url read this run from x.example (untrusted web content, not the screen)")
    assert not holds(fetched, "Fly from Seattle to Denver on May 4", action, {}, control)
    profile = dict(screen, source="profile")
    assert not holds(profile, "Fly from Seattle to Denver on May 4", action, {}, control)
    window = dict(screen, label=GROUNDING_WINDOW_TEXT_LABEL)
    assert holds(window, "Fly from Seattle to Denver on May 4", action, {}, control), "a task window's text"


def test_an_unquoted_choice_quote_holding_a_long_label_is_not_a_self_citation() -> None:
    # Run 1909: goal quote "outcome Left voicemail" (22 chars vs a 14-char label) was refused by a char margin.
    screen = {
        "source": "page",
        "label": "text currently on screen",
        "value": "Log the call. Outcome: Left voicemail. Left voicemail",
    }
    control = {"text": "Left voicemail", "role": "option"}
    action = {"action": "click", "text": "Left voicemail"}
    goal_context = {"goal": "Log the call with outcome Left voicemail"}
    holds = extension_run._unquoted_choice_support_holds
    assert holds(screen, "outcome Left voicemail", action, goal_context, control), "goal-sourced quote"
    assert not holds(screen, "Left voicemail", action, {}, control), "the label itself"
    assert not holds(screen, "Left voicemail.", action, {}, control), "label plus punctuation"
    assert holds(screen, "Outcome: Left voicemail", action, {}, control), "page field word plus label"


