def test_a_missing_grounding_verdict_from_a_transient_fault_is_asked_once_more() -> None:
    worth = extension_run._grounding_verdict_worth_retry
    transport = {"status": "unavailable", "metadata": {"normalization": "failover_exhausted", "first_attempt": {"outcome": "provider_unavailable"}}}
    assert worth(transport, 90.0)
    assert not worth(transport, 200.0)
    assert not worth({"status": "grounded"}, 1.0)
    assert not worth({"status": "not_grounded"}, 1.0)
    assert not worth({"status": "unavailable", "metadata": {"normalization": "runtime_deadline_exceeded"}}, 5.0)
    assert not worth(dict(transport, metadata={**transport["metadata"], "finish_reason": "length"}), 5.0)
    capped_first = {"status": "unavailable", "metadata": {"first_attempt": {"outcome": "length_capped"}}}
    assert not worth(capped_first, 5.0)


def test_a_failover_hands_the_task_back_to_the_primary_brain(monkeypatch) -> None:
    # v6_docs run 1777 failed over on one timeout and kept the backup (which answered {} eleven times) for
    # the rest of the run. After a few valid decisions on the backup, the primary gets the task back.
    monkeypatch.setattr(extension_run, "_PROVIDER_TRANSPORT_RETRY_LIMIT", 2)
    monkeypatch.setattr(extension_run, "_PROVIDER_TRANSPORT_BACKOFF_CAP_SECONDS", 0)
    init_db()
    db_events: list[tuple[str, dict]] = []
    primary = _resolved_vision_provider(401, display_name="Primary", provider_type="openrouter", model_name="primary-model")
    backup = _resolved_vision_provider(402, display_name="Backup", provider_type="openrouter", model_name="backup-model")
    decided_by: list[str] = []
    backup_used = [0]

    async def narrate(kind: str, data: dict) -> None:
        pass

    async def fake_save(profile: dict, *, force: bool = False, run_id: int | None = None) -> bool:
        return True

    def fake_decide(user_id: int, image: dict, view: dict, context: dict) -> dict:
        selected = context.get("_vision_provider_override") or primary
        if selected is backup:
            decided_by.append("backup")
            backup_used[0] += 1
            return {"action": "wait", "wait_ms": 100, "reason": "Backup step."}
        decided_by.append("primary")
        if backup_used[0] == 0:
            return {
                "_outcome_type": "empty_completion",
                "failure_reason": "provider_empty_output",
                "_model_metadata": {"provider": "openrouter", "model": primary.model_name, "parse_status": "empty", "raw_output_empty": True},
            }
        return {"action": "done", "reason": "Back on the primary."}

    class _WaitBody(_VisionBody):
        async def vision_wait(self, wait_ms: int, **_kw) -> dict:
            return {"ok": True, "action": "wait", "waited_ms": wait_ms}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_vision_profile_key_for_user", lambda user_id: ("openrouter", primary.model_name))
    monkeypatch.setattr(extension_run, "_load_vision_decision_profile", lambda provider_type, model_name: {
        "provider_type": provider_type, "model_name": model_name, "ewma_latency_seconds": None, "token_budget": None, "latency_ring_seconds": [],
    })
    monkeypatch.setattr(extension_run, "_save_vision_decision_profile_async", fake_save)
    monkeypatch.setattr(extension_run, "_vision_provider_for_user", lambda user_id: primary)
    monkeypatch.setattr(extension_run, "_vision_backup_provider", lambda user_id, failing_id, *, excluded_provider_keys=None: backup)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    asyncio.run(run_vision_loop(_WaitBody(), url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=12))

    assert "backup" in decided_by
    first_backup = decided_by.index("backup")
    after = decided_by[first_backup:]
    assert after[: extension_run._VISION_FAILOVER_RESTORE_AFTER_VALID] == ["backup"] * extension_run._VISION_FAILOVER_RESTORE_AFTER_VALID
    assert after[extension_run._VISION_FAILOVER_RESTORE_AFTER_VALID] == "primary", "the primary got the task back"
    assert any(kind == "VISION_PROVIDER_FAILOVER_RESTORED" for kind, _ in db_events)


def test_a_click_naming_one_option_of_a_list_control_is_that_control(monkeypatch) -> None:
    # v6_calendar run 1783: a custom listbox enumerated as one control ("30 min 45 min 60 min 90 min"); the
    # brain named "60 min" and pointed at it, and was refused eight times as a stale control.
    listbox = {"kind": "div/listbox", "text": "30 min 45 min 60 min 90 min"}
    assert extension_run._click_target_identity_check({"action": "click", "text": "60 min"}, listbox)["ok"]
    assert not extension_run._click_target_identity_check({"action": "click", "text": "0 min"}, listbox)["ok"], "whole words only"
    button = {"kind": "button", "text": "Save draft"}
    refused = extension_run._click_target_identity_check({"action": "click", "text": "Cancel"}, button)
    assert not refused["ok"] and "reads 'Save draft'" in refused["feedback"], "a plain control still needs its own text"
    # A short value naming the label in whole words is that control (v6_travel: "SEA", "10C").
    assert extension_run._click_target_identity_check({"action": "click", "text": "SEA"}, {"tag": "option", "text": "SEA - Seattle, Washington"})["ok"]
    assert extension_run._click_target_identity_check({"action": "click", "text": "10C"}, {"tag": "button", "text": "Seat 10C, aisle, available"})["ok"]
    assert not extension_run._click_target_identity_check({"action": "click", "text": "0C"}, {"tag": "button", "text": "Seat 10C, aisle, available"})["ok"]


def test_typing_into_a_button_goes_back_to_the_brain_and_the_inventory_prefers_on_screen_rows() -> None:
    # v6_mail run 1785: a search typed into the "Spam" folder button reached the secret gate and ended the run.
    assert extension_run._control_plainly_takes_no_text({"tag": "button", "text": "Spam"})
    assert extension_run._control_plainly_takes_no_text({"tag": "a", "text": "Inbox"})
    assert not extension_run._control_plainly_takes_no_text({"tag": "input", "role": "searchbox"})
    assert not extension_run._control_plainly_takes_no_text({"tag": "div", "role": "button", "contenteditable": True})
    assert not extension_run._control_plainly_takes_no_text({"tag": "div", "text": "editor"}), "unknown stays to the gates"
    # v6_travel: rows scrolled out of view held the slots the results and form needed.
    def row(text: str, y: int) -> dict:
        return {"tag": "button", "text": text, "x": 10, "y": y, "width": 80, "height": 30}

    rows = [row(f"above {n}", -200 - n * 40) for n in range(3)] + [row(f"below {n}", 700 + n * 40) for n in range(3)]
    rows += [row(f"on screen {n}", 100 + n * 40) for n in range(3)]
    shown = extension_run._model_visible_control_rows(rows, limit=3, viewport_height=600)
    assert [item["text"] for item in shown] == ["on screen 0", "on screen 1", "on screen 2"]
    assert len(extension_run._model_visible_control_rows(rows, limit=3)) == 3, "no viewport: order as before"


def test_a_toggle_state_is_read_from_structure_only() -> None:
    # v6_mail run 1786: the judge heard a row checkbox's label as a value for its neighbours' text; it now
    # hears "tick '<label>'" or "uncheck '<label>'" from the box's own state.
    state = extension_run._control_toggle_state
    assert state({"tag": "input", "type": "checkbox", "checked": False}) == "unchecked"
    assert state({"tag": "input", "type": "checkbox", "checked": True}) == "checked"
    assert state({"tag": "div", "role": "switch", "aria_checked": "true"}) == "checked"
    assert state({"tag": "input", "type": "radio", "checked": True}) == ""
    assert state({"tag": "button", "text": "Archive"}) == ""
    assert extension_run._control_is_checked_toggle({"role": "checkbox", "checked": True})
    # A role=button folder is named by its own text, not the sidebar around it.
    folder = {"tag": "div", "role": "button", "text": "Archive", "context_text": "Finance | Inbox | 8"}
    assert extension_run._control_accessible_name(folder) == "Archive"
    assert extension_run._control_label(folder) == "Archive"


def test_the_inventory_fills_nearest_the_focused_control_first() -> None:
    # v6_calendar: grid slot buttons filled the slots before the open form beside the focused Title box.
    grid = [
        {"tag": "button", "text": f"New event slot {row}", "x": 64, "y": 160 + 20 * row, "width": 126, "height": 20}
        for row in range(10)
    ]
    title = {"tag": "input", "text": "Title", "x": 715, "y": 163, "width": 229, "height": 28, "focused": True}
    form = [
        {"tag": "div", "role": "button", "text": name, "x": 715, "y": 200 + 30 * row, "width": 229, "height": 24}
        for row, name in enumerate(("Day", "Start", "Duration"))
    ]
    rows = extension_run._model_visible_control_rows([*grid, title, *form], limit=6)
    texts = [row["text"] for row in rows]
    assert {"Title", "Day", "Start", "Duration"} <= set(texts)
    # The rows shown keep observation order.
    assert texts.index("Title") < texts.index("Day") and texts[0].startswith("New event")
    # No focus: observation order fills the tier.
    unfocused = [dict(row, focused=False) for row in [*grid, title, *form]]
    assert [row["text"] for row in extension_run._model_visible_control_rows(unfocused, limit=3)][0] == "New event slot 0"


def test_instrumental_verdict_fails_closed() -> None:
    holds = extension_run._instrumental_verdict_holds
    page = {"source": "page", "label": "text currently on screen", "value": "x"}
    ok = {"instrumental": True, "commits_or_destroys": False}
    assert holds(ok, page)
    # A destructive/committing command (Delete user, Place order) is never instrumental; omitted fails closed.
    assert not holds({"instrumental": True, "commits_or_destroys": True}, page)
    assert not holds({"instrumental": True}, page)
    assert not holds({"instrumental": True, "commits_or_destroys": "false"}, page)
    for bad in (True, "true", 1, None, "yes"):
        if bad is not True:
            assert not holds({**ok, "instrumental": bad}, page)
    assert not holds({}, page)
    assert not holds(None, page)
    assert not holds(ok, {})
    assert not holds(ok, dict(page, label="text an earlier page of this run showed"))
    assert not holds(ok, dict(page, source="user_data"))
    assert not holds(ok, dict(page, source="fetched", label="a fetched page"))
    # The judge indexed the control's own content but quoted the task's instruction from the screen (run 1799).
    own = {"source": "page", "label": "the target field's current content", "value": "on"}
    screen = {"source": "page", "label": "text currently on screen", "value": "Give the role Reviewer to every Active user."}
    quoted = {**ok, "support_quote": "Give the role Reviewer to every Active user"}
    assert holds(quoted, own, [own, screen])
    assert not holds(quoted, own, [own])
    assert not holds({**quoted, "commits_or_destroys": True}, own, [own, screen])
    assert not holds({**quoted, "support_quote": "Delete everyone"}, own, [own, screen])
    assert not holds(quoted, own, [own, dict(screen, source="user_data")])


class _ToastAfterClickBody(_LedgerBody):
    def __init__(self, **flags: object) -> None:
        super().__init__()
        self.flags = flags
        self.scrolls = 0

    async def vision_scroll(self, dy: int, **binding: object) -> dict:
        self.scrolls += 1
        return {"ok": True, "action": "scroll", "scroll_attempted": True, "scroll_y": dy}

    async def vision_click(
        self,
        x: int,
        y: int,
        *,
        expected_target_identity: dict | None = None,
        expected_page_context: dict | None = None,
    ) -> dict:
        self.clicks.append((x, y))
        return {"ok": True, "action": "click", **self.flags}


def test_a_scroll_chained_after_a_click_survives_a_local_surface_change(monkeypatch) -> None:
    # v6_shop run 1791: a toast after Add to cart (surface_changed) dropped the chained scroll.
    init_db()
    body = _ToastAfterClickBody(surface_changed=True, title_changed=True)
    contexts = _run_scripted(monkeypatch, body, [
        {"action": "click", "x": 220, "y": 140, "reason": "Add to cart.",
         "then": [{"action": "scroll", "x": 0, "y": 0, "direction": "down", "amount": 600}]},
    ], max_steps=1)
    assert body.clicks == [(220, 140)]
    assert body.scrolls == 1

    # A navigation still ends the sequence before the scroll.
    body = _ToastAfterClickBody(url_changed=True)
    _run_scripted(monkeypatch, body, [
        {"action": "click", "x": 220, "y": 140, "reason": "Open.",
         "then": [{"action": "scroll", "x": 0, "y": 0, "direction": "down", "amount": 600}]},
    ], max_steps=1)
    assert body.scrolls == 0


