class _TwoButtonPointBody(_ToastAfterClickBody):
    def __init__(self) -> None:
        super().__init__(surface_changed=True)
        self.control_clicks: list[str] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"]["controls"] = [
            {"index": 1, "tag": "button", "text": "Previous month", "selector": "#prev", "x": 540, "y": 190, "width": 60, "height": 40},
            {"index": 2, "tag": "button", "text": "Sunday, September 26,", "selector": "#sep26", "x": 700, "y": 310, "width": 50, "height": 40},
        ]
        return shot

    async def vision_click_control(self, selector: str, fallback_x: int, fallback_y: int, **binding: object) -> dict:
        self.control_clicks.append(selector)
        return {"ok": True, "action": "click", "surface_changed": True}


