def test_a_chained_point_is_gated_as_unbound_not_with_the_old_controls_verdict(monkeypatch) -> None:
    # Morph scenario: a click can redraw 'Add' in place as 'Place order'; the chained point must not be judged
    # (consequence/payment/grounding/identity) as the control that stood there BEFORE the click.
    import app.extension_run as er

    seen: list[object] = []
    real = er._click_target_identity_check

    def spy(action, control):
        if action.get("x") == 723 and action.get("y") == 330:
            seen.append(control)
        return real(action, control)

    monkeypatch.setattr(er, "_click_target_identity_check", spy)
    init_db()
    body = _TwoButtonPointBody()
    _run_scripted(monkeypatch, body, [
        {"action": "click", "x": 570, "y": 210, "reason": "Previous month.",
         "then": [{"action": "click", "x": 723, "y": 330}]},
    ], max_steps=1)
    assert seen and all(control is None for control in seen)


