def test_a_repeated_viewport_header_gives_way_to_what_follows_it():
    from app.extension_run import _viewport_text_without_repeated_head as shorten

    header = "Task one read the contract. " * 60
    previous = header + "Dashboard"
    current = header + "Contract: renewal date June 1, 2027. Notice 30 days. Legal name Pinecrest Media LLC, billing city Savannah."
    shortened = shorten(current, previous, 1200)
    assert "Contract: renewal date June 1, 2027" in shortened
    assert "unchanged since the last step omitted" in shortened
    assert len(shortened) < len(current)
    assert shorten(current, "", 1200) == current
    assert shorten(current, previous, 5000) == current
    assert shorten(header + "x", header + "x", 100) == header + "x"


