def test_follow_click_resolves_at_dispatch_rules():
    from app.extension_run import _follow_click_resolves_at_dispatch as ok

    click = {"kind": "click", "action": {"action": "click"}}
    label = {"action": {"action": "click", "target_text": "Finance"}, "kind": "click"}
    point = {"action": {"action": "click", "x": 5, "y": 6}, "kind": "click"}
    assert ok(label, click, scrolled=False, page_evidence={})
    assert ok(label, {"kind": "scroll", "action": {"action": "scroll"}}, scrolled=True, page_evidence={})
    assert ok(label, {"kind": "wait", "action": {"action": "wait"}}, scrolled=False, page_evidence={})
    assert not ok(label, {"kind": "wait", "action": {"action": "wait", "text": "x"}}, scrolled=False, page_evidence={})
    assert not ok(label, {"kind": "key", "action": {"action": "key"}}, scrolled=False, page_evidence={})
    assert not ok(point, {"kind": "scroll", "action": {"action": "scroll"}}, scrolled=True, page_evidence={})


