class _CellEditorBody(_CodeAndVerifyBody):
    """A grid: the point the click lands on falls inside a big container control (the toolbar's label), the
    click opens an inline editor (in place: surface_changed only) and its receipt names that editor."""

    EDITOR = {
        "target_selector": "input[aria-label=\"Unit price of HW-3906\"]", "target_text": "", "target_tag": "input",
        "target_type": "text", "target_role": "", "dispatch_path": "dom_activation", "page_url": "http://x/y",
    }

    def __init__(self, *, identity: dict | None = EDITOR) -> None:
        super().__init__()
        self.identity = identity
        self.keys: list[str] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"]["controls"] = [
            {"index": 1, "tag": "section", "type": "", "text": "Filters: text contains", "selector": "section.toolbar",
             "x": 0, "y": 0, "width": 1000, "height": 600},
            {"index": 2, "tag": "input", "type": "text", "text": "Filter SKU", "selector": "input[aria-label=\"Filter SKU\"]",
             "focused": True, "x": 10, "y": 10, "width": 100, "height": 30},
        ]
        return shot

    async def vision_click(self, x: int, y: int, **_binding: object) -> dict:
        self.clicks.append((x, y))
        return {
            "ok": True, "action": "click", "surface_changed": True, "active_typable": self.identity is not None,
            "active_tag": "input", "active_value": "98.87", "active_identity": dict(self.identity) if self.identity else None,
        }

    async def vision_click_control(self, selector: str, fallback_x: int, fallback_y: int, **_binding: object) -> dict:
        return await self.vision_click(fallback_x, fallback_y)

    async def vision_key(self, key: str, **_kwargs: object) -> dict:
        self.keys.append(key)
        return {"ok": True, "action": "key"}


