def test_row_selection_checkboxes_with_row_text_are_never_dense_and_cells_keep_a_fair_share():
    # v6_sheet run 1823: a forty-row sheet listed four to eight cells and lost its row checkboxes.
    checkboxes = [
        _inv_row(i + 1, "", 20, 100 + i * 26, tag="input", type="checkbox", w=12, h=12, class_name="rowsel",
                 row_text=f"TL-{1000 + i} Shelf bracket Summit Parts Co Active")
        for i in range(16)
    ]
    cells = [
        _inv_row(100 + r * 4 + c, f"cell {r}.{c}", 100 + c * 120, 100 + r * 26, tag="td", w=118, h=24)
        for r in range(8)
        for c in range(4)
    ]
    buttons = [_inv_row(300 + i, f"Action {i}", 700, 100 + i * 30, class_name="btn") for i in range(6)]
    shown = extension_run._model_visible_control_rows([*checkboxes, *cells, *buttons], limit=40, viewport_height=900)
    indexes = {row["index"] for row in shown}
    assert {row["index"] for row in checkboxes} <= indexes
    assert {row["index"] for row in buttons} <= indexes
    # Without a focused control, twelve of the page's own cells reach the model (it was four).
    assert sum(1 for row in shown if 100 <= row["index"] < 200) >= 12


