def test_enter_after_a_type_into_an_unlisted_editor_targets_that_editor(monkeypatch) -> None:
    # v6_sheet run 1812: [click cell, type, Enter] typed into the editor the click opened, a field the
    # observation never listed; the Enter then found no focused control and was withheld.
    init_db()

    class _UnlistedEditorBody(_KeyboardConsoleBody):
        def __init__(self) -> None:
            super().__init__()
            self.keys: list[str] = []

        async def vision_type_control(self, selector: str, text: str, **_binding: object) -> dict:
            self.type_control_calls.append((selector, text))
            return {"ok": True, "action": "type", "mode": "control_selector", "active_typable": True,
                    "active_has_value": True, "active_tag": "input", "active_value": text,
                    "active_selector": "#cell-editor", "active_label": "Qty", "surface_changed": True}

        async def vision_click_control(self, selector: str, *args, **kwargs) -> dict:
            return {"ok": True, "action": "click", "mode": "control_selector", "surface_changed": True,
                    "active_typable": True, "active_selector": "#cell-editor",
                    "active_identity": {"target_selector": "#cell-editor", "target_tag": "input", "dispatch_path": "dom",
                                        "page_url": "https://example.test/apply", "target_text": "", "target_type": "text", "target_role": ""}}

        async def vision_key(self, key, *args, **kwargs) -> dict:
            self.keys.append(str(key))
            return {"ok": True, "action": "key", "key": str(key), "surface_changed": True}

    body = _UnlistedEditorBody()
    _run_scripted(monkeypatch, body, [
        {"action": "click", "control": 0, "x": 140, "y": 120, "reason": "Open the cell editor.",
         "then": [{"action": "type", "control": 0, "text": "555-123-4567", "grounding_source": "profile",
                   "grounding_quote": "555-123-4567", "reason": "Type into the opened editor."},
                  {"action": "key", "key": "Enter"}]},
    ], max_steps=1)
    assert body.keys == ["Enter"], body.type_control_calls


