def test_answer_line_tags_never_claim_verification() -> None:
    found = extension_run._answer_final_line("hunter-42", ["The password is  hunter-42 today"], [])
    assert found == "Answer: hunter-42 (found on the page; not independently verified)"
    absent = extension_run._answer_final_line("hunter-42", ["Password revealed on screen."], [])
    assert absent == "Answer: hunter-42 (not found on the page)"
    assert extension_run._answer_final_line("ABC", ["abc"], []).endswith("(not found on the page)")
    assert extension_run._answer_final_line("", ["x"], []) == ""
    assert len(extension_run._answer_final_line("a" * 900, [], [])) < 560


def test_answer_echoing_typed_input_or_goal_is_not_page_evidence() -> None:
    page = ["Search box shows: tiger-77 and the task said find the secret code"]
    wholly = extension_run._answer_final_line("tiger-77", page, [], ["tiger-77"], "find the secret code")
    assert wholly.endswith("(not found on the page)")
    goal_only = extension_run._answer_final_line("find the secret code", page, [], [], "find the secret code")
    assert goal_only.endswith("(not found on the page)")
    # Typed text is blanked out of the page, but a real occurrence elsewhere still counts.
    both = extension_run._answer_final_line("gold", ["typed gold-bar then gold stays"], [], ["gold-bar"], "")
    assert both.endswith("(found on the page; not independently verified)")
    only_typed = extension_run._answer_final_line("gold-bar", ["typed gold-bar"], [], ["gold-bar x"], "")
    assert only_typed.endswith("(found on the page; not independently verified)")
    blanked = extension_run._answer_final_line("bar", ["typed gold-bar"], [], ["gold-bar"], "")
    assert blanked.endswith("(not found on the page)")


