def test_done_answer_reaches_the_loop_summary_with_its_tag(monkeypatch) -> None:
    init_db()
    results = {}
    for name, answer in (("seen", "Example job page text"), ("absent", "nowhere-on-page"), ("none", "")):
        monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
        monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
        monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
        monkeypatch.setattr(
            extension_run, "_decide_vision_action",
            lambda *a, _answer=answer, **k: {"action": "done", "reason": "Found it.", **({"answer": _answer} if _answer else {})},
        )

        async def narrate(kind: str, data: dict) -> None:
            pass

        results[name] = asyncio.run(run_vision_loop(_VisionBody(), url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=5))
    assert results["seen"]["answer_line"] == "Answer: Example job page text (found on the page; not independently verified)"
    assert results["absent"]["answer_line"] == "Answer: nowhere-on-page (not found on the page)"
    assert "answer_line" not in results["none"]


