class _LocalChangeBody(_GestureBody):
    """A body whose drags, keys and clicks only change the page surface (no navigation)."""

    def __init__(self) -> None:
        super().__init__()
        self.reloads = 0

    async def vision_drag(self, x: int, y: int, to_x: int, to_y: int, **kwargs) -> dict:
        self.drags.append({"from": (x, y), "to": (to_x, to_y)})
        return {"ok": True, "action": "drag", "surface_changed": True, "drag_from_tag": "input", "drag_to_tag": "input"}

    async def vision_reload(self, **_kw) -> dict:
        self.reloads += 1
        return {"ok": True, "action": "reload", "surface_changed": True}


def test_two_slider_drags_on_different_controls_run_in_one_chain(monkeypatch) -> None:
    # WebGames slider-symphony run 1856: the first drag changed its own slider, the chain aborted on
    # "page_transition:surface_changed" and the second slider cost a whole decision.
    init_db()
    body = _LocalChangeBody()
    _run_scripted(monkeypatch, body, [
        {"action": "drag", "control": 2, "x": 439, "y": 320, "to_x": 439, "to_y": 205, "reason": "Slider 2.",
         "then": [{"action": "drag", "control": 1, "x": 402, "y": 270, "to_x": 402, "to_y": 284}]},
    ], max_steps=1)
    assert len(body.drags) == 2


def test_a_key_after_a_reload_waits_for_a_fresh_look(monkeypatch) -> None:
    # frog-crossing run 1855: a reload is a navigation; the key written before the page reloaded must not run.
    init_db()
    body = _LocalChangeBody()
    _run_scripted(monkeypatch, body, [
        {"action": "reload", "reason": "Restart.", "then": [{"action": "key", "key": "ArrowUp"}]},
    ], max_steps=1)
    assert body.reloads == 1 and body.keys == []


def test_plain_keys_chain_after_a_key_that_shows_no_read_back(monkeypatch) -> None:
    # enter-date run 1853: digits into a date field's segments, each "unverified", aborted after the first.
    init_db()
    body = _LocalChangeBody()
    _run_scripted(monkeypatch, body, [
        {"action": "key", "key": "0", "reason": "Month digits.",
         "then": [{"action": "key", "key": "9"}, {"action": "key", "key": "1"}, {"action": "key", "key": "0"}]},
    ], max_steps=1)
    assert [key for key, _kw in body.keys] == ["0", "9", "1", "0"]
    # An Enter after them is a commit and still waits for a look.
    body = _LocalChangeBody()
    _run_scripted(monkeypatch, body, [
        {"action": "key", "key": "0", "reason": "Digit.", "then": [{"action": "key", "key": "Enter"}]},
    ], max_steps=1)
    assert [key for key, _kw in body.keys] == ["0"]

