def test_same_label_buttons_on_different_rows_are_counted_separately_but_a_reclick_repeats() -> None:
    # WebGames shopping run 1876: four products' "Add to Cart" buttons shared one repeat key.
    by_selector = [{"selector": f"#p{i} button", "tag": "button", "text": "Add to Cart"} for i in range(2)]

    def identity(control: dict) -> dict:
        shot = {"url": "https://example.test/shop", "page_evidence": {"controls": [control, *by_selector]}}
        return extension_run._progress_guard_identity(
            kind="click", action={"action": "click", "x": 400, "y": 350}, bound_control=control,
            shot=shot, bound_label="Add to Cart", bound_signature="sig", sensitive_type=False,
        )

    assert identity(by_selector[0])["action_key"] != identity(by_selector[1])["action_key"]
    assert identity(by_selector[0])["action_key"] == identity(by_selector[0])["action_key"]
    by_row = [{"tag": "button", "text": "Add to Cart", "row_text": f"Product {i} $2.49"} for i in range(2)]
    assert identity(by_row[0])["action_key"] != identity(by_row[1])["action_key"]
    bare = {"tag": "button", "text": "Add to Cart"}
    assert identity(bare)["action_key"] == identity(dict(bare))["action_key"], "no identity: same repeat key"


