class _FocusedKeyBody(_KeyboardConsoleBody):
    """A page whose one listed control holds keyboard focus; keys are recorded, never echoed back."""

    def __init__(self, control: dict) -> None:
        super().__init__()
        self.focused_control = {"index": 1, "selector": "#focus", "x": 100, "y": 100, "width": 240, "height": 40,
                                "text": "", "value": "", "focused": True, **control}
        self.pressed: list[str] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"]["controls"] = [dict(self.focused_control)]
        return shot

    async def vision_key(self, key, *args, **kwargs) -> dict:
        self.pressed.append(str(key))
        return {"ok": True, "action": "key", "key": str(key), "surface_changed": False}


def _recent(contexts: list[dict]) -> str:
    return " ".join(str(item) for context in contexts for item in (context.get("recent_actions") or []))


def test_a_printable_key_into_a_password_field_is_refused_toward_type(monkeypatch) -> None:
    init_db()
    body = _FocusedKeyBody({"tag": "input", "type": "password", "context_text": "Password"})
    contexts = _run_scripted(monkeypatch, body, [
        {"action": "key", "key": "Z", "reason": "Type the password one key at a time."},
    ], max_steps=2)
    assert body.pressed == []
    recent = _recent(contexts)
    assert "keyed_text_sensitive_requires_type" in recent
    assert "'Z'" not in recent and "key=Z" not in recent


