def test_a_converted_click_is_judged_by_the_grounding_gate_of_its_type(monkeypatch) -> None:
    init_db()
    monkeypatch.setattr("app.lumen_model.LumenModelClient.judge_grounding", lambda self, **kwargs: {"grounded": False, "entry_index": -1, "reason": "Not supported."})
    body = _NativeSelectBody()
    contexts = _run_scripted(monkeypatch, body, [
        # Cites a value the profile does not hold: the option is refused by grounding, exactly as a type would be.
        {"action": "click", "control": 1, "x": 220, "y": 140, "text": "No", "question": body.SELECT_QUESTION,
         "grounding_source": "profile", "grounding_quote": "Maybe", "reason": "Answer No."},
    ], max_steps=2, engine=_SponsorContextEngine)
    assert body.type_control_calls == [], _recent(contexts)
    assert body.clicks == [] and body.point_clicks == [], _recent(contexts)
    assert "native_select_option_click" not in _recent(contexts)
    # The refusal reaches the brain once, in last_reply (its recent_actions copy is dropped as a duplicate).
    shown = _recent(contexts) + " ".join(str(context.get("last_reply") or "") for context in contexts)
    assert "grounding" in shown


