def test_a_native_select_click_is_converted_only_for_one_exact_option_on_its_own_control() -> None:
    controls = [
        {"index": 1, "tag": "select", "text": "Yes No", "selector": "#sponsor", "x": 100, "y": 120, "width": 240, "height": 40,
         "options": ["Yes", "No"]},
        {"index": 2, "tag": "button", "text": "No", "selector": "#no", "x": 100, "y": 200, "width": 80, "height": 40},
    ]
    evidence = {"controls": controls}
    index_map = extension_run._control_inventory_index_map(evidence)

    def convert(action: dict, surface: str = "browser") -> str:
        return extension_run._native_select_click_option(
            action,
            control_index=extension_run._action_control_index(action),
            control_index_map=index_map,
            page_evidence=evidence,
            coord_scale=1.0,
            execution_surface=surface,
        )

    assert convert({"action": "click", "control": 1, "text": "No"}) == "No"
    assert convert({"action": "click", "control": 1, "text": "  no "}) == "No"
    assert convert({"action": "click", "x": 150, "y": 140, "text": "yes"}) == "Yes"
    assert convert({"action": "click", "control": 1, "text": "Maybe"}) == ""
    assert convert({"action": "click", "control": 1, "text": ""}) == ""
    assert convert({"action": "click", "control": 2, "text": "No"}) == ""
    assert convert({"action": "click", "control": 1, "x": 150, "y": 210, "text": "No"}) == ""
    assert convert({"action": "type", "control": 1, "text": "No"}) == ""
    assert convert({"action": "click", "control": 1, "text": "No"}, surface="desktop") == ""


