class _CopyingKeyBody(_FocusedKeyBody):
    """A focused text field whose Ctrl+C reports the page's copy event with the copied text."""

    copied = "555-123-4567"

    async def vision_key(self, key, *args, **kwargs) -> dict:
        result = await super().vision_key(key, *args, **kwargs)
        if str(key).lower() in {"ctrl+c", "control+c"}:
            result["clipboard_events"] = [{"type": "copy", "selection_length": len(self.copied), "text": self.copied}]
        return result


