def test_a_paste_of_page_copied_text_runs_the_type_gates(monkeypatch) -> None:
    init_db()
    # Copied text is an ungrounded fact when pasted: refused like the same text typed.
    body = _CopyingKeyBody({"tag": "input", "type": "text", "context_text": "Phone number"})
    body.copied = "777-888-9999"
    contexts = _run_scripted(monkeypatch, body, [
        {"action": "key", "key": "Ctrl+c", "reason": "Copy."},
        {"action": "key", "key": "Ctrl+v", "reason": "Paste."},
    ], max_steps=3)
    assert "Ctrl+v" not in body.pressed, _recent(contexts)
    assert "grounding_" in _recent(contexts)
    # With a grounded citation it goes through.
    body = _CopyingKeyBody({"tag": "input", "type": "text", "context_text": "Phone number"})
    grounded = {"grounding_source": "profile", "grounding_quote": "555-123-4567"}
    contexts = _run_scripted(monkeypatch, body, [
        {"action": "key", "key": "Ctrl+c", "reason": "Copy."},
        {"action": "key", "key": "Ctrl+v", "reason": "Paste.", **grounded},
    ], max_steps=3)
    assert body.pressed == ["Ctrl+c", "Ctrl+v"], _recent(contexts)


