def test_chain_prior_click_regions_bound_what_a_chained_click_may_find_changed() -> None:
    from app.extension_run import _chain_prior_click_regions, _outcome_state, _reply_readback

    prepared = [
        {"action": {"action": "click", "x": 100, "y": 200}, "bound_control": {"x": 90, "y": 190, "width": 30, "height": 30}},
        {"action": {"action": "click", "x": 500, "y": 300}, "bound_control": {"x": 0, "y": 0, "width": 900, "height": 600}},
        {"action": {"action": "type", "text": "x"}},
    ]
    regions = _chain_prior_click_regions(prepared, 1.0)
    assert regions[0] == {"x": 90, "y": 190, "width": 30, "height": 30}
    # a whole-canvas control never widens the tolerated area past a small square around the point
    assert regions[1] == {"x": 436, "y": 236, "width": 128, "height": 128}
    assert len(regions) == 2

    key_result = {
        "action": "key",
        "key": "Enter",
        "edit_commit": {"editor_hint": "To:", "edit_value": "Steam", "editor_still_focused": True, "editor_value_after": "Steam"},
    }
    readback = _reply_readback(key_result)
    assert "reads 'Steam'" in readback
    state = _outcome_state({"ok": True, "timing_outcome": "executed", "readback": readback})
    assert state.startswith("ran unverified (executed)") and "reads 'Steam'" in state

