def test_choice_text_is_the_visible_label_never_the_value_attribute() -> None:
    derive = extension_run._derived_choice_text_from_control
    labelled = {"tag": "input", "type": "checkbox", "value": "on", "label": "Item 3", "text": ""}
    assert derive(labelled) == "Item 3"
    aria = {"tag": "input", "type": "checkbox", "value": "on", "aria_label": "Item 4"}
    assert derive(aria) == "Item 4"
    option = {"tag": "div", "role": "option", "value": "opt_7", "text": "Seven"}
    assert derive(option) == "Seven"
    assert derive({"tag": "input", "type": "checkbox", "value": "on"}) == ""
    # Run 75: a custom radio whose label is slotted in has no `text`; the body's visible derived label names it.
    slotted = {
        "tag": "spl-radio",
        "role": "radio",
        "text": "",
        "derived_label": "No, I do not have a disability and have not had one in the past.",
        "derived_label_visible": True,
        "context_text": "Do you have (or have a history/record of having) a disability?",
    }
    assert derive(slotted) == "No, I do not have a disability and have not had one in the past."
    # Class-name or attribute words are never a choice's visible text.
    assert derive({"tag": "div", "role": "option", "text": "", "derived_label": "c spl dropdown item"}) == ""


