def test_query_candidate_pages_report_more_facts_and_page_two_returns_the_rest(monkeypatch) -> None:
    entries = [{"source": "profile", "label": f"fact_{i}", "value": f"value {i}"} for i in range(8)]
    monkeypatch.setattr(extension_run, "_candidate_evidence_entries", lambda context, *, source_scope: entries)
    seen_limits: list[int] = []

    def retrieve(user_id, *, query, entries, task_context=None, limit=None):
        seen_limits.append(limit)
        return {"indexes": list(range(len(entries))), "metadata": {"provider": "t", "model": "m"}}

    monkeypatch.setattr(extension_run, "_call_candidate_evidence_retriever", retrieve)
    first = extension_run._retrieve_candidate_evidence(1, query="q", source_scope="profile", context={})
    second = extension_run._retrieve_candidate_evidence(1, query="q", source_scope="profile", context={}, page=1)
    assert [f["label"] for f in first["facts"]] == [f"fact_{i}" for i in range(5)]
    assert first["more_count"] == 3
    assert [f["label"] for f in second["facts"]] == ["fact_5", "fact_6", "fact_7"]
    assert second["more_count"] == 0 and seen_limits == [10, 15]


