def test_horizontal_scroll_receipt_uses_widths_never_vertical_totals():
    from app.extension_run import _add_horizontal_scroll_view, _vision_result_hint

    page = _vision_result_hint(
        {
            "scroll_changed": True,
            "scroll_axis": "horizontal",
            "before_scroll_position": 0,
            "scroll_position": 2037,
            "scroll_width": 3780,
            "inner_w": 1120,
            "scroll_height": 683,
            "inner_h": 700,
        }
    )
    assert "page scrolled right 0->2037px of 3780px (1120px visible at once)" in page
    box = _vision_result_hint(
        {
            "scroll_changed": True,
            "scroll_axis": "horizontal",
            "scroll_target_kind": "container",
            "before_scroll_position": 600,
            "scroll_position": 200,
            "scroll_container_scroll_width": 2400,
            "scroll_container_client_width": 600,
            "scroll_container_scroll_height": 100,
            "scroll_container_client_height": 50,
        }
    )
    assert "scrollable region scrolled left 600->200px of 2400px (600px visible at once)" in box

    wide = {}
    _add_horizontal_scroll_view(wide, {"scroll_x": 640, "scroll_width": 3780, "inner_w": 1120})
    assert wide == {"scroll_x": 640, "scroll_width": 3780}
    narrow = {}
    _add_horizontal_scroll_view(narrow, {"scroll_x": 0, "scroll_width": 1120, "inner_w": 1120})
    assert narrow == {}


def test_observed_control_dispatch_path_follows_the_observer_and_falls_back_to_tag():
    from app.extension_run import _observed_control_target_identity

    def path(control):
        return _observed_control_target_identity(control, page_url="https://example.test")["dispatch_path"]

    # An SVG descendant carries the observer's closest("canvas,svg") path, not its own tag's.
    assert path({"tag": "text", "text": "A", "selector": "#t", "dispatch_path": "cdp_trusted_click"}) == "cdp_trusted_click"
    assert path({"tag": "button", "text": "Go", "selector": "#b", "dispatch_path": "dom_activation"}) == "dom_activation"
    # A control the observer did not stamp keeps the tag rule; an unknown value is not trusted.
    assert path({"tag": "button", "text": "Go", "selector": "#b"}) == "dom_activation"
    assert path({"tag": "svg", "selector": "#s"}) == "cdp_trusted_click"
    assert path({"tag": "button", "text": "Go", "selector": "#b", "dispatch_path": "bogus"}) == "dom_activation"


def test_a_choice_judge_reads_the_page_text_around_the_chosen_option() -> None:
    # v6_shop run 1856: the shipping rule sat beside the options, far from the task card the brain quoted,
    # and reached the judge only as untrusted interaction context; a correct choice was refused four times.
    card = "4. Delivery deadline This order must be delivered by Wednesday, September 22, 2027. Choose the cheapest shipping option that arrives on or before that day. "
    filler = "Product listing row. " * 90
    panel = (
        "Shipping Orders placed today ship today. Delivery takes the stated number of business days after today "
        "(weekends are not business days). Saver - 7 business days - $4.95 Standard - 5 business days - $8.95 "
        "Express - 2 business days - $19.95 Overnight - 1 business day - $34.95"
    )
    screen = card + filler + panel
    action = {
        "action": "click",
        "text": "Express - 2 business days - $19.95",
        "grounding_source": "page",
        "grounding_quote": "Choose the cheapest shipping option that arrives on or before that day.",
    }
    control = {"text": "Express - 2 business days - $19.95", "role": "button"}
    entries = extension_run._grounding_judge_page_entries(
        action,
        {"reason": "page_source_not_allowed_for_choice", "source": "page"},
        decision_context={"page_evidence": {"viewport_text": screen}},
        bound_control=control,
        page_evidence={"viewport_text": screen},
        receiving_surface_is_page=True,
    )
    assert entries[0]["label"] == "cited page text", "the brain's quote stays entry 0"
    around = [e for e in entries if "Orders placed today ship today" in e["value"]]
    assert around and around[0]["label"] == "text currently on screen"
    assert "Express - 2 business days" in around[0]["value"]
    # Only a refused choice gets the extra cut: a typed value's window is never centred on the value.
    entries = extension_run._grounding_judge_page_entries(
        {"action": "type", "text": "Express - 2 business days - $19.95"},
        {"reason": "value_not_supported_by_quote", "source": "page"},
        decision_context={"page_evidence": {"viewport_text": screen}},
        bound_control=control,
        page_evidence={"viewport_text": screen},
        receiving_surface_is_page=True,
    )
    assert not any("Orders placed today ship today" in e["value"] for e in entries)
    # An option the screen does not hold adds nothing.
    entries = extension_run._grounding_judge_page_entries(
        {"action": "click", "text": "Zzz option"},
        {"reason": "page_source_not_allowed_for_choice", "source": "page"},
        decision_context={"page_evidence": {"viewport_text": screen}},
        bound_control={"text": "Zzz option"},
        page_evidence={"viewport_text": screen},
        receiving_surface_is_page=True,
    )
    assert not any("Orders placed today ship today" in e["value"] for e in entries)


def test_editable_control_values_survive_the_trim_verbatim() -> None:
    rows = [
        {"index": 1, "tag": "textarea", "text": "Notes", "value": "abc  def \n", "x": 0, "y": 0, "width": 50, "height": 9},
        {"index": 2, "tag": "input", "text": "Long", "value": "x" * 2500, "x": 0, "y": 20, "width": 50, "height": 9},
        {"index": 3, "tag": "div", "text": "Chip", "value": "a  b ", "x": 0, "y": 40, "width": 50, "height": 9},
    ]
    kept = extension_run._trim_observed_controls(rows, limit=16, text_limit=120)
    by_index = {row["index"]: row for row in kept}
    assert by_index[1]["value"] == "abc  def \n" and "value_truncated" not in by_index[1]
    assert len(by_index[2]["value"]) == 2000 and by_index[2]["value_truncated"] is True and by_index[2]["value_length"] == 2500
    assert by_index[3]["value"] == "a b"

def test_non_text_inputs_keep_the_trimmed_value() -> None:
    rows = [
        {"index": 1, "tag": "input", "type": "checkbox", "text": "Agree", "value": " on ", "x": 0, "y": 0, "width": 9, "height": 9},
        {"index": 2, "tag": "input", "type": "password", "text": "Pw", "value": "[REDACTED]", "x": 0, "y": 20, "width": 9, "height": 9},
        {"index": 3, "tag": "input", "type": "text", "text": "Name", "value": "Ann ", "x": 0, "y": 40, "width": 9, "height": 9},
    ]
    kept = {row["index"]: row for row in extension_run._trim_observed_controls(rows, limit=16, text_limit=120)}
    assert kept[1]["value"] == "on"
    assert kept[2]["value"] == "[REDACTED]"
    assert kept[3]["value"] == "Ann "


def _run_transport_failure_scenario(monkeypatch, error: str, *, with_backup: bool = True):
    monkeypatch.setattr(extension_run, "_PROVIDER_TRANSPORT_BACKOFF_CAP_SECONDS", 0)
    init_db()
    body = _ChoiceBody()
    db_events: list[tuple[str, dict]] = []
    calls: list[object] = []
    primary = _resolved_vision_provider(
        701, display_name="Primary", provider_type="openrouter", model_name="primary-model"
    )
    backup = _resolved_vision_provider(
        702, display_name="Backup", provider_type="openrouter", model_name="backup-model"
    )

    async def narrate(kind: str, data: dict) -> None:
        pass

    async def fake_save(profile: dict, *, force: bool = False, run_id: int | None = None) -> bool:
        return True

    def fake_backup_provider(user_id, failing_id, *, excluded_provider_keys=None):
        excluded = set(excluded_provider_keys or ())
        if with_backup and extension_run._vision_provider_runtime_key(backup) not in excluded:
            return backup
        return None

    def fake_decide(user_id, image, view, context):
        selected = context.get("_vision_provider_override") or primary
        calls.append(selected)
        if selected is backup:
            return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "ready"}
        return {
            "_outcome_type": "provider_transport_error",
            "failure_reason": "provider_transport_error",
            "error": error,
            "_model_metadata": {"provider": "openrouter", "model": primary.model_name},
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_vision_profile_key_for_user", lambda user_id: ("openrouter", primary.model_name))
    monkeypatch.setattr(
        extension_run,
        "_load_vision_decision_profile",
        lambda pt, mn: {"provider_type": pt, "model_name": mn, "ewma_latency_seconds": None, "token_budget": None, "latency_ring_seconds": []},
    )
    monkeypatch.setattr(extension_run, "_save_vision_decision_profile_async", fake_save)
    monkeypatch.setattr(extension_run, "_vision_provider_for_user", lambda user_id: primary)
    monkeypatch.setattr(extension_run, "_vision_backup_provider", fake_backup_provider)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *a, **k: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    summary = asyncio.run(
        run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=40)
    )
    # The primary may be handed the task back after the backup carries it; count the first episode.
    primary_calls = next((i for i, c in enumerate(calls) if c is backup), len(calls))
    classes = [p["attempt_record"].get("error_class") for t, p in db_events if t == "VISION_MODEL_PROVIDER_FAILURE"]
    return summary, primary_calls, classes


@pytest.mark.parametrize(
    ("error", "expected_class", "primary_calls"),
    [
        ("Error code: 400 - data_inspection_failed: Input image data may contain inappropriate content", "non_retryable", 1),
        ("HTTP 402 Payment Required", "non_retryable", 1),
        ("HTTP 429 Too Many Requests", "rate_limit", 2),
        ("Connection reset by peer", "rate_limit", 2),
        ("request timed out after 35s", "transient", 6),
        ("HTTP 503 Service Unavailable", "transient", 6),
    ],
)
def test_vision_loop_provider_error_class_sets_same_row_retries_then_fails_over(
    monkeypatch, error: str, expected_class: str, primary_calls: int
) -> None:
    summary, calls, classes = _run_transport_failure_scenario(monkeypatch, error)
    assert summary["state"] == "READY_FOR_REVIEW"
    assert calls == primary_calls
    assert set(classes) == {expected_class}


def test_vision_loop_non_retryable_error_without_backup_keeps_block_reason(monkeypatch) -> None:
    summary, calls, classes = _run_transport_failure_scenario(
        monkeypatch, "HTTP 402 Payment Required", with_backup=False
    )
    assert summary["state"] == "BLOCKED"
    assert summary["reason"] == "provider_error_exhausted"
    assert calls == 1
    assert classes == ["non_retryable"]


def _run_two_row_failover(monkeypatch, script, *, designated_only=False):
    """Two vision rows; script(name, call_no, state) returns an error string or None for a valid action."""
    monkeypatch.setattr(extension_run, "_PROVIDER_TRANSPORT_BACKOFF_CAP_SECONDS", 0)
    init_db()
    body = _ChoiceBody()
    db_events: list[tuple[str, dict]] = []
    calls: list[str] = []
    state: dict = {}
    rows = {
        "primary": _resolved_vision_provider(801, display_name="Primary", provider_type="openrouter", model_name="p"),
        "backup": _resolved_vision_provider(802, display_name="Backup", provider_type="openrouter", model_name="b"),
    }

    async def narrate(kind: str, data: dict) -> None:
        pass

    async def fake_save(profile: dict, *, force: bool = False, run_id: int | None = None) -> bool:
        return True

    def fake_backup_provider(user_id, failing_id, *, excluded_provider_keys=None):
        excluded = set(excluded_provider_keys or ())
        if designated_only:  # real selection: only the designated row 802, never the failing one
            return None if failing_id == 802 else rows["backup"]
        for row in rows.values():
            if extension_run._vision_provider_runtime_key(row) not in excluded:
                return row
        return None

    def fake_decide(user_id, image, view, context):
        selected = context.get("_vision_provider_override") or rows["primary"]
        name = "primary" if selected is rows["primary"] else "backup"
        calls.append(name)
        error = script(name, calls.count(name), state)
        if error is None:
            return {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "ready"}
        return {
            "_outcome_type": "provider_transport_error",
            "failure_reason": "provider_transport_error",
            "error": error,
            "_model_metadata": {"provider": "openrouter", "model": selected.model_name},
        }

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_vision_profile_key_for_user", lambda user_id: ("openrouter", "p"))
    monkeypatch.setattr(
        extension_run,
        "_load_vision_decision_profile",
        lambda pt, mn: {"provider_type": pt, "model_name": mn, "ewma_latency_seconds": None, "token_budget": None, "latency_ring_seconds": []},
    )
    monkeypatch.setattr(extension_run, "_save_vision_decision_profile_async", fake_save)
    monkeypatch.setattr(extension_run, "_vision_provider_for_user", lambda user_id: rows["primary"])
    monkeypatch.setattr(extension_run, "_vision_backup_provider", fake_backup_provider)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *a, **k: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", fake_decide)
    summary = asyncio.run(
        run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=60)
    )
    failovers = [p for t, p in db_events if t == "VISION_PROVIDER_FAILOVER"]
    return summary, calls, failovers


def test_vision_failover_returns_to_primary_after_one_timeout_and_backup_content_filter(monkeypatch) -> None:
    def script(name, n, state):
        if name == "primary":
            return None if state.get("backup_rejected") else "request timed out after 35s"
        state["backup_rejected"] = True
        return "Error code: 400 - data_inspection_failed: Input image data may contain inappropriate content"

    summary, calls, failovers = _run_two_row_failover(monkeypatch, script)
    assert summary["state"] == "READY_FOR_REVIEW"
    assert [f["to_provider_id"] for f in failovers] == [802, 801]
    assert failovers[1]["failure_kind"] == "content_filter"
    assert failovers[1]["excluded_rows"] == []


def test_vision_failover_fails_back_to_the_original_brain_when_the_backup_is_rate_limited(monkeypatch) -> None:
    def script(name, n, state):
        if name == "primary":
            return None if state.get("backup_limited") else "request timed out after 35s"
        state["backup_limited"] = True
        return "HTTP 429 Too Many Requests"

    summary, calls, failovers = _run_two_row_failover(monkeypatch, script, designated_only=True)
    assert summary["state"] == "READY_FOR_REVIEW"
    assert [f["to_provider_id"] for f in failovers] == [802, 801]
    assert [f["failback_to_original"] for f in failovers] == [False, True]


def test_vision_failover_does_not_fail_back_to_an_original_excluded_by_a_402(monkeypatch) -> None:
    def script(name, n, state):
        return "HTTP 402 Payment Required" if name == "primary" else "HTTP 429 Too Many Requests"

    summary, calls, failovers = _run_two_row_failover(monkeypatch, script, designated_only=True)
    assert summary["state"] == "BLOCKED" and summary["reason"] == "provider_error_exhausted"
    assert calls.count("primary") == 1
    assert all(not f["failback_to_original"] for f in failovers)


def test_vision_failover_failback_still_respects_the_hop_cap(monkeypatch) -> None:
    summary, calls, failovers = _run_two_row_failover(
        monkeypatch, lambda name, n, state: "HTTP 503 Service Unavailable", designated_only=True
    )
    assert summary["state"] == "BLOCKED"
    assert len(failovers) <= extension_run._VISION_PROVIDER_FAILOVER_LIMIT


def test_vision_failover_excludes_a_row_for_the_run_after_a_402(monkeypatch) -> None:
    def script(name, n, state):
        return "HTTP 402 Payment Required" if name == "primary" else "request timed out after 35s"

    summary, calls, failovers = _run_two_row_failover(monkeypatch, script)
    assert summary["state"] == "BLOCKED" and summary["reason"] == "provider_error_exhausted"
    assert calls.count("primary") == 1
    assert [f["to_provider_id"] for f in failovers] == [802]
    assert failovers[0]["failure_kind"] == "non_retryable"
    assert len(failovers[0]["excluded_rows"]) == 1


def test_vision_failover_cap_stops_endless_hopping(monkeypatch) -> None:
    summary, calls, failovers = _run_two_row_failover(
        monkeypatch, lambda name, n, state: "HTTP 503 Service Unavailable"
    )
    assert summary["state"] == "BLOCKED" and summary["reason"] == "provider_error_exhausted"
    assert 1 <= len(failovers) <= extension_run._VISION_PROVIDER_FAILOVER_LIMIT


def test_provider_status_pattern_reads_real_statuses_and_ignores_lookalikes() -> None:
    from app.extension_run import _classify_provider_transport_error, _PROVIDER_STATUS_PATTERN

    def status(text):
        match = _PROVIDER_STATUS_PATTERN.search(text)
        return (match.group(1) or match.group(2)) if match else None

    assert status("Error code: 400 - {...}") == "400"
    assert status("HTTP 402") == "402"
    assert status("status_code=429") == "429"
    assert status("Client error '400 Bad Request' for url") == "400"
    for lookalike in ("took 4000ms", "unicode 4000", "req id 4000abc", "status 4001"):
        assert status(lookalike) is None, lookalike


class _WhoseFactBody(_StatefulTwoFieldBody):
    """One text field whose label and surrounding page text the test chooses."""

    def __init__(self, label: str, page_text: str, control_type: str = "text", role: str = "") -> None:
        super().__init__()
        self._label, self._page_text, self._control_type, self._role = label, page_text, control_type, role

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"] = {
            "viewport_text": self._page_text,
            "controls": [
                {"index": 1, "tag": "input", "type": self._control_type, "role": self._role, "text": self._label,
                 "value": self.values.get("#first", ""), "selector": "#first",
                 "x": 100, "y": 100, "width": 300, "height": 30},
            ],
        }
        return shot


def _run_whose_fact(
    monkeypatch, body, verdict, *, text: str, quote: str, source: str = "page", install=None, decision=None
) -> tuple[list[dict], list[tuple]]:
    init_db()
    calls: list[dict] = []
    events: list[tuple] = []

    def judge(user_id: int, **kwargs) -> dict:
        calls.append(kwargs)
        if isinstance(verdict, Exception):
            raise verdict
        return dict(verdict)

    decisions = iter(
        [
            decision
            or {"action": "type", "control": 1, "x": 250, "y": 115, "text": text,
                "grounding_source": source, "grounding_quote": quote, "reason": "From the page."}
        ]
    )
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    async def narrate(kind: str, data: dict) -> None:
        pass

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, kind, payload=None, *a, **k: events.append((kind, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: dict(next(decisions, done)))
    monkeypatch.setattr(extension_run, "_call_field_subject_judge", judge)
    if install is not None:
        install()
    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))
    return calls, events


def test_a_page_claimed_user_phone_is_rejected_for_a_field_that_asks_for_the_users_phone(monkeypatch) -> None:
    body = _WhoseFactBody("Your phone", "Support note: the customer's phone number is 555-0142. Your phone")
    calls, events = _run_whose_fact(
        monkeypatch, body, {"subject": "user", "reason": "asks for the user's phone", "fail_closed": False},
        text="555-0142", quote="the customer's phone number is 555-0142",
    )
    assert len(calls) == 1 and "Your phone" in calls[0]["field"] and calls[0]["proposed_value"] == "555-0142"
    assert body.type_control_calls == []
    assert any(kind == "VISION_FIELD_SUBJECT_VERDICT" and data["subject"] == "user" for kind, data in events)


