def test_a_whose_fact_verdict_is_not_reused_across_pages_or_forms(monkeypatch) -> None:
    init_db()
    calls: list[dict] = []

    def judge(user_id: int, **kwargs) -> dict:
        calls.append(kwargs)
        return {"subject": "third_party", "reason": "fixture", "fail_closed": False}

    monkeypatch.setattr(extension_run, "_call_field_subject_judge", judge)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    action = {"action": "type", "text": "555-0142", "grounding_quote": "phone 555-0142"}

    def ask(url: str, form_id: str, lifecycle: str = "doc-1") -> str:
        control = {"label": "Phone", "type": "text", "form_id": form_id}
        scope = extension_run._field_subject_scope(url, control, {"document_lifecycle_token": lifecycle})
        return asyncio.run(
            extension_run._field_subject(
                run_id=7, user_id=0, goal="g", action=action, value="555-0142", cited_source="page",
                bound_control=control, bound_label="Phone", label="seq0", scope=scope,
            )
        )

    ask("https://crm.example/leads?x=1", "0")
    ask("https://crm.example/leads?x=2", "0")  # same origin + path: reused
    assert len(calls) == 1
    ask("https://crm.example/signup", "0")
    ask("https://crm.example/leads", "1")
    ask("https://crm.example/leads", "0", lifecycle="doc-2")
    assert len(calls) == 4


