# --- Approval mode: a "fill this form" goal may read the saved profile (owner 2026-10-07) -------------------


class _FormFillBody(_WhoseFactBody):
    """A phone field plus a Submit button; records any click that reaches the page."""

    def __init__(self, button: str = "Submit application") -> None:
        super().__init__("Your phone", "Free trial sign-up. Your phone")
        self._button = button
        self.clicks: list[tuple] = []

    async def capture_screenshot(self) -> dict:
        shot = await super().capture_screenshot()
        shot["page_evidence"]["controls"].append(
            {"index": 2, "tag": "button", "type": "submit", "text": self._button, "value": "", "selector": "#submit",
             "x": 100, "y": 200, "width": 200, "height": 40}
        )
        return shot

    async def click(self, *args, **kwargs):  # type: ignore[override]
        self.clicks.append(args)
        return await super().click(*args, **kwargs)


def _run_approval_form(monkeypatch, decisions: list[dict], *, facts: list[dict], body=None, mode: str = "approval"):
    init_db()
    body = body or _FormFillBody()
    events: list[tuple[str, dict]] = []
    with SessionLocal() as db:
        user = models.User(email=f"approval-fill-{uuid.uuid4().hex}@example.com", name="Approval Fill")
        db.add(user)
        db.flush()
        update_agent_settings(db, user.id, {"final_action_mode": mode})
        run = models.OperatorRun(
            user_id=user.id, application_id=None, goal="Fill out this form for me: https://forms.example/f",
            target_url="https://forms.example/f", current_state="RUNNING",
            confidence_state={"browser_task": {"candidate_data_access": "none", "candidate_data_scopes": []}},
        )
        db.add(run)
        db.commit()
        run_id, user_id = int(run.id), int(user.id)
    queue = iter(decisions)
    done = {"action": "done", "x": 0, "y": 0, "artifact_role": "", "reason": "Done."}

    def decide(uid, image, view, context):
        return dict(next(queue, done))

    narrations: list[tuple[str, dict]] = []

    async def narrate(kind: str, data: dict) -> None:
        narrations.append((kind, data))

    def whose(*args, **kwargs):
        raise AssertionError("a profile-sourced value never reaches the whose-fact judge")

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda rid, kind, payload=None, *a, **k: events.append((kind, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    monkeypatch.setattr(extension_run, "_call_field_subject_judge", whose)
    monkeypatch.setattr(
        extension_run, "_call_candidate_scope_judge",
        lambda uid, *, goal, scopes: {"needed_scopes": ["profile"], "reason": "fills the form for the user", "fail_closed": False},
    )
    monkeypatch.setattr(extension_run, "_candidate_retrieval_context_for_user", lambda *a, **k: {})
    monkeypatch.setattr(
        extension_run, "_retrieve_candidate_evidence",
        lambda *a, **k: {"facts": list(facts), "retrieval_succeeded": True},
    )
    summary = asyncio.run(
        run_vision_loop(body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=6)
    )
    summary = {**summary, "narrations": narrations}
    return body, summary, events


