@pytest.mark.parametrize(
    ("intended", "observed", "expected"),
    [
        # Formatting only: still the same value.
        ("5551234567", "(555) 123-4567", True),
        ("555-123-4567", "555.123.4567", True),
        ("+1 555 123 4567", "15551234567", True),
        ("  Jane   Doe ", "jane doe", True),
        ("Full-time", "Full time", True),
        ("1000", "1,000", True),
        ("1000", "1,000.00", True),
        ("1000", "$1,000.00", True),
        ("$1000", "1000", True),
        ("1 000", "1000", True),
        ("1,000 items", "1000 items", True),
        ("-5", "-5.0", True),
        ("-$5", "-5", True),
        ("0.5", ".5", True),
        ("2024-01-05", "20240105", True),
        ("02134", "02134", True),
        ("a-b", "ab", True),
        ("A.B@X.com", "a.b@x.com", True),
        ("1.234,56", "1234.56", True),
        ("1 234,56", "1234.56", True),
        ("1.234.567", "1234567", True),
        ("2.5 kg", "2.50 kg", True),
        ("5 USD", "5", True),
        ("EUR 5", "$5.00", True),
        ("(5)", "-5", True),
        # Meaning changes: no match.
        ("a.b@x.com", "ab@x.com", False),
        ("C++", "C", False),
        ("C#", "C", False),
        ("5", "5%", False),
        ("5-", "5", False),
        ("3/4", "34", False),
        ("3-4", "34", False),
        ("1.000", "1", False),
        ("1.000", "1000", False),
        ("2.5 kg", "2.5 lb", False),
        ("2.5 kg", "2.5", False),
        ("5 USD", "5 EUR", False),
        ("(5)", "5", False),
        ("1.234,56", "123456", False),
        ("São", "Sao", False),
        ("2024-01-05", "01/05/2024", False),
        ("1.5", "15", False),
        ("-5", "5", False),
        ("1,5", "15", False),
        ("1.5", "1,5", False),
        ("1000", "1,00", False),
        ("1000", "1,001", False),
        ("12.50", "1250", False),
        ("02134", "2134", False),
        ("007", "7", False),
        ("01/02", "1/2", False),
        ("3.14", "314", False),
        ("v1.2", "v12", False),
        ("", "5", False),
    ],
)
def test_loose_value_equal_ignores_formatting_but_not_meaning(intended: str, observed: str, expected: bool) -> None:
    assert _loose_value_equal(intended, observed) is expected
    assert _loose_value_equal(observed, intended) is expected


def test_type_read_back_does_not_verify_a_shifted_decimal_or_dropped_sign() -> None:
    for typed, held in (("1.5", "15"), ("-5", "5"), ("0.75", "75")):
        result = {"active_value": held, "active_typable": True, "active_has_value": True}
        assert extension_run._type_read_back_matches({"text": typed}, result) is False
        assert extension_run._type_read_back_contradicts({"text": typed}, result) is True
        assert extension_run._vision_action_verified("type", result, {"text": typed}) is False
    result = {"active_value": "$1,000.00", "active_typable": True, "active_has_value": True}
    assert extension_run._vision_action_verified("type", result, {"text": "1000"}) is True
    assert _matching_control_readback({"value": "15"}, "1.5") == ""
    assert _matching_control_readback({"value": "1,000"}, "1000") == "1,000"


def test_browser_surface_of_a_two_surface_body_hides_desktop_only_actions_and_desktop_offers_them() -> None:
    class Both:
        def available_surfaces(self):
            return ["browser", "desktop"]

        async def switch_surface(self, target):
            return {"ok": True}

        async def vision_launch_app(self, *a, **k): ...
        async def vision_focus_window(self, *a, **k): ...
        async def vision_read_clipboard(self, *a, **k): ...
        async def vision_open_file(self, *a, **k): ...

    desktop_only = {"launch_app", "focus_window", "read_clipboard", "open_file"}
    on_browser = set(extension_run._actions_unavailable_on_body(Both(), "browser"))
    assert desktop_only <= on_browser
    assert "switch_surface" not in on_browser  # still offered, so the brain can reach the desktop
    on_desktop = set(extension_run._actions_unavailable_on_body(Both(), "desktop"))
    assert not desktop_only & on_desktop
    assert "switch_surface" not in on_desktop


def test_unavailable_actions_ride_a_dynamic_line_and_the_schema_stays_whole() -> None:
    from app import vision_agent

    # The schema (action and follow-up enums, key list, cheat sheet) is the same whatever the body cannot do:
    # a surface switch must not change the cached prefix. The unavailable names ride after the cache boundary.
    view = {"width": 800, "height": 600, "url": "http://bench.test/", "title": "t"}
    plain = vision_agent.prepare_model_input(view, {"goal": "g"})
    limited = vision_agent.prepare_model_input(view, {"goal": "g", "unavailable_actions": ["watch", "read_clipboard"]})
    assert plain["schema"] == limited["schema"]
    then_enum = limited["schema"]["schema"]["properties"]["then"]["items"]["properties"]["action"]["enum"]
    assert "watch" in then_enum and "read_clipboard" in then_enum and "click" in then_enum
    stable_plain, _, dynamic_plain = plain["system"].partition(vision_agent.SYSTEM_DYNAMIC_BOUNDARY)
    stable_limited, _, dynamic_limited = limited["system"].partition(vision_agent.SYSTEM_DYNAMIC_BOUNDARY)
    assert stable_plain == stable_limited
    assert "unavailable now" not in plain["system"]
    assert 'unavailable now: ["read_clipboard", "watch"]' in dynamic_limited


class _CaptchaBody(_OptionalSkipBody):
    """The extension refuses any action that lands in a CAPTCHA frame (captchaRefusalFor)."""

    async def vision_click_control(self, selector: str, fallback_x: int, fallback_y: int, **kwargs) -> dict:
        self.control_clicks.append((selector, fallback_x, fallback_y))
        return {"ok": False, "action": "click", "failure_reason": "captcha_requires_user", "captcha_provider": "recaptcha",
                "captcha_detected_by": "point", "activation_attempted": False, "activation_dispatched": False}


