class _RequiredEmptyFinalSubmitBody(_FinalSubmitBody):
    """The form's First name and Email are required and still empty (run 57 on Workable)."""

    def __init__(self) -> None:
        super().__init__()
        self.form_reads = 0

    async def vision_read_form(self, *, target_selector: str = "", **_kwargs) -> dict:
        self.form_reads += 1
        self.read_targets = getattr(self, "read_targets", []) + [target_selector]
        return {
            "ok": True,
            "form_target": 2,
            "form_outline": [
                {"selector": "#q", "kind": "search", "label": "Search jobs", "required": True, "form": 1},
                {"selector": "#firstname", "kind": "text", "label": "* First name", "required": True, "in_view": False, "form": 2},
                {"selector": "#email", "kind": "email", "label": "* Email", "required": True, "in_view": False, "form": 2},
                {"selector": "#headline", "kind": "text", "label": "Headline", "required": False, "in_view": True, "form": 2},
                {"selector": "#resume", "kind": "file", "label": "Resume", "required": True, "hidden": True, "form": 2},
                {"selector": "#city", "kind": "text", "label": "City", "required": True, "value": "Jersey City", "form": 2},
            ],
        }


def test_a_delegated_task_holds_its_final_submit_while_required_fields_are_empty(monkeypatch) -> None:
    init_db()
    with SessionLocal() as db:
        user = models.User(email=f"generic-required-{uuid.uuid4().hex}@example.test", name="Generic Required")
        db.add(user)
        db.flush()
        run = models.OperatorRun(user_id=user.id, goal="Apply to this job.", target_url="https://example.test/apply",
                                 current_state="RUNNING")
        db.add(run)
        db.commit()
        run_id, user_id = run.id, user.id
    body = _RequiredEmptyFinalSubmitBody()
    final_click = {"action": "click", "x": 390, "y": 442, "reason": "Submit the application."}
    decisions = iter([final_click, final_click, final_click, {"action": "done", "reason": "Submitted."}])
    db_events: list[tuple[str, dict]] = []
    contexts: list[dict] = []

    async def narrate(kind: str, data: dict) -> None:
        pass

    def decide(user_id, image, view, context):
        contexts.append(context)
        return next(decisions)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_final_action_mode_for_user", lambda user_id: "autonomous")
    monkeypatch.setattr(extension_run, "_payment_floor_verdict", lambda *args, **kwargs: {"payment": False, "deterministic_hit": False, "judge_payment": False, "summary": ""})
    monkeypatch.setattr(extension_run, "_db_event", lambda run_id, event_type, payload: db_events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_final_action_outcome_verdict", lambda *args, **kwargs: {"status": "succeeded", "confidence": 0.99, "evidence": "Thank you page."})
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=run_id, user_id=user_id, skip_navigate=True, max_steps=4))

    held = [payload for event, payload in db_events if event == "FINAL_ACTION_READINESS_BLOCKED" and payload.get("reason") == "required_fields_empty"]
    # Only the submitted form's fields: the page's required search box belongs to another form.
    assert [payload["fields"] for payload in held] == [["* First name", "* Email"], ["* First name", "* Email"]]
    assert body.read_targets and all(target for target in body.read_targets), "the read names the final target"
    assert len(body.control_clicks) == 1, "held twice, then the site's own validation is the backstop"
    assert any("final_action_withheld_required_empty" in line and "* Email" in line for line in contexts[1]["recent_actions"])


def test_empty_required_form_labels_reads_each_control_kind() -> None:
    rows = [
        {"kind": "checkbox", "label": "I agree", "required": True, "checked": False},
        {"kind": "checkbox", "label": "Newsletter", "required": True, "checked": True},
        {"kind": "radio_group", "label": "Authorized to work?", "required": True, "selected": []},
        {"kind": "select", "label": "Country", "required": True, "selected": ["United States"]},
        {"kind": "file", "label": "Resume", "required": True, "files": ["Jordan_Park_Resume.pdf"]},
        # An upload widget clears its input after sending the file (Ashby, run 61).
        {"kind": "file", "label": "Cover letter", "required": True},
        {"kind": "text", "label": "Password", "required": True, "value_redacted": True},
        {"kind": "text", "label": "Disabled", "required": True, "disabled": True},
        # A type-ahead's input is emptied once its option is chosen (Greenhouse's Location (City) chip).
        {"kind": "combobox", "label": "Location (City) *", "required": True},
        # A native select left on its placeholder: the browser says the value is missing.
        {"kind": "select", "label": "Country", "required": True, "selected": ["Choose one"], "value_missing": True},
    ]
    assert extension_run._empty_required_form_labels(rows) == ["I agree", "Authorized to work?", "Country"]


def test_a_question_whose_control_cannot_be_bound_still_reaches_the_user(monkeypatch) -> None:
    """Run 58: Catalyst's terms checkbox had no label relation. Clicking it was ungrounded (consent is the user's)
    and every question about it was refused by the binding check, so the run died. After one re-bind the question
    goes to the user unbound."""
    init_db()
    control = {**_optional_skip_control(1, question="I agree to the terms and conditions & privacy policy"),
               "tag": "input", "type": "checkbox", "text": "", "selector": "input[name='terms_and_condition']"}
    body = _OptionalSkipBody([{"controls": [control]}])
    events: list[tuple[str, dict]] = []
    ask = {"action": "ask_user", "control": 1, "question": "Do you agree to the terms and conditions & privacy policy?",
           "options": ["Yes", "No"], "reason": "Consent is the user's to give."}
    decisions = iter([dict(ask), dict(ask), dict(ask)])
    judge_calls: list[str] = []

    async def narrate(kind: str, data: dict) -> None:
        pass

    def refuse(user_id, **kwargs):
        judge_calls.append(kwargs.get("question"))
        return {"matches": False, "reason": "No label or ARIA relation ties the checkbox to the question.", "metadata": {}}

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda _run_id, event_type, payload: events.append((event_type, payload)))
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_call_target_binding_judge", refuse)
    monkeypatch.setattr(extension_run, "_decide_vision_action", lambda *args, **kwargs: next(decisions))

    summary = asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=0, user_id=0, skip_navigate=True, max_steps=4))

    assert summary["state"] == "WAITING_FOR_USER" and summary["reason"] == "needs_answer"
    assert "terms and conditions" in summary["ask"]["label"] and summary["ask"]["selector"] == ""
    assert [event for event, _payload in events].count("VISION_ASK_TARGET_BINDING_REJECTED") == 1
    assert any(event == "VISION_ASK_UNBOUND_FALLBACK" for event, _payload in events)
    assert body.mutations == 0



class _UnknownFormFinalSubmitBody(_RequiredEmptyFinalSubmitBody):
    async def vision_read_form(self, *, target_selector: str = "", **_kwargs) -> dict:
        read = await super().vision_read_form(target_selector=target_selector)
        return {**read, "form_target": None}


