def test_an_instruction_stored_while_the_loop_runs_reaches_the_brain_at_the_next_step(monkeypatch) -> None:
    init_db()
    body = _OptionalSkipBody([{"controls": [_optional_skip_control(1)]}])
    contexts: list[dict] = []
    decisions = iter([{"action": "scroll", "direction": "down", "amount": 300, "reason": "Look further."},
                      {"action": "done", "reason": "Done."}])
    stored: list[list[dict]] = [[], [{"instruction": "The Education City should be Newark.", "source": "human_review_correction"}]]

    async def narrate(kind: str, data: dict) -> None:
        pass

    def decide(user_id, image, view, context):
        contexts.append(context)
        return next(decisions)

    monkeypatch.setattr("app.candidate_context.CandidateContextEngine", _DummyContextEngine)
    monkeypatch.setattr(extension_run, "_db_event", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_record_context_usage_for_run", lambda *args, **kwargs: None)
    monkeypatch.setattr(extension_run, "_decide_vision_action", decide)
    monkeypatch.setattr(extension_run, "_run_operator_instructions", lambda run_id: stored.pop(0) if len(stored) > 1 else stored[0])

    asyncio.run(run_vision_loop(body, url=None, narrate=narrate, run_id=999999, user_id=0, skip_navigate=True, max_steps=3))

    assert len(contexts) >= 2
    assert not any("user_instruction" in line for line in contexts[0]["recent_actions"])
    assert any("user_instruction" in line and "Newark" in line for line in contexts[1]["recent_actions"])
